// Capture ordered authored endpoints once. Editing angle/side never silently rebinds them.
QJsonObject retainedAngledLine(const QJsonObject& authored,const QJsonObject& inputs) {
    auto line=inputs.value("line").toObject();
    if(line.size()!=2 || !line.contains("sketchId") || !line.contains("entityId"))return line;
    const auto features=authored.value("features").toArray();
    for(const auto& row:features)if(row.toObject().value("id")==inputs.value("featureId")) {
        const auto retained=row.toObject().value("parameters").toObject().value("source").toObject()
            .value("angled").toObject().value("line").toObject();
        if(retained.value("sketchId")==line.value("sketchId") && retained.value("entityId")==line.value("entityId"))return retained;
    }
    for(const auto& row:features)if(row.toObject().value("id")==line.value("sketchId"))
        for(const auto& value:row.toObject().value("parameters").toObject().value("entities").toArray()) {
            const auto entity=value.toObject();if(entity.value("id")!=line.value("entityId"))continue;
            if(entity.value("type")!="line")return line;
            line["startPointId"]=entity.value("startPointId");line["endPointId"]=entity.value("endPointId");return line;
        }
    return line;
}
// app.state reports progress once; rich completed results remain available via
// command.status. Repeating a full document here duplicates embedded Canvases.
QJsonObject operationProgress(const QJsonObject& operation) {
    QJsonObject result;
    for(const auto* key:{"id","command","status","evaluationPhase","evaluationStatus","previewGeneration",
        "evaluationHeartbeat","evaluationTimingMs","cancellation","previewError","resultDiscarded","recovery","sessionId"})
        if(operation.contains(key))result[key]=operation.value(key);
    return result;
}
// Preview documents are internal candidates, not a second image-download route.
// Keep the authored document and Canvas metadata intact while avoiding duplicate
// embedded images in public session/preview inspection.
QJsonValue publicPreviewDocuments(const QJsonValue& value) {
    if(value.isArray()) {
        QJsonArray result;for(const auto& item:value.toArray())result.append(publicPreviewDocuments(item));return result;
    }
    if(!value.isObject())return value;
    auto result=value.toObject();
    for(auto it=result.begin();it!=result.end();++it) {
        if(it.key()=="documentDraft" && it.value().isObject()) {
            auto draft=it.value().toObject();
            if(draft.contains("canvases")) {
                QJsonArray canvases;
                for(const auto& item:draft.value("canvases").toArray()) {
                    auto canvas=item.toObject();
                    if(canvas.value("pngBase64").isString()) {
                        canvas["pngBase64Omitted"]=QJsonObject{{"encoding","base64"},
                            {"encodedBytes",canvas.value("pngBase64").toString().size()}};
                        canvas.remove("pngBase64");
                    }
                    canvases.append(canvas);
                }
                draft["canvases"]=canvases;
            }
            it.value()=publicPreviewDocuments(draft);
        } else it.value()=publicPreviewDocuments(it.value());
    }
    return result;
}
bool hasLinkedLocalCopies(const QJsonObject& authored){
    QSet<QString> seen;for(const auto& value:authored["occurrences"].toArray()){
        const auto definition=value.toObject()["definitionId"].toString();
        if(seen.contains(definition))return true;seen.insert(definition);
    }return false;
}
bool copiedBodyDefinition(const QJsonObject& authored,const EvaluatedDocument& evaluation,const QString& bodyId){
    QString owner;for(const auto& body:evaluation.bodies)if(body.bodyId==bodyId){owner=body.ownerId;break;}
    owner=authored["objectOwners"].toObject()["bodies"].toObject().value(bodyId).toString(owner);
    if(owner.isEmpty())return false;int count=0;
    for(const auto& value:authored["occurrences"].toArray())if(value.toObject()["definitionId"]==owner)++count;
    return count>1;
}
TopoDS_Face selectedSurfaceShape(const EvaluatedDocument& evaluation,const QJsonObject& ref){
    for(const auto& body:evaluation.bodies)if(body.visible && body.summary["type"]=="surface"
        && body.bodyId==ref["bodyId"].toString() && body.supportFaces.size()==1){
        const auto& face=body.supportFaces.front();
        if(face.faceId==ref["faceId"].toString() && face.producerFeatureId==ref["producerFeatureId"].toString())return face.face;
    }
    return {};
}
class BrowserTree final : public QTreeWidget {
public:
    using QTreeWidget::QTreeWidget;
    std::function<bool(QTreeWidgetItem*,QTreeWidgetItem*)> moveRequested;
    std::function<void()> copyRequested,pasteRequested;
protected:
    void keyPressEvent(QKeyEvent* event) override {
        if(event->matches(QKeySequence::Copy) && copyRequested){copyRequested();event->accept();return;}
        if(event->matches(QKeySequence::Paste) && pasteRequested){pasteRequested();event->accept();return;}
        QTreeWidget::keyPressEvent(event);
    }
    void startDrag(Qt::DropActions) override {
        if(!currentItem())return;
        auto* drag=new QDrag(this);auto* mime=new QMimeData;
        mime->setData("application/x-alloy-browser-object",QByteArray("move"));drag->setMimeData(mime);
        drag->exec(Qt::MoveAction);
    }
    void dragEnterEvent(QDragEnterEvent* event) override {
        if(event->source()==this && event->mimeData()->hasFormat("application/x-alloy-browser-object"))event->acceptProposedAction();
        else event->ignore();
    }
    void dragMoveEvent(QDragMoveEvent* event) override {
        auto* target=itemAt(event->position().toPoint());
        if(event->source()==this && event->mimeData()->hasFormat("application/x-alloy-browser-object")
            && target && !target->data(0,Qt::UserRole+3).toString().isEmpty())event->acceptProposedAction();
        else event->ignore();
    }
    void dropEvent(QDropEvent* event) override {
        auto* target=itemAt(event->position().toPoint());
        if(event->source()==this && event->mimeData()->hasFormat("application/x-alloy-browser-object")
            && target && currentItem() && moveRequested && moveRequested(currentItem(),target))event->acceptProposedAction();
        else event->ignore();
    }
};
class ComponentActivationRadio final : public QRadioButton {
public:
    using QRadioButton::QRadioButton;
    std::function<void()> renameRequested;
    std::function<void(const QPoint&)> hoverRequested,dropRequested;
protected:
    void mousePressEvent(QMouseEvent* event) override {
        if(event->button()==Qt::LeftButton){pressPosition_=event->pos();pressed_=true;dragging_=false;cancelled_=false;}
        QRadioButton::mousePressEvent(event);
    }
    void mouseMoveEvent(QMouseEvent* event) override {
        if(pressed_ && (event->pos()-pressPosition_).manhattanLength()>=QApplication::startDragDistance()){
            dragging_=true;setCursor(Qt::ClosedHandCursor);
            if(hoverRequested)hoverRequested(event->globalPosition().toPoint());
            event->accept();return;
        }
        QRadioButton::mouseMoveEvent(event);
    }
    void mouseReleaseEvent(QMouseEvent* event) override {
        if(event->button()==Qt::LeftButton && cancelled_){cancelled_=false;setDown(false);event->accept();return;}
        if(event->button()==Qt::LeftButton && dragging_){
            pressed_=false;dragging_=false;setDown(false);unsetCursor();
            if(dropRequested)dropRequested(event->globalPosition().toPoint());
            event->accept();return;
        }
        pressed_=false;QRadioButton::mouseReleaseEvent(event);
    }
    void mouseDoubleClickEvent(QMouseEvent* event) override {
        if(renameRequested){renameRequested();event->accept();return;}
        QRadioButton::mouseDoubleClickEvent(event);
    }
    void keyPressEvent(QKeyEvent* event) override {
        if(event->key()==Qt::Key_Escape && dragging_){pressed_=false;dragging_=false;cancelled_=true;setDown(false);unsetCursor();event->accept();return;}
        QRadioButton::keyPressEvent(event);
    }
private:
    QPoint pressPosition_;
    bool pressed_=false,dragging_=false,cancelled_=false;
};
