    connect(tree_, &QTreeWidget::itemClicked, this, [this](QTreeWidgetItem* item, int) {
        if(!item || item->isHidden() || !(item->flags()&Qt::ItemIsEnabled))return;
        if(!pendingBrowserVisibility_.isEmpty() && item->data(0,Qt::UserRole+2).toString()==pendingBrowserVisibility_)return;
        const auto jointCommand=session_.value("command").toString();
        const auto jointRole=session_.value("selectionRole").toString();
        if((jointCommand=="joint.revolute" || jointCommand=="joint.cylindrical")
            && (jointRole=="component1" || jointRole=="component2")){
            const auto occurrence=item->data(0,Qt::UserRole+8).toString();
            if(!occurrence.isEmpty()){
                const auto response=execute("joint.componentPick",{{"occurrenceId",occurrence}});
                if(!response["ok"].toBool())statusBar()->showMessage(response["error"].toObject()["message"].toString(),5000);
                return;
            }
        }
        const auto name=item->data(0,Qt::UserRole).toString();
        const auto namedView=item->data(0,Qt::UserRole+9).toString();
        const auto body=item->data(0,Qt::UserRole+1).toString();
        const auto sketch=(item->parent() && item->parent()->data(0,Qt::UserRole+4)=="sketches") ? item->data(0,Qt::UserRole+2).toString() : QString{};
        const auto plane=(item->data(0,Qt::UserRole+11)!="axis" && item->parent() && item->parent()->data(0,Qt::UserRole+4)=="planes") ? item->data(0,Qt::UserRole+2).toString() : QString{};
        if(name=="home")execute("view.home");
        else if(!namedView.isEmpty())execute("view.namedRestore",{{"viewId",namedView}});
        else if(!name.isEmpty())execute("view.orientation",{{"name",name}});
        else if(!body.isEmpty()){
            if(tree_->selectedItems().size()<=1)
                execute("selection.set",{{"bodyId",body},{"occurrenceId",item->data(0,Qt::UserRole+8).toString()}});
        }
        else if(!sketch.isEmpty())execute("selection.sketchSet",{{"sketchId",sketch}});
        else if(!plane.isEmpty())execute("selection.planeSet",{{"planeId",plane}});
    });
    connect(tree_,&QTreeWidget::itemChanged,this,[this](QTreeWidgetItem* item,int column){
        if(item && column==0 && item->parent()==namedViewsNode_ && !item->data(0,Qt::UserRole+9).toString().isEmpty()) {
            const auto id=item->data(0,Qt::UserRole+9).toString();
            const auto tabId=activeTabId_,documentId=document_->authored()["documentId"].toString();
            if(item->data(0,Qt::UserRole+10)!=documentId)return;
            const auto response=execute("view.namedRename",{{"viewId",id},{"name",item->text(0)}});
            if(!response.value("ok").toBool()) {
                if(tabId==activeTabId_ && documentId==document_->authored()["documentId"]) {
                    const QSignalBlocker block(tree_);
                    for(const auto& row:document_->authored()["namedViews"].toArray())if(row.toObject()["id"]==id)
                        item->setText(0,row.toObject()["name"].toString());
                }
                statusBar()->showMessage(response.value("error").toObject().value("message").toString(),5000);
            }
            return;
        }
        if(!item || item->isHidden() || !(item->flags()&Qt::ItemIsEnabled) || column!=0 ||
            (!item->parent() || item->parent()->data(0,Qt::UserRole+4).toString().isEmpty()) ||
            item->parent()->data(0,Qt::UserRole+4)=="instanceBodies")return;
        const auto id=item->data(0,Qt::UserRole+2).toString();const bool visible=item->checkState(0)==Qt::Checked;
        if(item->parent()==canvasesNode_){const auto id=item->data(0,Qt::UserRole+2).toString();const bool visible=item->checkState(0)==Qt::Checked;const auto tabId=activeTabId_;QTimer::singleShot(0,this,[this,id,visible,tabId]{if(tabId==activeTabId_)execute("canvas.set",{{"canvasId",id},{"visible",visible}});});return;}
        if(item->parent()==analysesNode_){
            const auto tabId=activeTabId_;QTimer::singleShot(0,this,[this,id,visible,tabId]{if(tabId==activeTabId_)execute("analysis.visibility",{{"analysisId",id},{"visible",visible}});});return;
        }
        pendingBrowserVisibility_=id;
        const auto tabId=activeTabId_,sessionId=session_.value("id").toString();
        // A checkbox changes before Qt emits itemClicked for this same item.
        // Rebuilding the Browser inside that event would invalidate Qt's pointer.
        QTimer::singleShot(0,this,[this,id,visible,tabId,sessionId]{
            if(tabId!=activeTabId_ || sessionId!=session_.value("id").toString())return;
            if(pendingBrowserVisibility_==id)pendingBrowserVisibility_.clear();
            const auto response=execute("feature.visibility",{{"featureId",id},{"visible",visible}});
            if(!response["ok"].toBool()) {
                const QSignalBlocker block(tree_);
                for(QTreeWidgetItemIterator it(tree_);*it;++it) {
                    auto* current=*it;if(current->data(0,Qt::UserRole+2).toString()!=id)continue;
                    for(const auto& entry:document_->authored()["features"].toArray()) {
                        const auto feature=entry.toObject();if(feature["id"]==id)current->setCheckState(0,feature["visible"].toBool() ? Qt::Checked : Qt::Unchecked);
                    }
                }
            }
        });
    });
    connect(tree_,&QTreeWidget::itemDoubleClicked,this,[this,wireNamedViewReturn](QTreeWidgetItem* item,int) {
        if(!item || item->isHidden() || !(item->flags()&Qt::ItemIsEnabled))return;
        if(item->parent()==namedViewsNode_ && !item->data(0,Qt::UserRole+9).toString().isEmpty()) {
            wireNamedViewReturn(item,false);
            return;
        }
        const auto occurrence=item->data(0,Qt::UserRole+8).toString();
        if(!occurrence.isEmpty() && !item->data(0,Qt::UserRole+3).toString().isEmpty()){
            QTimer::singleShot(0,this,[this,occurrence]{execute("component.renameDialog",{{"occurrenceId",occurrence}});});return;
        }
        const auto feature=item->data(0,Qt::UserRole+6).toString().isEmpty() ? item->data(0,Qt::UserRole+2).toString() : item->data(0,Qt::UserRole+6).toString();
        if(item->parent()==jointsNode_){const auto id=item->data(0,Qt::UserRole+5).toString();QString kind;
            for(const auto& value:document_->authored().value("joints").toArray())if(value.toObject()["id"]==id)kind=value.toObject()["type"].toString();
            execute(kind=="asBuiltCylindrical" ? "joint.cylindricalDialog"
                : kind=="asBuiltRevolute" ? "joint.revoluteDialog" : "joint.sliderDialog",{{"jointId",id}});return;}
        const auto tabId=activeTabId_;
        if(!feature.isEmpty())QTimer::singleShot(0,this,[this,feature,tabId]{if(tabId!=activeTabId_)return;
            const auto result=execute("feature.editDialog",{{"featureId",feature}});
            if(!result["ok"].toBool())statusBar()->showMessage(result["error"].toObject()["message"].toString(),6000);
        });
    });
