        if(session_.contains("pendingProject"))execute("sketch.projectCancel");
        cancelConicInput();
        session_.remove("pendingLineArc");view_->clearSketchLineArcDrag();if(lineLockCue_)lineLockCue_->hide();
        cancelSlotDrag();
