QJsonObject AlloyWindow::previewSplineOffset(const QJsonObject& inputs) {
    if(session_.value("command")!="sketch.edit" || session_.value("tool")!="offset")
        return failure("no_offset_tool","Activate sketch Offset first");
    if(inputs.contains("session") && inputs["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))
        return failure("stale_session","The document changed; cancel and restart this sketch");
    const auto draft=session_.value("draftSketch").toObject(),context=session_.value("projectionContext").toObject();
    const auto selected=session_.value("selection").toObject()["entityIds"].toArray();
    const auto previous=session_.value("pendingSplineOffset").toObject();
    auto sourceId=inputs.value("sourceEntityId").toString(previous.value("offsetEntityId").toString(previous.value("sourceEntityId").toString(
        selected.size()==1 ? selected.first().toString() : QString{})));
    QJsonObject existing;bool sourceFound=false;QString explicitOffsetId;
    for(const auto& value:draft["parameters"].toObject()["entities"].toArray()){
        const auto entity=value.toObject();
        if(entity["id"]==sourceId && entity["type"]=="fitSplineOffset"){
            existing=entity;explicitOffsetId=entity["id"].toString();sourceId=entity["sourceEntityId"].toString();
        }
    }
    for(const auto& value:draft["parameters"].toObject()["entities"].toArray()){
        const auto entity=value.toObject();
        if(entity["id"]==sourceId && entity["type"]=="fitSpline")sourceFound=true;
        if(entity["type"]=="fitSplineOffset" && entity["sourceEntityId"]==sourceId){
            if(!explicitOffsetId.isEmpty())continue;
            if(!existing.isEmpty())
                return failure("ambiguous_offset","Select the retained offset entity to edit its distance");
            existing=entity;
        }
    }
    if(!sourceFound)return failure("source_required","Select one authored open fit spline");
    const auto units=inputs.value("units").toString(session_.value("inputs").toObject()["units"].toString());
    double distance=inputs.contains("distance") ? CadDocument::millimeters(inputs["distance"].toDouble(),units)
        : previous["sourceEntityId"]==sourceId ? previous.value("distanceMm").toDouble(-5)
        : existing.isEmpty() ? -5 : existing["signedDistanceMm"].toDouble();
    if(inputs.value("flip").toBool())distance=-distance;
    const auto solved=existing.isEmpty() ? SketchSplineOffset::add(draft,{{"sourceEntityId",sourceId},{"signedDistanceMm",distance}},context)
        : SketchSplineOffset::update(draft,{{"offsetEntityId",existing["id"]},{"signedDistanceMm",distance}},context);
    QJsonObject pending{{"sourceEntityId",sourceId},{"distanceMm",distance},{"valid",solved.ok}};
    if(!existing.isEmpty())pending["offsetEntityId"]=existing["id"];
    if(!solved.ok){
        pending["error"]=solved.error;session_["pendingSplineOffset"]=pending;
        view_->showSketchDraft(evaluateSketchDraft(draft));displayedSketchDraft_=draft;
        return failure("invalid_spline_offset",solved.error);
    }
    try{
        const auto evaluated=evaluateSketchDraft(solved.feature);
        pending["previewDraft"]=solved.feature;session_["pendingSplineOffset"]=pending;
        view_->showSketchDraft(evaluated);displayedSketchDraft_=draft;
        return {{"pendingSplineOffset",pending},{"sketchGeometry",evaluated.summary},{"authoredChange",false}};
    }catch(const std::exception& error){return failure("preview_failed",QString::fromUtf8(error.what()));}
}

QJsonObject AlloyWindow::acceptSplineOffset(const QJsonObject& inputs){
    if(!inputs.isEmpty()){
        const auto preview=previewSplineOffset(inputs);
        if(preview.value("ok").isBool() && !preview["ok"].toBool())return preview;
    }
    const auto pending=session_.value("pendingSplineOffset").toObject();
    if(session_.value("tool")!="offset" || !pending["valid"].toBool())
        return failure("no_valid_offset_preview","Select a fit spline and preview a valid signed distance first");
    const bool editing=pending.contains("offsetEntityId");
    const auto result=appendSplineOffset(editing
        ? QJsonObject{{"offsetEntityId",pending["offsetEntityId"]},{"distance",pending["distanceMm"]},{"units","mm"}}
        : QJsonObject{{"sourceEntityId",pending["sourceEntityId"]},{"distance",pending["distanceMm"]},{"units","mm"}},editing);
    if(!result.value("ok").isBool() || result["ok"].toBool()){
        cancelSplineOffset();session_["tool"]="select";view_->setFocus();
    }
    return result;
}

void AlloyWindow::cancelSplineOffset(){
    if(!session_.contains("pendingSplineOffset"))return;
    session_.remove("pendingSplineOffset");const auto draft=session_.value("draftSketch").toObject();
    if(!draft.isEmpty()){view_->showSketchDraft(evaluateSketchDraft(draft));displayedSketchDraft_=draft;}
}

QJsonObject AlloyWindow::previewClosedRectOffset(const QJsonObject& inputs){
    if(session_.value("command")!="sketch.edit" || session_.value("tool")!="offset")
        return failure("no_offset_tool","Activate sketch Offset first");
    if(inputs.contains("session") && inputs["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))
        return failure("stale_session","The document changed; restart the sketch");
    if(inputs.contains("parameterName"))return failure("unsupported_parameter","Closed rectangle Offset currently accepts a numeric signed distance");
    const auto previous=session_.value("pendingClosedRectOffset").toObject();
    const auto sources=inputs.contains("sourceEntityIds") ? inputs["sourceEntityIds"].toArray()
        : previous.contains("sourceEntityIds") ? previous["sourceEntityIds"].toArray()
        : session_.value("selection").toObject()["entityIds"].toArray();
    const auto units=inputs.value("units").toString(session_.value("inputs").toObject()["units"].toString());
    double distance=inputs.contains("distance") ? CadDocument::millimeters(inputs["distance"].toDouble(),units)
        : previous.value("distanceMm").toDouble(1);
    if(inputs.value("flip").toBool())distance=-distance;
    auto pending=QJsonObject{{"sourceEntityIds",sources},{"distanceMm",distance},{"valid",false}};
    const auto original=session_.value("draftSketch").toObject(),context=session_.value("projectionContext").toObject();
    const auto solved=SketchGeometry::addClosedRectOffset(original,sources,distance,context);
    if(!solved.ok){pending["error"]=solved.error;session_["pendingClosedRectOffset"]=pending;
        view_->showSketchDraft(evaluateSketchDraft(original));displayedSketchDraft_=original;
        return failure("invalid_closed_offset",solved.error);
    }
    try {
        const auto evaluated=SketchGeometry::evaluateFeature(solved.feature,session_["resolvedFrame"].toObject(),context);
        pending["valid"]=true;pending["previewDraft"]=solved.feature;pending["previewGeometry"]=evaluated.summary;
        session_.remove("pendingOpenChainOffset");session_["pendingClosedRectOffset"]=pending;
        view_->showSketchDraft(evaluated);displayedSketchDraft_=original;
        return {{"pendingClosedRectOffset",pending},{"sketchGeometry",evaluated.summary},{"authoredChange",false}};
    } catch(const std::exception& error){pending["error"]=QString::fromUtf8(error.what());session_["pendingClosedRectOffset"]=pending;
        view_->showSketchDraft(evaluateSketchDraft(original));displayedSketchDraft_=original;
        return failure("invalid_closed_offset",QString::fromUtf8(error.what()));}
}

QJsonObject AlloyWindow::acceptClosedRectOffset(const QJsonObject& inputs){
    if(!inputs.isEmpty()){const auto preview=previewClosedRectOffset(inputs);if(preview.value("ok").isBool() && !preview["ok"].toBool())return preview;}
    const auto pending=session_.value("pendingClosedRectOffset").toObject();
    if(!pending["valid"].toBool())return failure("no_valid_offset_preview","Preview a valid closed rectangle offset first");
    const auto solved=SketchGeometry::solveDraft(pending["previewDraft"].toObject(),session_.value("projectionContext").toObject());
    if(!solved.ok)return failure("invalid_closed_offset",solved.error);
    auto result=publishSketchSolve(solved);
    if(!result.value("ok").isBool() || result["ok"].toBool()){
        session_.remove("pendingClosedRectOffset");session_["tool"]="select";view_->setFocus();}
    return result;
}

void AlloyWindow::cancelClosedRectOffset(){
    if(!session_.contains("pendingClosedRectOffset"))return;
    session_.remove("pendingClosedRectOffset");const auto draft=session_.value("draftSketch").toObject();
    if(!draft.isEmpty()){view_->showSketchDraft(evaluateSketchDraft(draft));displayedSketchDraft_=draft;}
}

QJsonObject AlloyWindow::previewOpenChainOffset(const QJsonObject& inputs){
    if(session_.value("command")!="sketch.edit" || session_.value("tool")!="offset")
        return failure("no_offset_tool","Activate sketch Offset first");
    if(inputs.contains("session") && inputs["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))
        return failure("stale_session","The document changed; cancel and restart this sketch");
    if(inputs.contains("distance") && inputs.contains("parameterName"))
        return failure("invalid_arguments","Supply a signed numeric distance or one direct length name");
    const auto draft=session_.value("draftSketch").toObject(),context=session_.value("projectionContext").toObject();
    const auto previous=session_.value("pendingOpenChainOffset").toObject();
    const auto expanded=SketchGeometry::expandedProjectionFeature(draft,context)["parameters"].toObject();
    QJsonObject existing;
    for(const auto& value:draft["parameters"].toObject()["openChainOffsets"].toArray())existing=value.toObject();
    auto sources=inputs.value("sourceEntityIds").toArray(previous.value("sourceEntityIds").toArray(
        existing.value("sourceEntityIds").toArray(session_.value("selection").toObject()["entityIds"].toArray())));
    auto topId=inputs.value("topEntityId").toString(previous.value("topEntityId").toString(
        existing.value("topEntityId").toString()));
    const auto units=inputs.value("units").toString(session_.value("inputs").toObject()["units"].toString());
    double signedDistance=inputs.contains("distance") ? CadDocument::millimeters(inputs["distance"].toDouble(),units)
        : previous.contains("distanceMm") ? previous["distanceMm"].toDouble()
        : existing.contains("signedDistanceMm") ? existing["signedDistanceMm"].toDouble() : -0.25;
    QString parameterId=previous.value("distanceParameterId").toString(existing.value("distanceParameterId").toString());
    if(inputs.contains("distance"))parameterId.clear();
    if(inputs.contains("parameterName")){
        const auto row=lengthParameter(inputs["parameterName"].toString());
        if(row.isEmpty()){
            session_["pendingOpenChainOffset"]=QJsonObject{{"sourceEntityIds",sources},{"topEntityId",topId},
                {"distanceMm",signedDistance},{"valid",false},{"error","User length name is unavailable"}};
            view_->showSketchDraft(evaluateSketchDraft(draft));displayedSketchDraft_=draft;
            return failure("unknown_parameter","User length name is unavailable","parameterName");
        }
        parameterId=row["id"].toString();signedDistance=(signedDistance<0 ? -1 : 1)*row["valueMm"].toDouble();
    }
    if(inputs.value("flip").toBool())signedDistance=-signedDistance;
    QJsonObject pending{{"sourceEntityIds",sources},{"topEntityId",topId},{"distanceMm",signedDistance},
        {"valid",false}};
    if(!existing.isEmpty())pending["offsetId"]=existing["id"];
    if(!parameterId.isEmpty())pending["distanceParameterId"]=parameterId;
    try{
        if(sources.size()!=5){
            pending["error"]="Select five connected lines: both shoulders, both slants and bottom";
            session_["pendingOpenChainOffset"]=pending;
            view_->showSketchDraft(evaluateSketchDraft(draft));displayedSketchDraft_=draft;
            return failure("source_required",pending["error"].toString());
        }
        QMap<QString,QPair<QPointF,QPointF>> lines;QMap<QString,QPointF> points;
        for(const auto& value:expanded["points"].toArray()){
            const auto p=value.toObject();points[p["id"].toString()]={p["uMm"].toDouble(),p["vMm"].toDouble()};}
        for(const auto& value:expanded["entities"].toArray()){
            const auto e=value.toObject();if(e["type"]!="line")continue;
            lines[e["id"].toString()]={points[e["startPointId"].toString()],points[e["endPointId"].toString()]};}
        const auto sketchPointNear=[](const QPointF& a,const QPointF& b){return std::hypot(a.x()-b.x(),a.y()-b.y())<1e-6;};
        // API order is authoritative. Native selection is unordered; resolve its
        // two free ends deterministically without walking an unselected branch.
        if(!inputs.contains("sourceEntityIds") && existing.isEmpty()){
            struct End{QString id;QPointF p;};QVector<End> free;
            for(const auto& value:sources){const auto id=value.toString();if(!lines.contains(id))continue;
                for(const auto& p:{lines[id].first,lines[id].second}){
                    int degree=0;for(const auto& other:sources){const auto endpoints=lines.value(other.toString());
                        degree+=sketchPointNear(p,endpoints.first)+sketchPointNear(p,endpoints.second);}
                    if(degree==1)free.append({id,p});
                }}
            if(free.size()!=2)throw std::invalid_argument("Offset selection must be one unbranched open chain");
            std::sort(free.begin(),free.end(),[](const End& a,const End& b){return a.p.x()==b.p.x()?a.p.y()<b.p.y():a.p.x()<b.p.x();});
            QJsonArray ordered;QSet<QString> used;QPointF at=free.front().p;
            for(int i=0;i<5;++i){QString next;QPointF nextPoint;
                for(const auto& value:sources){const auto id=value.toString();if(used.contains(id)||!lines.contains(id))continue;
                    const auto ends=lines[id];if(sketchPointNear(at,ends.first)||sketchPointNear(at,ends.second)){
                        if(!next.isEmpty())throw std::invalid_argument("Offset selection branches");
                        next=id;nextPoint=sketchPointNear(at,ends.first)?ends.second:ends.first;}}
                if(next.isEmpty())throw std::invalid_argument("Offset selection is disconnected");
                used.insert(next);ordered.append(next);at=nextPoint;}
            sources=ordered;pending["sourceEntityIds"]=sources;
        }
        if(topId.isEmpty()){
            const auto a=lines.value(sources[0].toString()),b=lines.value(sources[1].toString());
            const auto c=lines.value(sources[3].toString()),d=lines.value(sources[4].toString());
            const auto left=sketchPointNear(a.first,b.first)||sketchPointNear(a.first,b.second)?a.first:a.second;
            const auto right=sketchPointNear(d.first,c.first)||sketchPointNear(d.first,c.second)?d.first:d.second;
            for(auto it=lines.begin();it!=lines.end();++it){if(sources.contains(it.key()))continue;
                if((sketchPointNear(it.value().first,left)&&sketchPointNear(it.value().second,right)) ||
                   (sketchPointNear(it.value().first,right)&&sketchPointNear(it.value().second,left))){
                    if(!topId.isEmpty())throw std::invalid_argument("Original top line is ambiguous");topId=it.key();}}
            pending["topEntityId"]=topId;
        }
        QJsonObject args{{"sourceEntityIds",sources},{"signedDistanceMm",signedDistance}};
        if(!topId.isEmpty())args["topEntityId"]=topId;
        if(!parameterId.isEmpty()){args["distanceParameterId"]=parameterId;args["sideSign"]=signedDistance<0 ? -1 : 1;}
        QJsonObject updateArgs{{"offsetId",existing.value("id")},{"signedDistanceMm",signedDistance}};
        if(!parameterId.isEmpty()){updateArgs["distanceParameterId"]=parameterId;updateArgs["sideSign"]=signedDistance<0 ? -1 : 1;}
        auto candidate=existing.isEmpty() ? SketchOpenChainOffset::add(draft,expanded,args)
            : SketchOpenChainOffset::update(draft,expanded,updateArgs);
        const auto solved=SketchGeometry::solveDraft(candidate,context);
        if(!solved.ok)throw std::invalid_argument(solved.error.toUtf8().constData());
        const auto evaluated=evaluateSketchDraft(solved.feature);
        pending["valid"]=true;pending["previewDraft"]=solved.feature;
        session_["pendingOpenChainOffset"]=pending;
        view_->showSketchDraft(evaluated);displayedSketchDraft_=draft;
        return {{"pendingOpenChainOffset",pending},{"sketchGeometry",evaluated.summary},{"authoredChange",false}};
    }catch(const std::exception& e){
        pending["error"]=QString::fromUtf8(e.what());session_["pendingOpenChainOffset"]=pending;
        view_->showSketchDraft(evaluateSketchDraft(draft));displayedSketchDraft_=draft;
        return failure("invalid_open_chain_offset",pending["error"].toString());
    }
}

QJsonObject AlloyWindow::acceptOpenChainOffset(const QJsonObject& inputs){
    if(!inputs.isEmpty()){
        const auto preview=previewOpenChainOffset(inputs);
        if(preview.value("ok").isBool() && !preview["ok"].toBool())return preview;
    }
    const auto pending=session_.value("pendingOpenChainOffset").toObject();
    if(!pending["valid"].toBool())return failure("no_valid_offset_preview","Preview a valid five-line open chain first");
    const auto candidate=pending["previewDraft"].toObject();
    const auto result=publishSketchSolve(SketchGeometry::solveDraft(candidate,session_.value("projectionContext").toObject()));
    if(!result.value("ok").isBool() || result["ok"].toBool()){
        cancelOpenChainOffset();session_["tool"]="select";view_->setFocus();}
    return result;
}

void AlloyWindow::cancelOpenChainOffset(){
    if(!session_.contains("pendingOpenChainOffset"))return;
    session_.remove("pendingOpenChainOffset");const auto draft=session_.value("draftSketch").toObject();
    if(!draft.isEmpty()){view_->showSketchDraft(evaluateSketchDraft(draft));displayedSketchDraft_=draft;}
}

EvaluatedSketch AlloyWindow::evaluateSketchDraft(const QJsonObject& draft) const {
    if(!draft["parameters"].toObject().contains("loopOffsets"))
        return SketchGeometry::evaluateFeature(draft,session_.value("resolvedFrame").toObject(),session_.value("projectionContext").toObject());
    const auto editId=session_.value("inputs").toObject().value("sketchId").toString();
    const auto history=editId.isEmpty() ? document_->evaluation() : sketchHistoryStage(editId);
    return RoundedLoopOffset::evaluate(draft,
        GeometryKernel::resolveSketchSupport(history,draft["parameters"].toObject()["support"].toObject()),
        GeometryKernel::sketchFrame(history,draft));
}

QJsonObject AlloyWindow::previewLoopOffset(const QJsonObject& inputs) {
    if(session_.value("command")!="sketch.edit" || session_.value("tool")!="offset" || session_.value("inputs").toObject()["plane"]!="face")
        return failure("no_offset_tool","Activate Offset in a supported face sketch first");
    if(inputs.contains("session") && inputs["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))return failure("stale_session","Document changed; restart the sketch");
    const auto original=session_.value("draftSketch").toObject(),p=original["parameters"].toObject();
    const auto rejectPending=[&](const QString& code,const QString& message) {
        if(session_.contains("pendingLoopOffset")) {
            session_.remove("pendingLoopOffset");
            view_->showSketchDraft(evaluateSketchDraft(original));displayedSketchDraft_=original;
        }
        return failure(code,message);
    };
    if(inputs.contains("chain") && !inputs["chain"].toBool())
        return rejectPending("chain_required","Check Chain Selection for the whole closed boundary");
    if(!p["entities"].toArray().isEmpty() || !p["points"].toArray().isEmpty())
        return rejectPending("unsupported_offset_sketch","Use a generated-only face sketch for retained loop offsets");
    auto pending=session_.value("pendingLoopOffset").toObject();
    const auto support=p["support"].toObject();
    try {
        const auto editId=session_.value("inputs").toObject().value("sketchId").toString();
        const auto history=editId.isEmpty() ? document_->evaluation() : sketchHistoryStage(editId);
        const auto resolved=GeometryKernel::resolveSketchSupport(history,support);
        QString kind=inputs.value("kind").toString(pending.value("kind").toString());
        QString loop;
        if(kind.isEmpty() && !inputs.contains("kind")) {
            try {loop=RoundedLoopOffset::outerLoopId(resolved);}
            catch(const GeometryKernel::EvaluationError& error) {
                if(error.diagnostics().value("code")!="unsupported_offset_boundary")throw;
                kind="planarInsetV1";loop=RoundedLoopOffset::insetLoopId(resolved);
            }
        } else if(kind=="planarInsetV1")loop=RoundedLoopOffset::insetLoopId(resolved);
        else return rejectPending("unsupported_offset_kind","Unknown retained loop offset variant");
        if(inputs.contains("outerLoopId") && inputs["outerLoopId"].toString()!=loop)
            return rejectPending("offset_lineage_unavailable","Selected boundary is not the retained outer loop");
        if(!pending.isEmpty() && (pending["outerLoopId"]!=loop || pending.value("kind").toString()!=kind))
            return rejectPending("offset_lineage_unavailable","Selected loop or inset variant changed during preview");
        const auto units=inputs.value("units").toString(session_.value("inputs").toObject()["units"].toString());
        const double distance=inputs.contains("distance") ? CadDocument::millimeters(inputs["distance"].toDouble(),units)
            : pending.value("distanceMm").toDouble(kind=="planarInsetV1" ? -1.25 : -1.5);
        const double signedDistance=inputs.value("flip").toBool() ? -distance : distance;
        if(kind=="planarInsetV1" && signedDistance>0)
            return rejectPending("unsupported_inset_side","Trimmed planar inset requires an inward signed distance");
        pending={{"id",pending.value("id").toString(CadDocument::newId())},{"outerLoopId",loop},{"distanceMm",signedDistance},{"chain",true},{"valid",false}};
        if(!kind.isEmpty())pending["kind"]=kind;
        auto candidate=original,parameters=p;parameters.remove("projections");parameters.remove("pointReferences");
        QJsonObject authored{{"id",pending["id"]},{"outerLoopId",loop},{"distanceMm",signedDistance},{"chain",true}};
        if(!kind.isEmpty())authored["kind"]=kind;
        auto owners=p.value("loopOffsets").toArray();owners.append(authored);parameters["loopOffsets"]=owners;
        candidate["parameters"]=parameters;
        const auto solved=SketchGeometry::solveDraft(candidate);
        if(!solved.ok)throw GeometryKernel::EvaluationError({{"code","invalid_loop_offset"},{"message",solved.error}});
        const auto evaluated=RoundedLoopOffset::evaluate(solved.feature,resolved,
            GeometryKernel::sketchFrame(history,solved.feature));
        pending["valid"]=true;pending["previewDraft"]=solved.feature;pending["previewGeometry"]=evaluated.summary;
        session_["pendingLoopOffset"]=pending;view_->showSketchDraft(evaluated);displayedSketchDraft_=original;
        return {{"pendingLoopOffset",pending},{"sketchGeometry",evaluated.summary},{"authoredChange",false}};
    } catch(const GeometryKernel::EvaluationError& error) {
        pending["valid"]=false;pending["error"]=error.diagnostics();session_["pendingLoopOffset"]=pending;
        view_->showSketchDraft(evaluateSketchDraft(original));displayedSketchDraft_=original;
        return failure(error.diagnostics()["code"].toString(),QString::fromUtf8(error.what()));
    } catch(const std::exception& error) {
        return rejectPending("invalid_loop_offset",QString::fromUtf8(error.what()));
    }
}

QJsonObject AlloyWindow::acceptLoopOffset(const QJsonObject& inputs) {
    if(!inputs.isEmpty()){const auto result=previewLoopOffset(inputs);if(result.value("ok").isBool() && !result["ok"].toBool())return result;}
    const auto pending=session_.value("pendingLoopOffset").toObject();
    if(!pending["valid"].toBool())return failure("no_valid_offset_preview","Select the boundary and preview a valid signed distance");
    const auto solved=SketchGeometry::solveDraft(pending["previewDraft"].toObject());
    if(!solved.ok)return failure("invalid_loop_offset",solved.error);
    const auto result=publishSketchSolve(solved);
    if(!result.value("ok").isBool() || result["ok"].toBool()){session_.remove("pendingLoopOffset");session_["tool"]="select";view_->setFocus();}
    return result;
}

QJsonObject AlloyWindow::updateLoopOffset(const QJsonObject& inputs) {
    if(session_.value("command")!="sketch.edit")return failure("no_active_sketch","Enter the offset sketch first");
    if(inputs.contains("session") && inputs["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    const auto original=session_["draftSketch"].toObject(),parameters=original["parameters"].toObject();const auto objects=parameters["loopOffsets"].toArray();
    int index=-1;
    for(int i=0;i<objects.size();++i)if(objects[i].toObject().value("id")==inputs.value("offsetId")) {
        if(index>=0)return failure("offset_unavailable","The retained loop offset identity is ambiguous");
        index=i;
    }
    if(index<0)return failure("offset_unavailable","The retained loop offset is unavailable");
    auto object=objects[index].toObject();
    const auto units=inputs.value("units").toString(session_.value("inputs").toObject()["units"].toString());
    object["distanceMm"]=CadDocument::millimeters(inputs["distance"].toDouble(),units);
    auto p=parameters;auto updated=objects;updated[index]=object;p["loopOffsets"]=updated;auto candidate=original;candidate["parameters"]=p;
    try {evaluateSketchDraft(candidate);}catch(const GeometryKernel::EvaluationError& error){return failure(error.diagnostics()["code"].toString(),QString::fromUtf8(error.what()));}
    return publishSketchSolve(SketchGeometry::solveDraft(candidate));
}

void AlloyWindow::cancelLoopOffset() {
    if(!session_.contains("pendingLoopOffset"))return;
    session_.remove("pendingLoopOffset");const auto draft=session_["draftSketch"].toObject();
    if(!draft.isEmpty()){view_->showSketchDraft(evaluateSketchDraft(draft));displayedSketchDraft_=draft;}
}

QJsonObject AlloyWindow::previewCircleOffset(const QJsonObject& inputs) {
    if(session_.value("command")!="sketch.edit" || session_.value("tool")!="offset")
        return failure("no_offset_tool","Activate sketch Offset first");
    if(inputs.contains("session") && inputs["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))
        return failure("stale_session","The document changed; cancel and restart this sketch");
    auto pending=session_.value("pendingOffset").toObject();
    const auto selected=session_.value("selection").toObject()["entityIds"].toArray();
    const auto source=inputs.value("sourceEntityId").toString(pending.value("sourceEntityId").toString(
        selected.size()==1 ? selected[0].toString() : QString{}));
    if(source.isEmpty())return failure("source_required","Select one source circle");
    const auto units=inputs.value("units").toString(session_.value("inputs").toObject()["units"].toString());
    const auto draft=session_.value("draftSketch").toObject(),context=session_.value("projectionContext").toObject();
    QJsonObject existing;
    for(const auto& value:draft["parameters"].toObject()["constraints"].toArray()) {
        const auto relation=value.toObject();
        if(relation["type"]!="circleOffset" || relation["entityIds"].toArray()[0]!=source)continue;
        if(!existing.isEmpty())return failure("ambiguous_offset","Source circle has multiple offsets; use the constraint ID API");
        existing=relation;
    }
    double distance=inputs.contains("distance") ? CadDocument::millimeters(inputs["distance"].toDouble(),units)
        : pending["sourceEntityId"]==source ? pending.value("distanceMm").toDouble(1)
        : existing.isEmpty() ? 1 : existing["distanceMm"].toDouble();
    if(inputs.value("flip").toBool())distance=-distance;
    const auto solved=existing.isEmpty()
        ? SketchGeometry::addCircleOffset(draft,{{"sourceEntityId",source},{"distanceMm",distance}},context)
        : SketchGeometry::updateCircleOffset(draft,{{"constraintId",existing["id"]},{"distanceMm",distance}},context);
    if(!solved.ok) {
        pending={{"sourceEntityId",source},{"distanceMm",distance},{"valid",false},{"error",solved.error}};
        if(!existing.isEmpty())pending["constraintId"]=existing["id"];
        session_["pendingOffset"]=pending;
        view_->showSketchDraft(SketchGeometry::evaluateFeature(draft,session_.value("resolvedFrame").toObject(),context));
        displayedSketchDraft_=draft;
        return failure("invalid_circle_offset",solved.error);
    }
    try {
        const auto evaluated=SketchGeometry::evaluateFeature(solved.feature,session_.value("resolvedFrame").toObject(),context);
        pending={{"sourceEntityId",source},{"distanceMm",distance},{"valid",true},{"previewDraft",solved.feature}};
        if(!existing.isEmpty())pending["constraintId"]=existing["id"];
        session_["pendingOffset"]=pending;view_->showSketchDraft(evaluated);
        return {{"pendingOffset",pending},{"sketchGeometry",evaluated.summary},{"authoredChange",false}};
    } catch(const std::exception& error){return failure("preview_failed",QString::fromUtf8(error.what()));}
}

QJsonObject AlloyWindow::acceptCircleOffset(const QJsonObject& inputs) {
    if(!inputs.isEmpty()) {
        const auto preview=previewCircleOffset(inputs);
        if(preview.value("ok").isBool() && !preview.value("ok").toBool())return preview;
    }
    const auto pending=session_.value("pendingOffset").toObject();
    if(session_.value("tool")!="offset" || !pending["valid"].toBool())
        return failure("no_valid_offset_preview","Select a source circle and preview a valid distance first");
    const bool editing=pending.contains("constraintId");
    const auto result=appendCircleOffset(editing
        ? QJsonObject{{"constraintId",pending["constraintId"]},{"distance",pending["distanceMm"]},{"units","mm"}}
        : QJsonObject{{"sourceEntityId",pending["sourceEntityId"]},{"distance",pending["distanceMm"]},{"units","mm"}},editing);
    if(!result.value("ok").isBool() || result.value("ok").toBool()) {
        cancelCircleOffset();session_["tool"]="select";view_->setFocus();
    }
    return result;
}

void AlloyWindow::cancelCircleOffset() {
    if(!session_.contains("pendingOffset"))return;
    session_.remove("pendingOffset");
    const auto draft=session_.value("draftSketch").toObject();
    if(!draft.isEmpty()) {
        view_->showSketchDraft(SketchGeometry::evaluateFeature(draft,session_.value("resolvedFrame").toObject(),
            session_.value("projectionContext").toObject()));
        displayedSketchDraft_=draft;
    }
}

QJsonObject AlloyWindow::resolveSketchSnap(double x,double y,const QString& plane,bool includeMidpoints,
    bool preferFaceCurveCenterAtOrigin) const {
    auto point=view_->sketchPoint(x,y,plane);
    constexpr double radiusPx=10.0,ambiguityPx=0.5;
    QJsonObject result{{"status","none"},{"uMm",point["uMm"]},{"vMm",point["vMm"]},{"radiusPx",radiusPx},{"authoredChange",false}};
    const auto parameters=session_.value("draftSketch").toObject()["parameters"].toObject();
    QMap<QString,QJsonObject> points;for(const auto& entry:parameters["points"].toArray()){const auto p=entry.toObject();points[p["id"].toString()]=p;}
    std::vector<QJsonObject> candidates;
    auto offer=[&](const QJsonObject& target,double u,double v){
        const auto screen=view_->projectSketchPoint(u,v,plane);const double distance=std::hypot(screen["x"].toDouble()-x,screen["y"].toDouble()-y);
        if(distance<=radiusPx)candidates.push_back(QJsonObject{{"target",target},{"uMm",u},{"vMm",v},{"distancePx",distance}});
    };
    if(includeMidpoints) {
        for(const auto& entry:parameters["entities"].toArray()) {
            const auto line=entry.toObject();if(line["type"]!="line")continue;
            const auto first=points.value(line["startPointId"].toString()),second=points.value(line["endPointId"].toString());
            if(first.isEmpty() || second.isEmpty())continue;
            const double u=(first["uMm"].toDouble()+second["uMm"].toDouble())/2;
            const double v=(first["vMm"].toDouble()+second["vMm"].toDouble())/2;
            if(std::hypot(first["uMm"].toDouble()-second["uMm"].toDouble(),first["vMm"].toDouble()-second["vMm"].toDouble())<1e-9)continue;
            offer({{"kind","midpoint"},{"entityId",line["id"]}},u,v);
        }
    }
    if(session_.value("tool")=="line") {
        auto visibleParameters=parameters;QJsonArray lines;
        for(const auto& row:parameters.value("entities").toArray()){
            const auto e=row.toObject();
            if(!view_->sketchEntityVisible(e.value("id").toString()))continue;
            lines.append(e);
        }
        visibleParameters["entities"]=lines;
        for(const auto& row:SketchGeometry::pointerLineIntersections(visibleParameters)){
            const auto crossing=row.toObject();
            offer({{"kind","intersection"},{"entityIds",crossing.value("entityIds")}},crossing.value("uMm").toDouble(),crossing.value("vMm").toDouble());
        }
    }
    offer({{"kind","origin"}},0,0);
    QMap<QString,bool> endpointIds;
    for(const auto& entry:parameters["entities"].toArray()){
        const auto e=entry.toObject();if(e["type"]=="point"){endpointIds[e["pointId"].toString()]=true;continue;}
        if(e["type"]!="line" && e["type"]!="arc")continue;
        endpointIds[e["startPointId"].toString()]=true;endpointIds[e["endPointId"].toString()]=true;
    }
    for(const auto& entry:parameters["constraints"].toArray()) {
        const auto relation=entry.toObject();if(relation["type"]!="midpoint")continue;
        const auto ids=relation["pointIds"].toArray();if(ids.size()==1)endpointIds[ids[0].toString()]=true;
    }
    for(auto it=endpointIds.begin();it!=endpointIds.end();++it){
        if(it.key().isEmpty() || it.key()==parameters["originPointId"].toString() || !points.contains(it.key()))continue;
        const auto p=points.value(it.key());offer({{"kind","point"},{"pointId",it.key()}},p["uMm"].toDouble(),p["vMm"].toDouble());
    }
    for(const auto& value:session_.value("projectionContext").toObject()["lines"].toArray()) {
        const auto line=value.toObject();
        if(includeMidpoints && session_.value("tool").toString().endsWith("Polygon")){
            bool retained=false;for(const auto& row:parameters["projections"].toArray())retained|=row.toObject()["id"]==line["id"];
            if(retained)offer({{"kind","midpoint"},{"entityId",line["id"]}},(line["u1Mm"].toDouble()+line["u2Mm"].toDouble())/2,(line["v1Mm"].toDouble()+line["v2Mm"].toDouble())/2);
        }
        for(const bool end:{false,true}) {
            const auto id=line[end ? "endPointId" : "startPointId"].toString();
            const double u=line[end ? "u2Mm" : "u1Mm"].toDouble(),v=line[end ? "v2Mm" : "v1Mm"].toDouble();
            const auto screen=view_->projectSketchPoint(u,v,plane);
            const double distance=std::hypot(screen["x"].toDouble()-x,screen["y"].toDouble()-y);
            if(distance<=radiusPx)candidates.push_back(QJsonObject{{"target",QJsonObject{{"kind","point"},{"pointId",id}}},
                {"uMm",u},{"vMm",v},{"distancePx",distance},{"projected",true},{"projectionId",line["id"]},
                {"source",line["source"]},{"endpoint",end ? "end" : "start"}});
        }
    }
    for(const auto& value:session_.value("projectionContext").toObject()["points"].toArray()) {
        const auto center=value.toObject();const auto id=center["id"].toString();
        const double u=center["uMm"].toDouble(),v=center["vMm"].toDouble();
        const auto screen=view_->projectSketchPoint(u,v,plane);
        const double distance=std::hypot(screen["x"].toDouble()-x,screen["y"].toDouble()-y);
        if(distance<=radiusPx)candidates.push_back(QJsonObject{{"target",QJsonObject{{"kind","point"},{"pointId",id}}},
            {"uMm",u},{"vMm",v},{"distancePx",distance},{"projected",true},{"supportPoint",true},
            {"source",center["source"]},{"retained",center["retained"]}});
    }
    if(candidates.empty())return result;
    // A face sketch can project an authored circle center exactly onto its
    // local origin. For Circle's center click, keep the source identity instead
    // of replacing it with the generic origin point. Ambiguous source centers
    // still require a different explicit reference choice.
    const double nearestDistance=std::min_element(candidates.begin(),candidates.end(),[](const auto& a,const auto& b){
        return a.value("distancePx").toDouble()<b.value("distancePx").toDouble();
    })->value("distancePx").toDouble();
    QSet<QString> centersAtOrigin;QJsonArray originCenterCandidates;
    if(preferFaceCurveCenterAtOrigin)for(const auto& candidate:candidates){
        const auto source=candidate.value("source").toObject();
        if(candidate.value("distancePx").toDouble()>nearestDistance+ambiguityPx
            || !candidate.value("supportPoint").toBool() || source.value("role")!="curveCenter"
            || std::hypot(candidate.value("uMm").toDouble(),candidate.value("vMm").toDouble())>=1e-6)continue;
        centersAtOrigin.insert(source.value("sourceSketchId").toString()+":"+source.value("sourceEntityId").toString());
        originCenterCandidates.append(candidate);
    }
    if(centersAtOrigin.size()>1){result["status"]="ambiguous";result["candidates"]=originCenterCandidates;return result;}
    const bool preferUniqueOriginCenter=preferFaceCurveCenterAtOrigin && centersAtOrigin.size()==1;
    auto rank=[&](const QJsonObject& candidate){
        if(preferUniqueOriginCenter && candidate.value("supportPoint").toBool()
            && candidate.value("source").toObject().value("role")=="curveCenter"
            && std::hypot(candidate.value("uMm").toDouble(),candidate.value("vMm").toDouble())<1e-6)return -1;
        const auto kind=candidate["target"].toObject()["kind"];
        return kind=="origin" ? 0 : kind=="point" && !candidate.value("projected").toBool() ? 1
            : kind=="point" ? 2 : kind=="intersection" ? 3 : 4;
    };
    std::sort(candidates.begin(),candidates.end(),[&](const QJsonObject& a,const QJsonObject& b){
        const double distanceA=a["distancePx"].toDouble(),distanceB=b["distancePx"].toDouble();
        if(distanceA!=distanceB)return distanceA<distanceB;
        const auto targetA=a["target"].toObject(),targetB=b["target"].toObject();
        const int rankA=rank(a),rankB=rank(b);
        if(rankA!=rankB)return rankA<rankB;
        const auto idA=targetA["kind"]=="midpoint" ? targetA["entityId"].toString() : targetA["pointId"].toString();
        const auto idB=targetB["kind"]=="midpoint" ? targetB["entityId"].toString() : targetB["pointId"].toString();
        return idA<idB;
    });
    // Each inferred midpoint can name an authored point, but only through a
    // retained midpoint relation. Distinct points join a snap cluster only
    // through retained Coincident edges; equal coordinates alone are not intent.
    QMap<QString,QSet<QString>> midpointPoints,coincidentPoints;
    for(const auto& entry:parameters["constraints"].toArray()) {
        const auto relation=entry.toObject();
        const auto ids=relation["pointIds"].toArray();
        if(relation["type"]=="midpoint" && ids.size()==1 && relation["entityIds"].toArray().size()==1)
            midpointPoints[relation["entityIds"].toArray()[0].toString()].insert(ids[0].toString());
        if(relation["type"]=="coincident" && ids.size()==2) {
            const auto a=ids[0].toString(),b=ids[1].toString();
            coincidentPoints[a].insert(b);coincidentPoints[b].insert(a);
        }
    }
    auto identities=[&](const QJsonObject& candidate) {
        QSet<QString> ids;const auto target=candidate["target"].toObject();
        const auto kind=target["kind"].toString();
        if(kind=="origin" && !parameters["originPointId"].toString().isEmpty())ids.insert(parameters["originPointId"].toString());
        else if(kind=="point")ids.insert(target["pointId"].toString());
        else if(kind=="midpoint") {
            const auto names=midpointPoints.value(target["entityId"].toString());
            if(names.size()==1)ids=names;
        }
        ids.remove(QString{});return ids;
    };
    auto linked=[&](const QJsonObject& a,const QJsonObject& b) {
        const auto source=identities(a),target=identities(b);
        if(source.isEmpty() || target.isEmpty())return false;
        QSet<QString> visited=source;QList<QString> queue=source.values();
        for(qsizetype i=0;i<queue.size();++i) {
            const auto id=queue[i];if(target.contains(id))return true;
            for(const auto& next:coincidentPoints.value(id))if(!visited.contains(next)){visited.insert(next);queue.append(next);}
        }
        return false;
    };
    std::vector<QJsonObject> groups;
    for(const auto& candidate:candidates) {
        if(candidate["distancePx"].toDouble()-candidates[0]["distancePx"].toDouble()>ambiguityPx)break;
        bool joined=false;
        for(auto& representative:groups) {
            const bool sameLocation=std::hypot(candidate["uMm"].toDouble()-representative["uMm"].toDouble(),
                candidate["vMm"].toDouble()-representative["vMm"].toDouble())<1e-6;
            if(!sameLocation)continue;
            // An incidental midpoint or projected support point at an authored
            // point is a weaker inference, not another authored point.
            const auto candidateKind=candidate["target"].toObject()["kind"].toString();
            const auto representativeKind=representative["target"].toObject()["kind"].toString();
            const bool incidentalMidpoint=(candidateKind=="midpoint" && identities(candidate).isEmpty())
                || (representativeKind=="midpoint" && identities(representative).isEmpty());
            const bool intersectionOverlay=(candidateKind=="intersection" || representativeKind=="intersection")
                && candidateKind!=representativeKind && (candidateKind=="point" || candidateKind=="origin" || representativeKind=="point" || representativeKind=="origin");
            const bool projectedOverlay=(candidate.value("projected").toBool() || representative.value("projected").toBool())
                && (candidateKind=="point" || candidateKind=="origin")
                && (representativeKind=="point" || representativeKind=="origin");
            if(!linked(candidate,representative) && !(incidentalMidpoint
                && candidateKind!=representativeKind && (candidateKind=="midpoint" || representativeKind=="midpoint"))
                && !projectedOverlay && !intersectionOverlay)continue;
            if(rank(candidate)<rank(representative))representative=candidate;
            joined=true;break;
        }
        if(!joined)groups.push_back(candidate);
    }
    if(groups.size()>1){result["status"]="ambiguous";QJsonArray tied;for(const auto& group:groups)tied.append(group);result["candidates"]=tied;return result;}
    const auto best=groups.front();
    result["status"]="acquired";result["target"]=best["target"];result["uMm"]=best["uMm"];result["vMm"]=best["vMm"];result["distancePx"]=best["distancePx"];
    if(best.value("projected").toBool())for(const auto& field:{"projected","projectionId","source","endpoint","supportPoint","retained"})
        if(best.contains(field))result[field]=best[field];
    return result;
}

QJsonObject AlloyWindow::resolveLineCircleSnap(double x,double y,const QString& plane,const QJsonObject& first,bool shiftTangent) const {
    const auto cursor=view_->sketchPoint(x,y,plane);
    QJsonObject result{{"status","none"},{"uMm",cursor["uMm"]},{"vMm",cursor["vMm"]},
        {"radiusPx",10.0},{"authoredChange",false}};
    const auto parameters=session_.value("draftSketch").toObject().value("parameters").toObject();
    if(!first.isEmpty() && first.value("target").toObject().value("kind")=="circle" && shiftTangent) {
        const auto projected=SketchGeometry::pointerCircleFrom(parameters,first.value("target").toObject().value("entityId").toString(),
            first.value("uMm").toDouble(),first.value("vMm").toDouble(),cursor["uMm"].toDouble(),cursor["vMm"].toDouble());
        if(projected.value("status")=="ambiguous")return {{"status","ambiguous"},{"authoredChange",false}};
        if(projected.isEmpty())return result;
        result["uMm"]=projected["uMm"];result["vMm"]=projected["vMm"];
        result["status"]="inferred";result["tangentCue"]=true;return result;
    }
    if(!first.isEmpty() && first.value("target").toObject().value("kind")=="circle")return result;
    std::vector<QJsonObject> candidates;
    for(const auto& value:parameters.value("entities").toArray()) {
        const auto circle=value.toObject();if(circle.value("type")!="circle")continue;
        const auto id=circle.value("id").toString();
        QJsonArray contacts;
        if(first.isEmpty()) {
            const auto contact=SketchGeometry::pointerCircleContact(parameters,id,cursor["uMm"].toDouble(),cursor["vMm"].toDouble());
            if(!contact.isEmpty())contacts.append(QJsonObject{{"uMm",contact["uMm"]},{"vMm",contact["vMm"]}});
        } else contacts=SketchGeometry::pointerCircleTangents(parameters,id,first.value("uMm").toDouble(),first.value("vMm").toDouble());
        for(const auto& value:contacts) {
            const auto contact=value.toObject();const auto screen=view_->projectSketchPoint(contact["uMm"].toDouble(),contact["vMm"].toDouble(),plane);
            const double distance=std::hypot(screen["x"].toDouble()-x,screen["y"].toDouble()-y);
            if(distance>10.0)continue;
            QJsonObject target{{"kind","circle"},{"entityId",id}};
            if(!first.isEmpty())target["branch"]=contact["branch"];
            candidates.push_back({{"target",target},{"uMm",contact["uMm"]},{"vMm",contact["vMm"]},
                {"distancePx",distance},{"tangentCue",!first.isEmpty()}});
        }
    }
    if(candidates.empty())return result;
    std::sort(candidates.begin(),candidates.end(),[](const auto& a,const auto& b){return a["distancePx"].toDouble()<b["distancePx"].toDouble();});
    if(candidates.size()>1 && candidates[1]["distancePx"].toDouble()-candidates[0]["distancePx"].toDouble()<=0.5) {
        result["status"]="ambiguous";return result;
    }
    const auto chosen=candidates.front();result["status"]="acquired";
    for(const auto& field:{"target","uMm","vMm","distancePx","tangentCue"})result[field]=chosen[field];
    return result;
}

QJsonObject AlloyWindow::resolveCircleTangentSnap(double x,double y,const QString& plane) const {
    const auto cursor=view_->sketchPoint(x,y,plane);
    constexpr double radiusPx=10.0,ambiguityPx=0.5;
    QJsonObject result{{"status","none"},{"uMm",cursor["uMm"]},{"vMm",cursor["vMm"]},
        {"radiusPx",radiusPx},{"authoredChange",false}};
    const auto first=session_.value("firstPoint").toObject();
    if(first.isEmpty())return result;
    const QPointF center(first["uMm"].toDouble(),first["vMm"].toDouble());
    const auto parameters=session_.value("draftSketch").toObject()["parameters"].toObject();
    QMap<QString,QPointF> points;
    for(const auto& entry:parameters["points"].toArray()) {
        const auto point=entry.toObject();points[point["id"].toString()]={point["uMm"].toDouble(),point["vMm"].toDouble()};
    }
    std::vector<QJsonObject> candidates;
    for(const auto& entry:parameters["entities"].toArray()) {
        const auto line=entry.toObject();if(line["type"]!="line")continue;
        const auto startId=line["startPointId"].toString(),endId=line["endPointId"].toString();
        if(!points.contains(startId) || !points.contains(endId))continue;
        const QPointF start=points.value(startId),delta=points.value(endId)-start;
        const double squared=QPointF::dotProduct(delta,delta);if(squared<1e-18)continue;
        const double length=std::sqrt(squared);
        const double parameter=QPointF::dotProduct(center-start,delta)/squared;
        constexpr double endpointToleranceMm=1e-6;
        if(parameter< -endpointToleranceMm/length || parameter>1+endpointToleranceMm/length)continue;
        const QPointF foot=start+delta*std::clamp(parameter,0.0,1.0);
        const double tangentRadius=std::abs(delta.x()*(center.y()-start.y())-delta.y()*(center.x()-start.x()))/length;
        if(tangentRadius<0.001)continue;
        const auto screen=view_->projectSketchPoint(foot.x(),foot.y(),plane);
        const double distance=std::hypot(screen["x"].toDouble()-x,screen["y"].toDouble()-y);
        if(distance>radiusPx)continue;
        candidates.push_back(QJsonObject{{"target",QJsonObject{{"kind","tangent"},{"entityId",line["id"]}}},
            {"uMm",foot.x()},{"vMm",foot.y()},{"radiusMm",tangentRadius},{"distancePx",distance}});
    }
    if(candidates.empty())return result;
    std::sort(candidates.begin(),candidates.end(),[](const QJsonObject& a,const QJsonObject& b){
        if(a["distancePx"].toDouble()!=b["distancePx"].toDouble())return a["distancePx"].toDouble()<b["distancePx"].toDouble();
        return a["target"].toObject()["entityId"].toString()<b["target"].toObject()["entityId"].toString();
    });
    const auto best=candidates.front();QJsonArray tied;
    for(const auto& candidate:candidates) {
        if(candidate["distancePx"].toDouble()-best["distancePx"].toDouble()>ambiguityPx)break;
        tied.append(candidate);
    }
    if(tied.size()>1){result["status"]="ambiguous";result["candidates"]=tied;return result;}
    result["status"]="acquired";result["target"]=best["target"];result["uMm"]=best["uMm"];
    result["vMm"]=best["vMm"];result["radiusMm"]=best["radiusMm"];result["distancePx"]=best["distancePx"];
    return result;
}

QJsonObject AlloyWindow::resolveFilletCorner(double x,double y,const QString& plane) const {
    constexpr double radiusPx=8.0,ambiguityPx=0.5;
    QJsonObject result{{"status","none"},{"radiusPx",radiusPx},{"authoredChange",false}};
    const auto parameters=session_.value("draftSketch").toObject()["parameters"].toObject();
    QMap<QString,QJsonObject> points;QMap<QString,QString> parent;
    for(const auto& entry:parameters["points"].toArray()) {
        const auto point=entry.toObject();const auto id=point["id"].toString();points[id]=point;parent[id]=id;
    }
    auto root=[&](QString id){while(parent.contains(id) && parent.value(id)!=id)id=parent.value(id);return id;};
    for(const auto& entry:parameters["constraints"].toArray()) {
        const auto constraint=entry.toObject();if(constraint["type"]!="coincident")continue;
        const auto ids=constraint["pointIds"].toArray();if(ids.size()!=2)continue;
        const auto a=root(ids[0].toString()),b=root(ids[1].toString());if(a!=b)parent[b]=a;
    }
    QMap<QString,QJsonArray> members;
    for(auto it=points.cbegin();it!=points.cend();++it)members[root(it.key())].append(it.key());
    std::vector<QJsonObject> candidates;
    for(auto it=members.cbegin();it!=members.cend();++it) {
        QJsonArray lines;
        for(const auto& entry:parameters["entities"].toArray()) {
            const auto line=entry.toObject();if(line["type"]!="line" || line["construction"].toBool())continue;
            if(it.value().contains(line["startPointId"]) || it.value().contains(line["endPointId"]))lines.append(line["id"]);
        }
        if(lines.size()!=2)continue;
        double distance=std::numeric_limits<double>::infinity();QJsonObject nearest;
        for(const auto& value:it.value()) {
            const auto point=points.value(value.toString());const auto screen=view_->projectSketchPoint(point["uMm"].toDouble(),point["vMm"].toDouble(),plane);
            const double current=std::hypot(screen["x"].toDouble()-x,screen["y"].toDouble()-y);
            if(current<distance){distance=current;nearest=point;}
        }
        if(distance>radiusPx)continue;
        candidates.push_back(QJsonObject{{"target",QJsonObject{{"kind","filletCorner"},{"entityIds",lines},{"pointIds",it.value()}}},
            {"uMm",nearest["uMm"]},{"vMm",nearest["vMm"]},{"distancePx",distance}});
    }
    if(candidates.empty())return result;
    std::sort(candidates.begin(),candidates.end(),[](const auto& a,const auto& b){
        if(a["distancePx"].toDouble()!=b["distancePx"].toDouble())return a["distancePx"].toDouble()<b["distancePx"].toDouble();
        return a["target"].toObject()["entityIds"].toArray()[0].toString()<b["target"].toObject()["entityIds"].toArray()[0].toString();
    });
    const auto best=candidates.front();QJsonArray tied;
    for(const auto& candidate:candidates) {
        if(candidate["distancePx"].toDouble()-best["distancePx"].toDouble()>ambiguityPx)break;
        tied.append(candidate);
    }
    if(tied.size()>1){result["status"]="ambiguous";result["candidates"]=tied;return result;}
    result["status"]="acquired";result["target"]=best["target"];result["uMm"]=best["uMm"];
    result["vMm"]=best["vMm"];result["distancePx"]=best["distancePx"];
    return result;
}

QJsonObject AlloyWindow::breakPointerInput(const QJsonObject& pixels) const {
    auto draft=session_.value("draftSketch").toObject();auto p=draft.value("parameters").toObject();QJsonArray analytic;
    for(auto v:p.value("entities").toArray())if(QSet<QString>{"line","arc","circle"}.contains(v.toObject().value("type").toString()))analytic.append(v);
    p["entities"]=analytic;draft["parameters"]=p;
    const auto hit=view_->pickSketch(draft,pixels.value("x").toDouble(),pixels.value("y").toDouble(),"entity");if(hit.isEmpty()||hit.value("projected").toBool())return {};
    const auto point=view_->sketchPoint(pixels.value("x").toDouble(),pixels.value("y").toDouble(),p.value("plane").toString());
    return {{"entityId",hit.value("entityId")},{"uMm",point.value("uMm")},{"vMm",point.value("vMm")}};
}
QJsonObject AlloyWindow::previewBreak(const QJsonObject& inputs) {
    view_->clearSketchCursor();session_.remove("pendingBreak");
    if(session_.value("command")!="sketch.edit")return failure("no_active_sketch","Enter a sketch first");
    const auto result=SketchGeometry::breakCurve(session_.value("draftSketch").toObject(),inputs,session_.value("projectionContext").toObject());
    if(!result.ok)return failure("sketch_break_unavailable",result.error);
    session_["pendingBreak"]=QJsonObject{{"inputs",inputs},{"diagnostics",result.diagnostics}};
    view_->showBreakPreview(session_.value("inputs").toObject().value("plane").toString(),result.diagnostics.value("breakPoints").toArray());
    return {{"authoredChange",false},{"breakPreview",session_.value("pendingBreak")}};
}
QJsonObject AlloyWindow::trimPointerInput(const QJsonObject& pixels) const {
    auto onlyLines=session_.value("draftSketch").toObject();auto parameters=onlyLines["parameters"].toObject();QJsonArray lines;
    for(const auto& entry:parameters["entities"].toArray())if(entry.toObject()["type"]=="line")lines.append(entry);parameters["entities"]=lines;onlyLines["parameters"]=parameters;
    const auto hit=view_->pickSketch(onlyLines,pixels["x"].toDouble(),pixels["y"].toDouble(),"entity");if(hit.isEmpty() || hit["projected"].toBool())return {};
    const auto point=view_->sketchPoint(pixels["x"].toDouble(),pixels["y"].toDouble(),parameters["plane"].toString());return {{"entityId",hit["entityId"]},{"uMm",point["uMm"]},{"vMm",point["vMm"]}};
}
QJsonObject AlloyWindow::previewTrim(const QJsonObject& inputs) {
    view_->clearSketchCursor();session_.remove("pendingTrim");
    if(session_.value("command")!="sketch.edit")return failure("no_active_sketch","Enter a sketch first");
    const auto result=SketchGeometry::trimLine(session_.value("draftSketch").toObject(),inputs,session_.value("projectionContext").toObject());
    if(!result.ok)return failure("sketch_trim_failed",result.error);
    session_["pendingTrim"]=QJsonObject{{"inputs",inputs},{"diagnostics",result.diagnostics}};
    view_->showTrimPreview(session_.value("inputs").toObject()["plane"].toString(),result.diagnostics["trimmedSegment"].toObject());return {{"authoredChange",false},{"trimPreview",session_["pendingTrim"]}};
}
QJsonObject AlloyWindow::previewExtend(const QJsonObject& inputs) {
    view_->clearSketchCursor();session_.remove("pendingExtend");
    if(session_.value("command")!="sketch.edit")return failure("no_active_sketch","Enter a sketch first");
    const auto result=SketchGeometry::extendLine(session_.value("draftSketch").toObject(),inputs,session_.value("projectionContext").toObject());
    if(!result.ok)return failure("sketch_extend_unavailable",result.error);
    const auto segment=result.diagnostics.value("extendedSegment").toObject();
    session_["pendingExtend"]=QJsonObject{{"inputs",inputs},{"segment",segment}};
    view_->showExtendPreview(session_.value("inputs").toObject().value("plane").toString(),segment);
    return {{"authoredChange",false},{"extendPreview",session_.value("pendingExtend")}};
}
void AlloyWindow::clearFilletPreview() {
    auto pending=session_.value("pendingFillet").toObject();
    if(!pending.contains("previewDraft"))return;
    pending.remove("previewDraft");pending.remove("previewDiagnostics");session_["pendingFillet"]=pending;
    const auto draft=session_.value("draftSketch").toObject();
    if(!draft.isEmpty())view_->showSketchDraft(SketchGeometry::evaluateFeature(draft,session_.value("resolvedFrame").toObject(),session_.value("projectionContext").toObject()));
    auto selection=session_.value("selection").toObject();selection["tool"]=session_.value("tool");
    view_->decorateSketch(draft,selection,session_.value("solverDiagnostics").toObject(),
        session_.value("inputs").toObject()["units"].toString());
    view_->clearSketchCursor();
}

QJsonObject AlloyWindow::previewFillet(const QJsonObject& args) {
    if(session_.value("command")!="sketch.edit")return failure("no_active_sketch","Enter a sketch first");
    if(session_.value("tool")!="fillet")return failure("fillet_tool_inactive","Select sketch Fillet before previewing corners");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))return failure("stale_session","The document changed; cancel and restart this sketch");
    auto pending=session_.value("pendingFillet").toObject();
    const auto corners=args.contains("corners") ? args["corners"].toArray() : pending["corners"].toArray();
    if(corners.isEmpty() || corners.size()>2)return failure("invalid_fillet_target","Select one or two sketch corners");
    double radiusMm=pending.value("radiusMm").toDouble();
    if(args.contains("value")) {
        const auto units=args.value("units").toString(session_.value("inputs").toObject()["units"].toString());
        radiusMm=CadDocument::millimeters(args["value"].toDouble(),units);
    }
    if(!std::isfinite(radiusMm) || radiusMm<0.001)return failure("invalid_fillet_radius","Enter a positive fillet radius");
    clearFilletPreview();
    const auto solved=SketchGeometry::filletCorners(session_["draftSketch"].toObject(),{{"corners",corners},{"radiusMm",radiusMm}},session_.value("projectionContext").toObject());
    if(!solved.ok) {
        auto response=failure("sketch_fillet_failed",solved.error);auto error=response["error"].toObject();error["diagnostics"]=solved.diagnostics;response["error"]=error;return response;
    }
    const auto evaluated=SketchGeometry::evaluateFeature(solved.feature,session_.value("resolvedFrame").toObject(),session_.value("projectionContext").toObject());
    pending=session_.value("pendingFillet").toObject();pending.remove("previewError");pending["previewDraft"]=solved.feature;
    pending["previewDiagnostics"]=solved.diagnostics;pending["radiusMm"]=radiusMm;
    session_["pendingFillet"]=pending;
    view_->showSketchDraft(evaluated);
    return {{"authoredChange",false},{"previewed",true},{"sketchGeometry",evaluated.summary},
        {"diagnostics",solved.diagnostics},{"createdArcIds",solved.diagnostics.value("createdArcIds")},
        {"removedDimensionIds",solved.diagnostics.value("removedDimensionIds")}};
}

QJsonObject AlloyWindow::appendSketchCurve(const QString& tool,const QJsonObject& inputs) {
    if(session_.value("command")!="sketch.edit")return failure("no_active_sketch","Enter a sketch first");
    if(inputs.contains("session") && inputs["session"]!=session_["id"])return failure("invalid_session","Session is no longer active");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))return failure("stale_session","The document changed; cancel and restart this sketch");
    const auto units=inputs.value("units").toString(session_["inputs"].toObject()["units"].toString());
    auto length=[&](const char* field){if(!inputs.value(field).isDouble())throw std::invalid_argument("Missing curve coordinate/length");return CadDocument::millimeters(inputs[field].toDouble(),units);};
    QJsonObject canonical;
    if(tool=="circle" || tool=="centerArc") {
        canonical={{"centerUMm",length("centerX")},{"centerVMm",length("centerY")}};
        if(tool=="circle")canonical["diameterMm"]=length("diameter");
        else {if(!inputs["startAngleDeg"].isDouble() || !inputs["sweepAngleDeg"].isDouble())return failure("invalid_arguments","Center arc requires startAngleDeg and signed sweepAngleDeg");
            canonical["radiusMm"]=length("radius");canonical["startAngleDeg"]=inputs["startAngleDeg"];canonical["sweepAngleDeg"]=inputs["sweepAngleDeg"];}
    } else canonical={{"startUMm",length("startX")},{"startVMm",length("startY")},{"endUMm",length("endX")},{"endVMm",length("endY")},{"throughUMm",length("throughX")},{"throughVMm",length("throughY")}};
    const auto draft=session_["draftSketch"].toObject();
    return publishSketchSolve(SketchGeometry::solveDraft(tool=="circle" ? SketchGeometry::addCircle(draft,canonical) : SketchGeometry::addArc(draft,canonical),session_.value("projectionContext").toObject()));
}

QJsonObject AlloyWindow::sketchCurveGesture(const QJsonObject& point,bool commit) {
    const auto tool=session_["tool"].toString();
    if(!session_.contains("firstPoint")) {if(commit)session_["firstPoint"]=point;return {{"placement",false},{"nextPoint",tool=="circle" ? "circumference" : tool=="twoPointCircle" ? "diameter direction" : tool=="centerArc" ? "start" : "end"}};}
    const auto first=session_["firstPoint"].toObject();const double ax=first["uMm"].toDouble(),ay=first["vMm"].toDouble(),x=point["uMm"].toDouble(),y=point["vMm"].toDouble();
    QJsonObject inputs{{"units","mm"}};
    if(tool=="circle")inputs={{"centerX",ax},{"centerY",ay},{"diameter",2*std::hypot(x-ax,y-ay)},{"units","mm"}};
    else if(tool=="twoPointCircle")inputs={{"diameter",std::hypot(x-ax,y-ay)},{"units","mm"}};
    else {
        if(!session_.contains("secondPoint")) {
            if(commit)session_["secondPoint"]=point;
            else view_->showSketchCursor(session_["inputs"].toObject()["plane"].toString(),{ax,ay},{x,y},false);
            return {{"placement",false},{"nextPoint",tool=="centerArc" ? "end" : "through"}};
        }
        const auto second=session_["secondPoint"].toObject();const double bx=second["uMm"].toDouble(),by=second["vMm"].toDouble();
        if(tool=="threePointArc")inputs={{"mode","threePoint"},{"startX",ax},{"startY",ay},{"endX",bx},{"endY",by},{"throughX",x},{"throughY",y},{"units","mm"}};
        else {
            const double start=std::atan2(by-ay,bx-ax)*180/std::numbers::pi;
            double sweep=std::remainder(std::atan2(y-ay,x-ax)*180/std::numbers::pi-start,360.0);
            if(session_.contains("gestureSweepDeg")) {const double previous=session_["gestureSweepDeg"].toDouble();
                while(sweep-previous>180)sweep-=360;while(sweep-previous< -180)sweep+=360;}
            if(std::abs(sweep)>=360)return failure("invalid_arc","Arc sweep must be smaller than a full revolution");
            session_["gestureSweepDeg"]=sweep;
            inputs={{"mode","center"},{"centerX",ax},{"centerY",ay},{"radius",std::hypot(bx-ax,by-ay)},{"startAngleDeg",start},{"sweepAngleDeg",sweep},{"units","mm"}};
        }
    }
    if(commit) {
        if(tool=="circle") {
            QJsonObject canonical{{"centerUMm",ax},{"centerVMm",ay},{"diameterMm",inputs["diameter"]}};
            if(first["status"]=="acquired")canonical["centerSnapTarget"]=first["target"];
            if(point["status"]=="acquired" && point["target"].toObject()["kind"]=="tangent")
                canonical["tangentSnapTarget"]=point["target"];
            return publishSketchSolve(SketchGeometry::addPointerCircle(session_["draftSketch"].toObject(),canonical,session_.value("projectionContext").toObject()));
        }
        if(tool=="twoPointCircle") {
            const double diameter=inputs["diameter"].toDouble();
            if(diameter<0.002)return failure("invalid_circle_diameter","Move the second diameter endpoint away from the first");
            return publishSketchSolve(SketchGeometry::addTwoPointCircle(session_["draftSketch"].toObject(),
                {{"startUMm",ax},{"startVMm",ay},{"directionU",(x-ax)/diameter},{"directionV",(y-ay)/diameter},{"diameterMm",diameter}},
                session_.value("projectionContext").toObject()));
        }
        return appendSketchCurve(tool,inputs);
    }
    try {
        const auto sketchInputs=session_["inputs"].toObject();const auto plane=sketchInputs["plane"].toString();
        auto preview=plane=="face"
            ? SketchGeometry::newSupportedFeature(document_->activeOwnerId(),sketchInputs["support"].toObject(),"Curve Preview")
            : plane=="construction" ? SketchGeometry::newConstructionPlaneFeature(document_->activeOwnerId(),sketchInputs["planeId"].toString(),"Curve Preview")
            : SketchGeometry::newFeature(document_->activeOwnerId(),plane,"Curve Preview");
        if(plane=="face") {auto parameters=preview["parameters"].toObject();const auto original=session_["draftSketch"].toObject()["parameters"].toObject();
            if(original.contains("originConvention"))parameters["originConvention"]=original["originConvention"];
            preview["parameters"]=parameters;}
        if(tool=="circle")preview=SketchGeometry::addCircle(preview,{{"centerUMm",ax},{"centerVMm",ay},{"diameterMm",inputs["diameter"]}});
        else if(tool=="twoPointCircle")preview=SketchGeometry::addCircle(preview,{{"centerUMm",(ax+x)/2},{"centerVMm",(ay+y)/2},{"diameterMm",inputs["diameter"]}});
        else if(tool=="centerArc")preview=SketchGeometry::addArc(preview,{{"centerUMm",ax},{"centerVMm",ay},{"radiusMm",inputs["radius"]},{"startAngleDeg",inputs["startAngleDeg"]},{"sweepAngleDeg",inputs["sweepAngleDeg"]}});
        else preview=SketchGeometry::addArc(preview,{{"startUMm",ax},{"startVMm",ay},{"endUMm",inputs["endX"]},{"endVMm",inputs["endY"]},{"throughUMm",x},{"throughVMm",y}});
        const auto e=preview["parameters"].toObject()["entities"].toArray().first().toObject();view_->showSketchCurveCursor(preview);
        return {{"authoredChange",false},{"curve",e}};
    }catch(const std::invalid_argument&){view_->clearSketchCursor();return {{"authoredChange",false}};}
}

double AlloyWindow::sketchDimensionMeasure(const QJsonObject& targets,const QString& kind) const {
    const auto parameters=SketchGeometry::expandedProjectionFeature(session_.value("draftSketch").toObject(),session_.value("projectionContext").toObject())["parameters"].toObject();
    if(kind=="angle") {
        const auto ids=targets.value("entityIds").toArray();
        if(ids.size()!=2 || ids[0]==ids[1])throw std::invalid_argument("Select two distinct lines for an angle");
        QMap<QString,QPointF> points;for(const auto& value:parameters["points"].toArray()){const auto p=value.toObject();points[p["id"].toString()]={p["uMm"].toDouble(),p["vMm"].toDouble()};}
        QJsonArray lines;
        for(const auto& id:ids)for(const auto& value:parameters["entities"].toArray())if(value.toObject()["id"]==id){lines.append(value);break;}
        if(lines.size()!=2 || lines[0].toObject()["type"]!="line" || lines[1].toObject()["type"]!="line")throw std::invalid_argument("Select two lines for an angle");
        auto direction=[&](const QJsonValue& value){const auto line=value.toObject();return points.value(line["endPointId"].toString())-points.value(line["startPointId"].toString());};
        auto a=direction(lines[0]),b=direction(lines[1]);const auto signs=targets.value("raySigns").toArray();
        if(signs.size()==2){a*=signs[0].toInt(1);b*=signs[1].toInt(1);}
        const double cross=a.x()*b.y()-a.y()*b.x(),dot=a.x()*b.x()+a.y()*b.y();
        const double measured=std::abs(std::atan2(cross,dot))*180/std::numbers::pi;
        if(measured<1e-6 || measured>179.999999)throw std::invalid_argument("Select nonparallel lines for an angle");
        return measured;
    }
    if(kind=="centerlineDiameter")return SketchGeometry::centerlineDiameterValue(session_.value("draftSketch").toObject(),targets["entityIds"].toArray(),session_.value("projectionContext").toObject());
    if(kind=="parallelLineDistance") {
        const auto ids=targets["entityIds"].toArray();if(ids.size()!=2 || ids[0]==ids[1])throw std::invalid_argument("Select two distinct straight lines");
        QMap<QString,QPointF> points;for(const auto& row:parameters["points"].toArray()){const auto p=row.toObject();points[p["id"].toString()]={p["uMm"].toDouble(),p["vMm"].toDouble()};}
        QJsonObject first,second;for(const auto& row:parameters["entities"].toArray()){const auto line=row.toObject();if(line["id"]==ids[0])first=line;if(line["id"]==ids[1])second=line;}
        if(first["type"]!="line" || second["type"]!="line")throw std::invalid_argument("Distance requires two straight lines");
        const auto a=points.value(first["startPointId"].toString()),b=points.value(first["endPointId"].toString()),c=points.value(second["startPointId"].toString()),d=points.value(second["endPointId"].toString());
        const auto axis=b-a,edge=d-c;const double length=std::hypot(axis.x(),axis.y()),edgeLength=std::hypot(edge.x(),edge.y());
        if(length<.001 || edgeLength<.001 || std::abs(axis.x()*edge.y()-axis.y()*edge.x())/(length*edgeLength)>1e-9)throw std::invalid_argument("Distance requires two parallel straight lines");
        return std::abs(axis.x()*(c.y()-a.y())-axis.y()*(c.x()-a.x()))/length;
    }
    if(kind=="pointLineDistance") {
        const auto ids=targets["pointIds"].toArray();if(ids.size()!=1)throw std::invalid_argument("Select a point and a straight edge");QMap<QString,QPointF> points;for(const auto& value:parameters["points"].toArray()){const auto p=value.toObject();points[p["id"].toString()]={p["uMm"].toDouble(),p["vMm"].toDouble()};}QJsonObject edge;for(const auto& value:parameters["entities"].toArray())if(value.toObject()["id"]==targets["entityId"])edge=value.toObject();if(edge["type"]!="line" || !points.contains(ids[0].toString()))throw std::invalid_argument("Point-edge targets unavailable");const auto a=points.value(edge["startPointId"].toString()),b=points.value(edge["endPointId"].toString()),q=points.value(ids[0].toString());const auto d=b-a;const double length=std::hypot(d.x(),d.y());if(length<.001)throw std::invalid_argument("Point-edge target is degenerate");return std::abs(d.x()*(q.y()-a.y())-d.y()*(q.x()-a.x()))/length;
    }
    if(targets.contains("entityId")) {
        for(const auto& value:parameters["entities"].toArray()){const auto e=value.toObject();if(e["id"]!=targets["entityId"])continue;
            if(kind=="radius")return e["radiusMm"].toDouble();if(kind=="diameter")return 2*e["radiusMm"].toDouble();
            if(kind=="arcSweep" && e["type"]=="arc")return std::abs(e["sweepAngleDeg"].toDouble());
            throw std::invalid_argument("Select Radius, Diameter or Arc Sweep for a curve");
        }throw std::invalid_argument("Curve dimension target does not exist");
    }
    const auto ids=targets["pointIds"].toArray();if(ids.size()!=2)throw std::invalid_argument("Select a line or two points");
    QMap<QString,QPointF> points;for(const auto& value:parameters["points"].toArray()){const auto p=value.toObject();points[p["id"].toString()]={p["uMm"].toDouble(),p["vMm"].toDouble()};}
    const auto a=points[ids[0].toString()],b=points[ids[1].toString()];
    if(kind=="horizontal")return std::abs(b.x()-a.x());if(kind=="vertical")return std::abs(b.y()-a.y());
    if(kind=="linear")return std::hypot(b.x()-a.x(),b.y()-a.y());throw std::invalid_argument("Select a curve for Radius, Diameter or Arc Sweep");
}

QJsonObject AlloyWindow::publishSketchSolve(const SketchGeometry::SolveResult& solved,const QString& journalGroup) {
    if(session_.contains("pendingSlotDrag"))cancelSlotDrag();
    if(session_.value("command").toString()!="sketch.edit")return failure("no_active_sketch","Enter a sketch first");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))return failure("stale_session","The document changed; cancel and restart this sketch");
    if(!solved.ok) {
        auto diagnostics=solved.diagnostics;
        diagnostics["postFailureSolver"]=session_.value("solverDiagnostics");
        diagnostics["documentRevision"]=static_cast<qint64>(document_->revision());
        diagnostics["draftHistory"]=session_.value("draftHistory");
        diagnostics["sketchId"]=session_.value("draftSketch").toObject().value("id");
        session_["lastSolveFailure"]=diagnostics;
        auto response=failure(diagnostics.value("code")=="constraint_conflict" ? "constraint_conflict" : "sketch_solve_failed",solved.error);
        auto error=response["error"].toObject();error["accepted"]=false;error["diagnostics"]=diagnostics;response["error"]=error;return response;
    }
    const auto candidate=SketchGeometry::replaceFeature(document_->authored(),solved.feature);const auto error=CadDocument::validate(candidate);
    if(!error.isEmpty())return failure("invalid_sketch",error);
    auto context=session_.value("projectionContext").toObject();
    if(solved.feature["parameters"].toObject()["plane"]=="face" || solved.feature["parameters"].toObject()["plane"]=="construction")try {
        const auto editId=session_.value("inputs").toObject().value("sketchId").toString();
        const auto history=editId.isEmpty() ? document_->evaluation() : sketchHistoryStage(editId);
        context=GeometryKernel::projectionContext(history,solved.feature);
    } catch(const GeometryKernel::EvaluationError& error) {
        auto response=failure("projection_unavailable",QString::fromUtf8(error.what()));
        auto details=response["error"].toObject();details["diagnostics"]=error.diagnostics();response["error"]=details;return response;
    }
    const auto evaluated=solved.feature["parameters"].toObject().contains("loopOffsets") ? evaluateSketchDraft(solved.feature)
        : SketchGeometry::evaluateFeature(solved.feature,session_.value("resolvedFrame").toObject(),context);
    cancelCircleDiameter();cancelCenterRectangle();cancelTwoPointRectangle();cancelCircleOffset();session_.remove("pendingSketchMirror");session_.remove("pendingSketchPattern");session_.remove("pendingSketchMove");
    session_.remove("pendingDrivenOffer");
    recordSketchHistory(solved.feature,solved.diagnostics,journalGroup);
    session_["draftSketch"]=solved.feature;session_["solverDiagnostics"]=solved.diagnostics;session_["projectionContext"]=context;session_["previewed"]=false;
    auto selection=session_.value("selection").toObject();selection.remove("constraintIds");session_["selection"]=selection;session_.remove("hoveredConstraintId");
    session_.remove("lastSolveFailure");session_.remove("firstPoint");session_.remove("secondPoint");session_.remove("pointerPoint");session_.remove("gestureSweepDeg");session_.remove("snap");
    view_->clearSketchCursor();view_->showSketchDraft(evaluated);displayedSketchDraft_=solved.feature;
    return {{"sessionId",session_.value("id")},{"draftSketch",solved.feature},{"sketchGeometry",evaluated.summary},{"diagnostics",solved.diagnostics},{"authoredCommitted",false}};
}

QJsonObject AlloyWindow::publishNewDimension(const QJsonObject& draft,const QJsonObject& arguments) {
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))
        return failure("stale_session","The document changed; cancel and restart this sketch");
    if(session_.contains("pendingDrivenOffer"))return failure("pending_dimension_offer","Choose Add Driven or Cancel before adding another dimension");
    const auto context=session_.value("projectionContext").toObject();
    const auto names=userLengthNames();
    const auto driving=SketchGeometry::addDimension(draft,arguments,context,names);
    if(driving.ok)return publishSketchSolve(driving);
    const auto alternative=SketchGeometry::drivenAlternative(draft,arguments,driving,context,names);
    if(!alternative)return publishSketchSolve(driving);
    const auto dimensions=alternative->feature.value("parameters").toObject().value("dimensions").toArray();
    const auto dimension=dimensions.last().toObject();
    const QString offerId=CadDocument::newId();
    const auto offer=QJsonObject{{"id",offerId},{"dimensionId",dimension.value("id")},
        {"kind",dimension.value("kind")},{"draftSketch",draft},{"feature",alternative->feature},
        {"diagnostics",alternative->diagnostics},{"sessionId",session_.value("id")},
        {"tabId",activeTabId_},{"documentRevision",static_cast<qint64>(document_->revision())},
        {"historyIndex",sketchHistoryIndex_}};
    session_["pendingDrivenOffer"]=offer;
    if(dimensionEditor_)dimensionEditor_->hide();
    refreshSketchControls();
    if(auto* choice=sketchPanel_ ? sketchPanel_->findChild<QPushButton*>("sketch.dimension.offerAccept") : nullptr)
        choice->setFocus(Qt::OtherFocusReason);
    return {{"pending",true},{"offerId",offerId},{"dimensionId",dimension.value("id")},
        {"kind",dimension.value("kind")},{"message","This dimension is redundant. Add it as a read-only Driven measurement?"}};
}

QJsonObject AlloyWindow::selectSketchProjection(const QJsonObject& source) {
    if(!session_.contains("pendingProject"))return failure("no_project_tool","Start Project first");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))return failure("stale_session","Document changed during Project");
    auto pending=session_["pendingProject"].toObject();
    const auto editId=session_.value("inputs").toObject().value("sketchId").toString();
    const auto history=editId.isEmpty() ? document_->evaluation() : sketchHistoryStage(editId);
    auto selected=pending["sources"].toArray();
    if(selected.contains(source))return QJsonObject{{"pending",true},{"selectedCount",selected.size()},{"duplicate",true}};
    QJsonObject candidate,context;try {
        candidate=SketchGeometry::linkedProjectionCandidate(history,pending["previewDraft"].toObject(),source);
        context=GeometryKernel::projectionContext(history,candidate);
    } catch(const GeometryKernel::EvaluationError& error) {
        return failure(error.diagnostics()["code"].toString(),QString::fromUtf8(error.what()));
    } catch(const std::exception& error) {return failure("invalid_projection",QString::fromUtf8(error.what()));}
    const auto solved=SketchGeometry::solveDraft(candidate,context);
    if(!solved.ok)return failure("sketch_solve_failed",solved.error);
    EvaluatedSketch evaluated;try {
        evaluated=SketchGeometry::evaluateFeature(solved.feature,session_["resolvedFrame"].toObject(),context);
    } catch(const std::exception& error) {return failure("projection_preview_failed",QString::fromUtf8(error.what()));}
    selected.append(source);pending["sources"]=selected;pending["previewDraft"]=solved.feature;pending["previewGeometry"]=evaluated.summary;session_["pendingProject"]=pending;
    view_->showSketchDraft(evaluated);displayedSketchDraft_=solved.feature;
    try {refreshSketchControls();}catch(const std::exception& error){return failure("projection_controls_failed",QString::fromUtf8(error.what()));}
    return QJsonObject{{"pending",true},{"selectedCount",selected.size()},{"source",source},{"previewDraft",solved.feature},
        {"sketchGeometry",evaluated.summary}};
}

QJsonObject AlloyWindow::selectSketchProjectionFace(const QJsonObject& support) {
    if(!session_.contains("pendingProject"))return failure("no_project_tool","Start Project first");
    const auto editId=session_.value("inputs").toObject().value("sketchId").toString();
    const auto history=editId.isEmpty() ? document_->evaluation() : sketchHistoryStage(editId);
    EvaluatedSupportFace face;try{face=GeometryKernel::resolveSketchSupport(history,support);}
    catch(const GeometryKernel::EvaluationError& error){return failure(error.diagnostics()["code"].toString(),QString::fromUtf8(error.what()));}
    for(const auto& edge:face.boundaryEdges)if(edge.type!="line")
        return failure("unsupported_projection","This Project accepts faces with straight boundaries only");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))return failure("stale_session","Document changed during Project");
    const auto before=session_["pendingProject"].toObject();
    int added=0;for(const auto& edge:face.boundaryEdges) {
        const auto result=selectSketchProjection({{"bodyId",support["bodyId"]},{"edgeId",edge.edgeId}});
        if(result.contains("error")) {
            session_["pendingProject"]=before;
            const auto draft=before["previewDraft"].toObject();const auto context=GeometryKernel::projectionContext(history,draft);
            view_->showSketchDraft(SketchGeometry::evaluateFeature(draft,session_["resolvedFrame"].toObject(),context));displayedSketchDraft_=draft;
            refreshSketchControls();return result;
        }
        if(!result["duplicate"].toBool())++added;
    }
    const auto restore=[&] {
        session_["pendingProject"]=before;const auto original=before.value("previewDraft").toObject();
        view_->showSketchDraft(SketchGeometry::evaluateFeature(original,session_.value("resolvedFrame").toObject(),GeometryKernel::projectionContext(history,original)));displayedSketchDraft_=original;refreshSketchControls();
    };
    try {
    auto pending=session_.value("pendingProject").toObject();auto draft=pending.value("previewDraft").toObject();auto parameters=draft.value("parameters").toObject();
    QJsonArray members;
    for(const auto& edge:face.boundaryEdges)for(const auto& key:{"projections","circleProjections","pointProjections"})
        for(const auto& row:parameters.value(key).toArray()) {
            const auto projection=row.toObject(),source=projection.value("source").toObject();
            if(source.value("bodyId")==support.value("bodyId") && source.value("edgeId")==edge.edgeId)members.append(projection.value("id"));
        }
    const auto groupId=QUuid::createUuidV5(QUuid(draft.value("id").toString()),QByteArray("alloy-face-projection/1\n")
        +support.value("producerFeatureId").toString().toUtf8()+'\n'+support.value("bodyId").toString().toUtf8()+'\n'+support.value("faceId").toString().toUtf8()).toString(QUuid::WithoutBraces);
    const QJsonObject group{{"id",groupId},{"source",support},{"projectionIds",members}};
    QJsonArray groups;bool replaced=false;for(const auto& row:parameters.value("faceProjectionGroups").toArray()) {
        if(row.toObject().value("id")==groupId){groups.append(group);replaced=true;}else groups.append(row);
    }
    if(!replaced)groups.append(group);parameters["faceProjectionGroups"]=groups;draft["parameters"]=parameters;
    const auto context=GeometryKernel::projectionContext(history,draft);const auto solved=SketchGeometry::solveDraft(draft,context);
    if(!solved.ok) {
        restore();
        return failure("sketch_solve_failed",solved.error);
    }
    pending["previewDraft"]=solved.feature;const auto evaluated=SketchGeometry::evaluateFeature(solved.feature,session_.value("resolvedFrame").toObject(),context);
    pending["previewGeometry"]=evaluated.summary;session_["pendingProject"]=pending;view_->showSketchDraft(evaluated);displayedSketchDraft_=solved.feature;refreshSketchControls();
    return QJsonObject{{"pending",true},{"selectedCount",session_["pendingProject"].toObject()["sources"].toArray().size()},
        {"added",added},{"face",support},{"faceProjectionGroupId",groupId},{"projectionIds",members}};
    } catch(const GeometryKernel::EvaluationError& error) {restore();return failure(error.diagnostics().value("code").toString(),QString::fromUtf8(error.what()));}
    catch(const std::exception& error) {restore();return failure("invalid_projection",QString::fromUtf8(error.what()));}
}

void AlloyWindow::updateSketchHistoryState() {
    if(session_.value("command")!="sketch.edit")return;
    session_["draftHistory"]=QJsonObject{{"index",sketchHistoryIndex_},{"count",static_cast<int>(sketchHistory_.size())},
        {"canUndo",sketchHistoryIndex_>0},{"canRedo",sketchHistoryIndex_+1<static_cast<int>(sketchHistory_.size())}};
}

void AlloyWindow::recordSketchHistory(const QJsonObject& draft,const QJsonObject& diagnostics,const QString& group) {
    if(sketchHistoryIndex_>=0 && draft==sketchHistory_[sketchHistoryIndex_].draft)return;
    if(!group.isEmpty() && group==sketchHistoryGroup_ && sketchHistoryIndex_>0
        && sketchHistoryIndex_==static_cast<int>(sketchHistory_.size())-1) {
        sketchHistory_[sketchHistoryIndex_]={draft,diagnostics};
    } else {
        sketchHistory_.resize(sketchHistoryIndex_+1);
        sketchHistory_.push_back({draft,diagnostics});
        sketchHistoryIndex_=static_cast<int>(sketchHistory_.size())-1;
    }
    sketchHistoryGroup_=group;updateSketchHistoryState();
}

QJsonObject AlloyWindow::traverseSketchHistory(int direction) {
    if(session_.contains("pendingSplineDrag"))splineCommand("drag",{{"phase","cancel"}});
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))
        return failure("stale_session","The document changed; cancel and restart this sketch");
    cancelConicInput();
    cancelSlotDrag();
    if(session_.contains("pendingSketchMove") || session_["moveInteraction"].toObject()["active"].toBool()){execute("sketch.moveExit");return {{"action","cancelled_input"},{"changed",false},{"draftHistory",session_["draftHistory"]}};}
    if(session_.contains("pendingSketchPattern")){execute("sketch.patternCancel");return {{"action","cancelled_input"},{"changed",false},{"draftHistory",session_["draftHistory"]}};}
    if(session_.contains("pendingSketchMirror")){
        session_.remove("pendingSketchMirror");const auto draft=session_["draftSketch"].toObject();
        view_->showSketchDraft(evaluateSketchDraft(draft));displayedSketchDraft_=draft;view_->setFocus();
        return {{"action","cancelled_input"},{"changed",false},{"draftHistory",session_["draftHistory"]}};
    }
    if(direction<0) {
        if(session_.contains("pendingTwoPointRectangle")) {
            cancelTwoPointRectangle();view_->setFocus();return {{"action","cancelled_input"},{"changed",false},{"draftHistory",session_["draftHistory"]}};
        }
        if(session_.contains("pendingCenterRectangle")) {
            cancelCenterRectangle();view_->setFocus();return {{"action","cancelled_input"},{"changed",false},{"draftHistory",session_["draftHistory"]}};
        }
        if(session_.contains("pendingCircleDiameter")) {
            cancelCircleDiameter();view_->setFocus();return {{"action","cancelled_input"},{"changed",false},{"draftHistory",session_["draftHistory"]}};
        }
        if(session_.contains("pendingLineLength")) {
            cancelLineLength();view_->setFocus();return {{"action","cancelled_input"},{"changed",false},{"draftHistory",session_["draftHistory"]}};
        }
        if(session_.value("pendingDimension").toObject()["phase"]=="editing") {
            cancelDimension();view_->setFocus();return {{"action","cancelled_input"},{"changed",false},{"draftHistory",session_["draftHistory"]}};
        }
        if(session_.value("tool")!="select") {
            const auto previous=session_.value("tool");
            const auto response=execute("sketch.tool",{{"tool","select"}});
            if(!response["ok"].toBool())return response;
            return {{"action","cancelled_tool"},{"tool",previous},{"changed",false},{"draftHistory",session_["draftHistory"]}};
        }
    } else if(session_.value("tool")!="select" || session_.contains("pendingDimension") || session_.contains("pendingCircleDiameter") || session_.contains("pendingLineLength") || session_.contains("pendingCenterRectangle") || session_.contains("pendingTwoPointRectangle") || session_.contains("pendingFillet") || session_.contains("pendingChamfer") || session_.contains("firstPoint"))
        return failure("pending_input_active","Complete or cancel the current sketch tool before Redo");
    const int next=sketchHistoryIndex_+direction;
    if(next<0 || next>=static_cast<int>(sketchHistory_.size()))return {{"action","none"},{"changed",false},{"draftHistory",session_["draftHistory"]}};
    const auto entry=sketchHistory_[next];
    auto context=session_.value("projectionContext").toObject();
    if(entry.draft["parameters"].toObject()["plane"]=="face" || entry.draft["parameters"].toObject()["plane"]=="construction")try {
        const auto editId=session_.value("inputs").toObject().value("sketchId").toString();
        const auto history=editId.isEmpty() ? document_->evaluation() : sketchHistoryStage(editId);
        context=GeometryKernel::projectionContext(history,entry.draft);
    } catch(const GeometryKernel::EvaluationError& error) {
        auto response=failure("projection_unavailable",QString::fromUtf8(error.what()));
        auto details=response["error"].toObject();details["diagnostics"]=error.diagnostics();response["error"]=details;return response;
    }
    const auto evaluated=entry.draft.value("parameters").toObject().contains("loopOffsets") ? evaluateSketchDraft(entry.draft)
        : SketchGeometry::evaluateFeature(entry.draft,session_.value("resolvedFrame").toObject(),context);
    sketchHistoryIndex_=next;sketchHistoryGroup_.clear();
    cancelDimension();view_->clearSketchCursor();
    session_["draftSketch"]=entry.draft;session_["solverDiagnostics"]=entry.diagnostics;session_["projectionContext"]=context;
    auto inputs=session_["inputs"].toObject();inputs["name"]=entry.draft["name"];session_["inputs"]=inputs;
    session_["selection"]=QJsonObject{{"pointIds",QJsonArray{}},{"entityIds",QJsonArray{}},{"profileIds",QJsonArray{}}};
    session_.remove("firstPoint");session_.remove("secondPoint");session_.remove("pointerPoint");session_.remove("gestureSweepDeg");session_.remove("snap");session_.remove("hoveredConstraintId");session_.remove("lastSolveFailure");
    session_["previewed"]=false;updateSketchHistoryState();
    view_->showSketchDraft(evaluated);displayedSketchDraft_=entry.draft;view_->setFocus();
    return {{"action",direction<0 ? "undone" : "redone"},{"changed",true},{"draftHistory",session_["draftHistory"]},
        {"draftSketch",entry.draft},{"diagnostics",entry.diagnostics},{"sketchGeometry",evaluated.summary}};
}

QJsonObject AlloyWindow::applySketchConstraint(const QString& type,const QJsonObject& targets) {
    if(type=="fixed") {
        QJsonObject args;for(const auto& field:{"pointIds","entityIds"})if(targets.contains(field))args[field]=targets.value(field);
        return publishSketchSolve(SketchGeometry::toggleFixed(session_.value("draftSketch").toObject(),args,session_.value("projectionContext").toObject()));
    }
    auto args=targets;args["type"]=type;
    if(type=="horizontalVertical" && targets.contains("entityIds")) {
        const auto ids=targets["entityIds"].toArray();
        if(ids.size()!=1)return failure("invalid_constraint_target","Select one line for Horizontal/Vertical");
    const auto parameters=SketchGeometry::expandedProjectionFeature(session_.value("draftSketch").toObject(),session_.value("projectionContext").toObject())["parameters"].toObject();
        QMap<QString,QJsonObject> points;for(const auto& entry:parameters["points"].toArray())points[entry.toObject()["id"].toString()]=entry.toObject();
        bool found=false;
        for(const auto& entry:parameters["entities"].toArray()) {
            const auto entity=entry.toObject();if(entity["id"]!=ids[0])continue;
            if(entity["type"]!="line")return failure("invalid_constraint_target","Horizontal/Vertical requires a line");
            const auto a=points.value(entity["startPointId"].toString()),b=points.value(entity["endPointId"].toString());
            args["type"]=std::abs(b["uMm"].toDouble()-a["uMm"].toDouble())>=std::abs(b["vMm"].toDouble()-a["vMm"].toDouble()) ? "horizontal" : "vertical";found=true;break;
        }
        if(!found)return failure("stale_entity","Selected line no longer exists");
    }
    return publishSketchSolve(SketchGeometry::addConstraint(session_.value("draftSketch").toObject(),args,session_.value("projectionContext").toObject()));
}

QJsonObject AlloyWindow::setSketchSelection(const QJsonObject& selection) {
    if(session_.value("command").toString()!="sketch.edit")return failure("no_active_sketch","Enter a sketch first");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))return failure("stale_session","The document changed; cancel and restart this sketch");
    const auto parameters=SketchGeometry::chamferPresentation(SketchGeometry::expandedProjectionFeature(session_.value("draftSketch").toObject(),session_.value("projectionContext").toObject()))["parameters"].toObject();
    QJsonObject normalized;
    for(const auto& field:QStringList{"pointIds","entityIds","profileIds"}) {
        QSet<QString> available;
        if(field=="profileIds")for(const auto& profile:evaluateSketchDraft(session_.value("draftSketch").toObject()).profiles)available.insert(profile.profileId);
        else {
            for(const auto& entry:parameters[field=="pointIds" ? "points" : "entities"].toArray())available.insert(entry.toObject()["id"].toString());
            if(field=="pointIds")for(const auto& value:session_.value("projectionContext").toObject()["points"].toArray())
                available.insert(value.toObject()["id"].toString());
        }
        QJsonArray ids;for(const auto& value:selection[field].toArray()) {
            if(!value.isString() || !available.contains(value.toString()))return failure("stale_entity","Selected sketch geometry does not exist",field);
            if((field=="pointIds" && !view_->sketchPointVisible(value.toString()))
                || (field=="entityIds" && !view_->sketchEntityVisible(value.toString()))
                || (field=="profileIds" && (!session_.value("displayOptions").toObject().value("showProfile").toBool(true)
                    || session_.value("displayOptions").toObject().value("hideFullyConstrained").toBool())))
                return failure("geometry_hidden","Show sketch geometry before selecting it",field);
            if(!ids.contains(value))ids.append(value);
        }
        normalized[field]=ids;
    }
    const auto constraintType=session_.value("constraintType").toString();
    if(session_.value("tool")=="constraint" && constraintType=="fixed"
        && normalized.value("pointIds").toArray().size()+normalized.value("entityIds").toArray().size()>1)
        return failure("invalid_constraint_target","Fix/UnFix requires one point, authored straight line, circle or arc");
    const bool analyticConstraint=session_.value("tool")=="constraint"
        && QStringList{"concentric","collinear","symmetry","tangent"}.contains(constraintType);
    if(analyticConstraint){
        const auto targets=normalized["entityIds"].toArray();
        const auto label=constraintType.first(1).toUpper()+constraintType.sliced(1);
        const auto retry=[&]{
            const auto count=session_.value("selection").toObject()["entityIds"].toArray().size();
            return constraintType=="symmetry" && count==2 ? QString("Pick construction axis")
                : count==0 ? QString("Pick first compatible curve") : QString("Pick a compatible second curve");
        };
        const auto rejectPick=[&](const QString& status,const QString& explanation){
            session_["constraintPickStatus"]=status;
            const auto message=label+" · "+(status=="unsupported_pair" ? "Unsupported pair: " : "Wrong type: ")+explanation;
            session_["constraintPrompt"]=message+" · "+retry()+" · Escape exits";
            return failure("invalid_constraint_target",message);
        };
        if(!normalized["pointIds"].toArray().isEmpty() || !normalized["profileIds"].toArray().isEmpty())
            return rejectPick("wrong_type","Select sketch curves, not points or profiles");
        if(targets.size()>(constraintType=="symmetry" ? 3 : 2))
            return rejectPick("wrong_type",constraintType=="symmetry" ? "Select two curves then one construction axis" : "Select two distinct curves");
        QStringList types;
        for(int index=0;index<targets.size();++index){
            QJsonObject entity;for(const auto& row:parameters["entities"].toArray())if(row.toObject()["id"]==targets[index]){entity=row.toObject();break;}
            const auto kind=entity["type"].toString();types.append(kind);
            if(constraintType=="symmetry" && index==2){
                if(kind!="line" || !entity["construction"].toBool())
                    return rejectPick("wrong_type","Third symmetry pick must be a construction line");
            }else if(constraintType=="concentric" && kind!="circle" && kind!="arc")
                return rejectPick("wrong_type","Concentric requires circles or arcs");
            else if(constraintType=="collinear" && kind!="line")
                return rejectPick("wrong_type","Collinear requires straight lines");
            else if((constraintType=="symmetry" && kind!="line" && kind!="circle" && kind!="arc")
                || (constraintType=="tangent" && kind!="line" && kind!="circle" && kind!="arc"))
                return rejectPick("wrong_type",label+" requires authored lines, circles or arcs");
        }
        if(constraintType=="tangent" && session_.contains("tangentEndpoint")){
            if(session_.value("tangentEndpoint").toString().contains(':')){
                for(const auto& kind:types)if(kind!="arc" && kind!="line")return rejectPick("wrong_type","Endpoint join requires two arcs or an arc and line");
                if(types.size()==2 && !types.contains("arc"))return rejectPick("unsupported_pair","Endpoint join requires an authored arc");
            }else {
            for(const auto& kind:types)if(kind!="arc" && kind!="circle")return rejectPick("wrong_type","Endpoint contact needs one arc and one full circle");
            if(types.size()==2 && !(types.contains("arc") && types.contains("circle")))return rejectPick("unsupported_pair","Endpoint contact needs one arc and one full circle");
            }
        }
        if(types.size()>=2){
            const auto first=types[0],second=types[1];
            if(constraintType=="symmetry" && first!=second)
                return rejectPick("unsupported_pair","Symmetry requires matching line-line, circle-circle or arc-arc geometry");
            if(constraintType=="tangent" && !((first=="circle" && second=="circle")
                || (first=="arc" && second=="arc") || (first=="arc" && second=="circle") || (first=="circle" && second=="arc")
                || (first=="line" && (second=="circle" || second=="arc"))
                || (second=="line" && (first=="circle" || first=="arc"))))
                return rejectPick("unsupported_pair",first=="line" && second=="line"
                    ? "Line-line Tangent is unavailable; use Collinear for a common line"
                    : "Select two authored circular curves, or one circular curve and a line");
        }
        session_["constraintPickStatus"]=targets.isEmpty() ? "pending_first" : "pending_next";
    }
    session_["selection"]=normalized;session_.remove("hoveredConstraintId");
    cancelDimension();
    if(session_.value("tool")=="constraint") {
        const auto type=session_.value("constraintType").toString();
        if(type=="midpoint"){
            const auto curves=normalized["entityIds"].toArray(),points=normalized["pointIds"].toArray();
            if(curves.size()>1 || points.size()>1)return failure("invalid_constraint_target","Midpoint requires one line or arc and one point");
            if(!curves.isEmpty()){
                bool supported=false;for(const auto& entry:parameters["entities"].toArray())if(entry.toObject()["id"]==curves[0])
                    supported=entry.toObject()["type"]=="line" || entry.toObject()["type"]=="arc";
                if(!supported)return failure("invalid_constraint_target","Midpoint requires a line or arc");
            }
            session_["constraintPrompt"]=curves.isEmpty() ? "Midpoint · Pick a line or arc · Escape exits"
                : "Midpoint · Pick a point or sketch origin · Escape exits";
            if(curves.size()==1 && points.size()==1){
                const auto result=applySketchConstraint(type,{{"entityIds",curves},{"pointIds",points}});
                if(result["ok"].isBool() && !result["ok"].toBool())return result;
                session_["selection"]=QJsonObject{{"pointIds",QJsonArray{}},{"entityIds",QJsonArray{}},{"profileIds",QJsonArray{}}};
                session_["constraintPrompt"]="Midpoint · Applied; pick next curve · Escape exits";
                auto completed=result;completed["constraintApplied"]=true;completed["constraintType"]=type;completed["selection"]=session_["selection"];return completed;
            }
            auto result=normalized;result["selection"]=normalized;return result;
        }
        const auto field=(type=="fixed" && normalized["entityIds"].toArray().isEmpty()) || type=="coincident" || (type=="horizontalVertical" && !normalized["pointIds"].toArray().isEmpty()) ? QString("pointIds") : QString("entityIds");
        const int required=type=="symmetry" ? 3 : type=="fixed" || type=="horizontal" || type=="vertical" || (type=="horizontalVertical" && field=="entityIds") ? 1 : 2;
        const auto targets=normalized[field].toArray();
        const auto label=type=="fixed" ? QString("Fix/UnFix") : type=="horizontalVertical" ? QString("Horizontal/Vertical") : type.first(1).toUpper()+type.sliced(1);
        session_["constraintPrompt"]=type=="fixed" ? QString("Fix/UnFix · Pick point, straight line, circle or arc; click fixed target to unfix · Escape exits") : type=="collinear" ? (targets.isEmpty() ? QString("Collinear · Pick first line")
            : QString("Collinear · Pick second line"))
            : type=="tangent" ? (targets.isEmpty() ? QString("Tangent · Pick curve or line")
            : QString("Tangent · Pick matching curve or line"))
            : type=="symmetry" ? (targets.size()==2 ? QString("Symmetry · Pick construction axis · Escape exits")
            : targets.isEmpty() ? QString("Symmetry · Pick first line, circle or arc · Escape exits") : QString("Symmetry · Pick matching line, circle or arc · Escape exits"))
            : QString("%1 · Pick %2 %3 · Escape exits").arg(label).arg(targets.isEmpty() ? "first" : "next").arg(field=="pointIds" ? "point" : "curve");
        if(type=="tangent" && session_.contains("tangentEndpoint"))session_["constraintPrompt"]=QString("Tangent · Arc %1 endpoint to circle · %2 · Escape exits")
            .arg(session_.value("tangentEndpoint").toString()).arg(targets.isEmpty() ? "Pick arc or circle" : "Pick matching arc or circle");
        if(type=="tangent" && session_.value("tangentEndpoint").toString().contains(':')){
            const auto roles=session_.value("tangentEndpoint").toString().split(':');
            session_["constraintPrompt"]=QString("Tangent · Pick %1 curve (%2 endpoint) · Arc–arc or arc–line · Escape exits").arg(targets.isEmpty() ? "first" : "second").arg(roles[targets.isEmpty() ? 0 : 1]);
        }
        if(targets.size()>required)return failure("invalid_constraint_target",QString("%1 requires %2 targets").arg(label).arg(required));
        if(type=="symmetry" && !normalized["pointIds"].toArray().isEmpty())return failure("invalid_constraint_target","Symmetry requires line, circle or arc picks");
        if(field=="entityIds")for(int index=0;index<targets.size();++index)for(const auto& entry:parameters["entities"].toArray()) {
            const auto target=targets[index];
            const auto entity=entry.toObject();if(entity["id"]!=target)continue;
            if(type!="equal" && type!="concentric" && type!="tangent" && type!="symmetry" && type!="fixed" && entity["type"]!="line")return failure("invalid_constraint_target",label+" requires lines");
            if(type=="concentric" && entity["type"]!="circle" && entity["type"]!="arc")return failure("invalid_constraint_target",label+" requires circles or arcs");
            if(type=="symmetry" && index==2 && !entity["construction"].toBool())return failure("invalid_constraint_target","Third symmetry pick must be a construction line");
        }
        if(targets.size()==required) {
            QJsonObject args{{field,targets}};
            if(type=="tangent" && session_.contains("tangentEndpoint"))args["endpoint"]=session_.value("tangentEndpoint");
            const auto result=applySketchConstraint(type,args);
            if(result["ok"].isBool() && !result["ok"].toBool()) {
                if(analyticConstraint){
                    auto pending=normalized;auto entities=pending["entityIds"].toArray();entities.removeLast();pending["entityIds"]=entities;
                    session_["selection"]=pending;
                }
                if(analyticConstraint)session_["constraintPickStatus"]="solve_failed";
                session_["constraintPrompt"]=type=="collinear" ? QString("Collinear · Failed; pick second line")
                    : type=="tangent" ? QString("Tangent · Failed; pick matching curve or line")
                    : analyticConstraint ? label+" · Constraint failed; "+result["error"].toObject()["message"].toString()+" · Pick another compatible curve · Escape exits"
                    : label+" · Constraint failed; pick a new set · Escape exits";return result;
            }
            session_["selection"]=QJsonObject{{"pointIds",QJsonArray{}},{"entityIds",QJsonArray{}},{"profileIds",QJsonArray{}}};
            if(analyticConstraint)session_["constraintPickStatus"]="applied";
            session_["constraintPrompt"]=type=="fixed" ? QString("Fix/UnFix · Pick point, straight line, circle or arc; click fixed target to unfix · Escape exits")
                : type=="collinear" ? QString("Collinear · Applied")
                : label+" · Applied; pick next "+(field=="pointIds" ? "point" : "curve")+" · Escape exits";
            auto completed=result;completed["constraintApplied"]=true;completed["constraintType"]=type;completed["selection"]=session_["selection"];return completed;
        }
    }
    if(session_.value("tool")=="dimension")refreshSketchControls();
    auto result=normalized;result["selection"]=normalized;return result;
}

QJsonObject AlloyWindow::sketchDimensionTargets(const QJsonObject& args) const {
    const auto selection=session_.value("selection").toObject();
    const auto parameters=SketchGeometry::expandedProjectionFeature(session_.value("draftSketch").toObject(),session_.value("projectionContext").toObject())["parameters"].toObject();
    auto points=args.contains("pointIds") ? args["pointIds"].toArray() : selection["pointIds"].toArray();
    for(const auto& chosen:points)for(const auto& available:session_.value("projectionContext").toObject()["points"].toArray()) {
        const auto point=available.toObject();
        if(point["id"]==chosen && !point.value("retained").toBool())
            throw std::invalid_argument("Snap a sketch line or circle to this support center before dimensioning it");
    }
    const auto entities=selection["entityIds"].toArray();
    const auto pair=args.contains("entityIds") ? args["entityIds"].toArray() : entities;
    if(args.value("kind")=="centerlineDiameter" || (args.value("kind").toString().isEmpty() && pair.size()==2)) {
        QJsonObject first,second;
        for(const auto& row:parameters["entities"].toArray()) {
            const auto e=row.toObject();if(e["id"]==(pair.size()>0 ? pair[0] : QJsonValue{}))first=e;if(e["id"]==(pair.size()>1 ? pair[1] : QJsonValue{}))second=e;
        }
        if(args.value("kind")=="centerlineDiameter" || first.value("centerline").toBool() || second.value("centerline").toBool()) {
            SketchGeometry::centerlineDiameterValue(session_.value("draftSketch").toObject(),pair,session_.value("projectionContext").toObject());
            return {{"entityIds",first.value("centerline").toBool() ? pair : QJsonArray{pair[1],pair[0]}},{"kind","centerlineDiameter"}};
        }
    }
    if(args.value("kind")=="parallelLineDistance" || (args.value("kind").toString().isEmpty() && pair.size()==2)) {
        QJsonObject target{{"entityIds",pair},{"kind","parallelLineDistance"}};
        try {if(sketchDimensionMeasure(target,"parallelLineDistance")>=.001)return target;}
        catch(const std::invalid_argument&) {if(args.value("kind")=="parallelLineDistance")throw;}
        if(args.value("kind")=="parallelLineDistance")throw std::invalid_argument("Distance requires separated parallel lines");
    }
    if(args.value("kind")=="angle" || (args.value("kind").toString().isEmpty() && (args.contains("entityIds") || entities.size()==2))) {
        const auto chosen=args.contains("entityIds") ? args.value("entityIds").toArray() : entities;
        if(chosen.size()!=2 || chosen[0]==chosen[1])throw std::invalid_argument("Select two distinct lines for an angle");
        QJsonArray found;for(const auto& id:chosen)for(const auto& value:parameters["entities"].toArray())if(value.toObject()["id"]==id && value.toObject()["type"]=="line"){found.append(id);break;}
        if(found.size()!=2)throw std::invalid_argument("Select two lines for an angle");
        QJsonObject result{{"entityIds",chosen}};if(args.contains("raySigns"))result["raySigns"]=args["raySigns"];return result;
    }
    if((args.value("kind")=="pointLineDistance" || (points.size()==1 && entities.size()==1)) && points.size()==1) {
        const auto chosen=args.contains("entityId") ? args["entityId"] : entities.size()==1 ? entities[0] : QJsonValue{};
        for(const auto& value:parameters["entities"].toArray())if(value.toObject()["id"]==chosen && value.toObject()["type"]=="line")return {{"pointIds",points},{"entityId",chosen}};
        throw std::invalid_argument("Point-edge dimension requires one straight line");
    }
    const auto entity=args.value("entityId").toString(points.isEmpty() && entities.size()==1 ? entities[0].toString() : QString{});
    if(args.contains("entityId") && entity.isEmpty())throw std::invalid_argument("The requested sketch line does not exist");
    if(!entity.isEmpty()) {
        if(args.contains("pointIds"))throw std::invalid_argument("Choose two points or one line for a dimension");
        bool found=false;points={};
        for(const auto& entry:parameters["entities"].toArray()) {
            const auto line=entry.toObject();if(line["id"]==entity){if(line["type"]!="line")return {{"entityId",entity}};points=QJsonArray{line["startPointId"],line["endPointId"]};found=true;break;}
        }
        if(!found)throw std::invalid_argument("The requested sketch line does not exist");
    }
    if(points.size()!=2 || points[0]==points[1])throw std::invalid_argument("Select one line or two distinct points for a dimension");
    return {{"pointIds",points}};
}

QJsonArray AlloyWindow::angleRaySigns(const QJsonArray& entityIds,const QJsonObject& annotation) const {
    if(entityIds.size()!=2)return {1,1};
    const auto parameters=SketchGeometry::expandedProjectionFeature(session_.value("draftSketch").toObject(),session_.value("projectionContext").toObject())["parameters"].toObject();
    QMap<QString,QPointF> points;for(const auto& value:parameters["points"].toArray()){const auto p=value.toObject();points[p["id"].toString()]={p["uMm"].toDouble(),p["vMm"].toDouble()};}
    QJsonArray lines;for(const auto& id:entityIds)for(const auto& value:parameters["entities"].toArray())if(value.toObject()["id"]==id){lines.append(value);break;}
    if(lines.size()!=2)return {1,1};
    auto start=[&](const QJsonValue& value){return points.value(value.toObject()["startPointId"].toString());};
    auto end=[&](const QJsonValue& value){return points.value(value.toObject()["endPointId"].toString());};
    const auto a=start(lines[0]),b=start(lines[1]),da=end(lines[0])-a,db=end(lines[1])-b;
    const double cross=da.x()*db.y()-da.y()*db.x();if(std::abs(cross)<1e-9)return {1,1};
    const auto offset=b-a;const QPointF origin=a+da*((offset.x()*db.y()-offset.y()*db.x())/cross);
    auto cursor=QPointF(annotation.value("uMm").toDouble(),annotation.value("vMm").toDouble())-origin;
    const double radius=std::hypot(cursor.x(),cursor.y());if(radius<1e-9)return {1,1};cursor/=radius;
    const auto unit=[](QPointF p){const double length=std::hypot(p.x(),p.y());return p/length;};
    const auto u=unit(da),v=unit(db);QJsonArray choice{1,1};
    for(int sa:{1,-1})for(int sb:{1,-1}){
        const auto first=u*sa,second=v*sb;
        const double sweep=std::atan2(first.x()*second.y()-first.y()*second.x(),first.x()*second.x()+first.y()*second.y());
        double offset=std::atan2(first.x()*cursor.y()-first.y()*cursor.x(),first.x()*cursor.x()+first.y()*cursor.y());
        if(sweep>0 && offset<0)offset+=2*std::numbers::pi;
        if(sweep<0 && offset>0)offset-=2*std::numbers::pi;
        if(sweep>0 ? offset>=0 && offset<=sweep : offset<=0 && offset>=sweep){choice={sa,sb};break;}
    }
    return choice;
}

void AlloyWindow::sketchResponse(const QJsonObject& response) {
    if(sketchError_){
        const auto conflict=session_.value("lastSolveFailure").toObject();
        sketchError_->setText(conflict.value("code")=="constraint_conflict" ? "Constraint conflict: "+conflict.value("message").toString()
            : response["ok"].toBool() ? "" : response["error"].toObject()["message"].toString());
        // Error feedback lives outside the scrolled palette. Reserve its wrapped
        // height after a refusal so the explanation cannot be compressed away.
        sketchError_->setMinimumHeight(sketchError_->text().isEmpty() ? 0
            : sketchError_->heightForWidth(std::max(80,sketchError_->contentsRect().width())));
        sketchError_->updateGeometry();
    }
    if(dimensionEditor_ && dimensionEditor_->isVisible() && !response.value("ok").toBool())dimensionEditorError_->setText(response.value("error").toObject().value("message").toString());
}

QJsonObject AlloyWindow::previewCircleDiameter(const QJsonObject& args) {
    const bool twoPoint=session_.value("tool")=="twoPointCircle";
    if(session_.value("command")!="sketch.edit" || (session_.value("tool")!="circle" && !twoPoint) || !session_.contains("firstPoint"))
        return failure("no_pending_circle","Click the first circle point first");
    if(args.contains("session") && args["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))
        return failure("stale_session","The document changed; cancel and restart this sketch");
    if(args.contains("text")==args.contains("value"))return failure("invalid_arguments","Supply either text or a numeric diameter");
    auto units=args.value("units").toString(session_.value("inputs").toObject().value("units").toString());
    if(units!="mm" && units!="in")return failure("invalid_units","Circle diameter uses mm or in");
    QString text;
    if(args.contains("text"))text=args["text"].toString();
    else text=QString::number(args["value"].toDouble(),'g',10)+" "+units;
    const QRegularExpression expression(QStringLiteral(R"(^\s*([+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*(mm|in)?\s*$)"),QRegularExpression::CaseInsensitiveOption);
    const auto match=expression.match(text);double diameterMm=0;bool valid=false;
    if(match.hasMatch()) {
        bool numberValid=false;const double value=match.captured(1).toDouble(&numberValid);
        if(!match.captured(2).isEmpty())units=match.captured(2).toLower();
        if(numberValid)diameterMm=CadDocument::millimeters(value,units);
        valid=numberValid && std::isfinite(diameterMm) && diameterMm>=0.002 && diameterMm<=100000;
    }
    const bool opening=!session_.contains("pendingCircleDiameter");
    QJsonObject pending{{"phase","editing"},{"text",text},{"valid",valid}};
    if(valid)pending["diameterMm"]=diameterMm;
    if(twoPoint) {
        const auto start=session_.value("firstPoint").toObject(),pointer=session_.value("pointerPoint").toObject();
        const double du=pointer["uMm"].toDouble()-start["uMm"].toDouble();
        const double dv=pointer["vMm"].toDouble()-start["vMm"].toDouble();
        const double length=std::hypot(du,dv);
        if(length<0.002)return failure("circle_direction_required","Move the pointer away from the first diameter endpoint before typing");
        pending["directionU"]=du/length;pending["directionV"]=dv/length;
    }
    session_["pendingCircleDiameter"]=pending;
    if(valid) {
        const auto first=session_.value("firstPoint").toObject();
        sketchCurveGesture({{"uMm",first["uMm"].toDouble()+diameterMm*(twoPoint ? pending["directionU"].toDouble() : 0.5)},
            {"vMm",first["vMm"].toDouble()+diameterMm*(twoPoint ? pending["directionV"].toDouble() : 0.0)}},false);
    } else view_->clearSketchCursor();
    if(opening)showCircleDiameterEditor(text);
    else {
        if(dimensionEditorValue_)dimensionEditorValue_->setReadOnly(false);
        if(dimensionEditorValue_ && dimensionEditorValue_->text()!=text) {
            const QSignalBlocker block(dimensionEditorValue_);dimensionEditorValue_->setText(text);
        }
        if(dimensionEditorError_)dimensionEditorError_->setText(valid ? "Enter accepts · Esc cancels" : "Enter a diameter from 0.002 to 100000 mm");
    }
    return {{"pendingCircleDiameter",pending},{"authoredChange",false}};
}

QJsonObject AlloyWindow::lockCircleDiameter(const QJsonObject& args) {
    if(!args.isEmpty() && (args.contains("text") || args.contains("value"))) {
        const auto preview=previewCircleDiameter(args);
        if(preview.value("ok").isBool() && !preview.value("ok").toBool())return preview;
    }
    if(session_.value("command")!="sketch.edit" || (session_.value("tool")!="circle" && session_.value("tool")!="twoPointCircle") || !session_.contains("firstPoint"))
        return failure("no_pending_circle","Click the first circle point first");
    if(args.contains("session") && args["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    auto pending=session_.value("pendingCircleDiameter").toObject();
    if(!pending.value("valid").toBool())return failure("invalid_circle_diameter","Enter a diameter from 0.002 to 100000 mm");
    pending["phase"]="locked";session_["pendingCircleDiameter"]=pending;
    const auto units=session_.value("inputs").toObject().value("units").toString("mm");
    if(dimensionEditorValue_)dimensionEditorValue_->setReadOnly(true);
    if(dimensionEditorError_)dimensionEditorError_->setText(QString::fromUtf8("Ø%1 %2 locked · Enter places · Esc cancels")
        .arg(QString::number(pending["diameterMm"].toDouble()/(units=="in" ? 25.4 : 1.0),'g',9),units));
    if(dimensionEditor_) {dimensionEditor_->adjustSize();positionDimensionEditor();dimensionEditor_->show();dimensionEditor_->raise();}
    return {{"pendingCircleDiameter",pending},{"authoredChange",false}};
}

QJsonObject AlloyWindow::acceptCircleDiameter(const QJsonObject& args) {
    if(!args.isEmpty() && (args.contains("text") || args.contains("value"))) {
        const auto preview=previewCircleDiameter(args);
        if(preview.value("ok").isBool() && !preview.value("ok").toBool())return preview;
    }
    const bool twoPoint=session_.value("tool")=="twoPointCircle";
    if(session_.value("command")!="sketch.edit" || (session_.value("tool")!="circle" && !twoPoint) || !session_.contains("firstPoint"))
        return failure("no_pending_circle","Click the first circle point first");
    if(args.contains("session") && args["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    const auto pending=session_.value("pendingCircleDiameter").toObject();
    if(!pending.value("valid").toBool())return failure("invalid_circle_diameter","Enter a diameter from 0.002 to 100000 mm");
    const auto first=session_["firstPoint"].toObject();const double diameterMm=pending["diameterMm"].toDouble();
    SketchGeometry::SolveResult solved;
    if(twoPoint)solved=SketchGeometry::addTwoPointCircle(session_["draftSketch"].toObject(),
        {{"startUMm",first["uMm"]},{"startVMm",first["vMm"]},{"directionU",pending["directionU"]},
         {"directionV",pending["directionV"]},{"diameterMm",diameterMm}},session_.value("projectionContext").toObject());
    else {
        QJsonObject canonical{{"centerUMm",first["uMm"]},{"centerVMm",first["vMm"]},
            {"diameterMm",diameterMm},{"drivingDiameterMm",diameterMm}};
        if(first["status"]=="acquired")canonical["centerSnapTarget"]=first["target"];
        solved=SketchGeometry::addPointerCircle(session_["draftSketch"].toObject(),canonical,session_.value("projectionContext").toObject());
    }
    const auto result=publishSketchSolve(solved);
    if(result.value("ok").isBool() && !result.value("ok").toBool())return result;
    cancelCircleDiameter();view_->setFocus();return result;
}

void AlloyWindow::cancelCircleDiameter() {
    if(!session_.contains("pendingCircleDiameter"))return;
    session_.remove("pendingCircleDiameter");
    if(dimensionEditor_)dimensionEditor_->hide();
    if(dimensionEditorValue_)dimensionEditorValue_->setReadOnly(false);
    view_->clearSketchCursor();
}

QJsonObject AlloyWindow::previewLineLength(const QJsonObject& args) {
    if(session_.value("command")!="sketch.edit" || session_.value("tool")!="line" || !session_.contains("firstPoint"))
        return failure("no_pending_line","Click the line start first");
    if(args.contains("session") && args["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))
        return failure("stale_session","The document changed; cancel and restart this sketch");
    if(args.contains("text")==args.contains("value"))return failure("invalid_arguments","Supply either text or a numeric length");
    auto units=args.value("units").toString(session_.value("inputs").toObject().value("units").toString());
    if(units!="mm" && units!="in")return failure("invalid_units","Line length uses mm or in");
    const auto valueText=args.contains("text") ? args["text"].toString() : QString::number(args["value"].toDouble(),'g',10)+" "+units;
    const QRegularExpression expression(QStringLiteral(R"(^\s*([+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*(mm|in)?\s*$)"),QRegularExpression::CaseInsensitiveOption);
    const auto match=expression.match(valueText);double lengthMm=0;bool valid=false;
    if(match.hasMatch()) {
        bool numberValid=false;const auto value=match.captured(1).toDouble(&numberValid);
        if(!match.captured(2).isEmpty())units=match.captured(2).toLower();
        if(numberValid)lengthMm=CadDocument::millimeters(value,units);
        valid=numberValid && std::isfinite(lengthMm) && lengthMm>=0.001 && lengthMm<=100000;
    }
    const bool opening=!session_.contains("pendingLineLength");
    const auto previous=session_.value("pendingLineLength").toObject();
    QJsonObject pending{{"phase","editing"},{"text",valueText},{"valid",valid}};
    if(previous.contains("angleText")){pending["angleText"]=previous["angleText"];pending["angleValid"]=previous["angleValid"];
        if(previous.contains("angleDeg"))pending["angleDeg"]=previous["angleDeg"];}
    if(valid)pending["lengthMm"]=lengthMm;
    session_["pendingLineLength"]=pending;
    if(lineLockCue_)lineLockCue_->hide();
    if(opening) {
        ensureSketchInlineEditor();twoPointWidthLabel_->hide();twoPointHeightLabel_->hide();centerRectangleHeight_->hide();
        lineLengthLabel_->show();
        lineAngleLabel_->show();lineAngleValue_->show();lineAngleValue_->clear();dimensionEditorValue_->setReadOnly(false);
        dimensionEditorValue_->installEventFilter(this);
        {const QSignalBlocker block(dimensionEditorValue_);dimensionEditorValue_->setText(valueText);}
        dimensionEditor_->adjustSize();positionDimensionEditor();dimensionEditor_->show();dimensionEditor_->raise();dimensionEditorValue_->setFocus();
        dimensionEditorValue_->setCursorPosition(valueText.size());
    }
    if(dimensionEditorError_)dimensionEditorError_->setText(valid ? "Tab locks length and opens Angle · Click places" : "Enter a length from 0.001 to 100000 mm");
    if(valid) {
        auto pointer=session_.value("pointerPoint").toObject();
        if(!pointer.isEmpty()) {
            const auto placed=lockedLinePoint(pointer);
            if(!placed.isEmpty())view_->showSketchCursor(session_.value("inputs").toObject()["plane"].toString(),
                {session_.value("firstPoint").toObject()["uMm"].toDouble(),session_.value("firstPoint").toObject()["vMm"].toDouble()},
                {placed["uMm"].toDouble(),placed["vMm"].toDouble()},false);
        }
    } else view_->clearSketchCursor();
    return {{"pendingLineLength",pending},{"authoredChange",false}};
}

QJsonObject AlloyWindow::lockLineLength(const QJsonObject& args) {
    if(!args.isEmpty() && (args.contains("text") || args.contains("value"))) {
        const auto preview=previewLineLength(args);
        if(preview.value("ok").isBool() && !preview.value("ok").toBool())return preview;
    }
    if(session_.value("command")!="sketch.edit" || session_.value("tool")!="line" || !session_.contains("firstPoint"))
        return failure("no_pending_line","Click the line start first");
    if(args.contains("session") && args["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    auto pending=session_.value("pendingLineLength").toObject();
    if(!pending.value("valid").toBool())return failure("invalid_line_length","Enter a length from 0.001 to 100000 mm");
    pending["phase"]="locked";session_["pendingLineLength"]=pending;
    ensureSketchInlineEditor();dimensionEditorValue_->setReadOnly(true);
    lineAngleLabel_->show();lineAngleValue_->show();
    dimensionEditor_->adjustSize();positionDimensionEditor();dimensionEditor_->show();dimensionEditor_->raise();
    lineAngleValue_->setFocus();lineAngleValue_->selectAll();
    const auto point=lockedLinePoint(session_.value("pointerPoint").toObject());
    if(!point.isEmpty())showLineLockCue(point);
    return {{"pendingLineLength",pending},{"authoredChange",false}};
}

QJsonObject AlloyWindow::previewLineAngle(const QJsonObject& args) {
    if(session_.value("command")!="sketch.edit" || session_.value("tool")!="line" ||
        session_.value("pendingLineLength").toObject().value("phase")!="locked")
        return failure("line_length_required","Lock a valid line length before entering an angle");
    if(args.contains("session") && args["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))
        return failure("stale_session","The document changed; cancel and restart this sketch");
    if(args.contains("text")==args.contains("valueDeg"))return failure("invalid_arguments","Supply text or a numeric angle");
    const auto valueText=args.contains("text") ? args["text"].toString() : QString::number(args["valueDeg"].toDouble(),'g',10);
    const QRegularExpression expression(QStringLiteral(R"(^\s*([+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*(?:deg|°)?\s*$)"),QRegularExpression::CaseInsensitiveOption);
    const auto match=expression.match(valueText);bool numeric=false;const double angle=match.hasMatch() ? match.captured(1).toDouble(&numeric) : 0;
    const bool valid=numeric && std::isfinite(angle) && angle>0 && angle<180;
    auto pending=session_.value("pendingLineLength").toObject();pending["angleText"]=valueText;pending["angleValid"]=valid;
    if(valid)pending["angleDeg"]=angle;else pending.remove("angleDeg");
    session_["pendingLineLength"]=pending;
    if(lineAngleValue_ && lineAngleValue_->text()!=valueText){const QSignalBlocker block(lineAngleValue_);lineAngleValue_->setText(valueText);}
    if(dimensionEditorError_)dimensionEditorError_->setText(valid ? "Tab locks angle · Move to choose ray · Click places" : "Enter an angle between 0 and 180°");
    const auto pointer=session_.value("pointerPoint").toObject();
    const auto point=lockedLinePoint(pointer);
    if(!point.isEmpty()){
        const auto first=session_.value("firstPoint").toObject();
        view_->showSketchCursor(session_.value("inputs").toObject()["plane"].toString(),
            {first["uMm"].toDouble(),first["vMm"].toDouble()},{point["uMm"].toDouble(),point["vMm"].toDouble()},false);
        if(lineLockCue_)lineLockCue_->hide();
    } else {view_->clearSketchCursor();if(lineLockCue_)lineLockCue_->hide();}
    return {{"pendingLineLength",pending},{"authoredChange",false}};
}

QJsonObject AlloyWindow::lockLineAngle(const QJsonObject& args) {
    if(args.contains("session") && args["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))
        return failure("stale_session","The document changed; cancel and restart this sketch");
    if(args.contains("text") || args.contains("valueDeg")) {
        const auto preview=previewLineAngle(args);
        if(preview.value("ok").isBool() && !preview.value("ok").toBool())return preview;
    }
    auto pending=session_.value("pendingLineLength").toObject();
    if(pending.value("phase")!="locked")return failure("line_length_required","Lock a line length first");
    if(!pending.value("angleValid").toBool())return failure("invalid_line_angle","Enter an angle between 0 and 180°");
    pending["angleLocked"]=true;session_["pendingLineLength"]=pending;
    if(dimensionEditor_)dimensionEditor_->hide();view_->setFocus();
    const auto point=lockedLinePoint(session_.value("pointerPoint").toObject());if(!point.isEmpty())showLineLockCue(point);
    return {{"pendingLineLength",pending},{"authoredChange",false}};
}

void AlloyWindow::cancelLineLength() {
    if(lineLockCue_)lineLockCue_->hide();
    if(!session_.contains("pendingLineLength"))return;
    session_.remove("pendingLineLength");if(dimensionEditor_)dimensionEditor_->hide();if(lineLockCue_)lineLockCue_->hide();view_->clearSketchCursor();
}

void AlloyWindow::showLineLockCue(const QJsonObject& point) {
    if(dimensionEditor_ && dimensionEditor_->isVisible() && session_.value("pendingLineLength").toObject().contains("angleText")){
        if(lineLockCue_)lineLockCue_->hide();return;
    }
    if(!lineLockCue_) {
        lineLockCue_=new QLabel(view_);lineLockCue_->setObjectName("sketch.lineLockCue");
        lineLockCue_->setAttribute(Qt::WA_TransparentForMouseEvents);
        lineLockCue_->setStyleSheet("background: #eaf5fc; color: #143f59; border: 1px solid #5b9fc6; border-radius: 3px; padding: 3px 6px; font-weight: 600;");
    }
    const auto units=session_.value("inputs").toObject().value("units").toString("mm");
    const auto direction=point["direction"]=="angled" ? QString::number(session_.value("pendingLineLength").toObject()["angleDeg"].toDouble(),'g',9)+"°"
        : point["direction"]=="horizontal" ? "H" : "V";
    const double scale=units=="in" ? 25.4 : 1.0;
    lineLockCue_->setText(QString("%1 %2  ·  %3").arg(QString::number(session_.value("pendingLineLength").toObject()["lengthMm"].toDouble()/scale,'g',9),units,direction));
    lineLockCue_->adjustSize();
    const auto screen=view_->projectSketchPoint(point["uMm"].toDouble(),point["vMm"].toDouble(),session_.value("inputs").toObject()["plane"].toString());
    lineLockCue_->move(std::clamp(qRound(screen["x"].toDouble()+15),0,std::max(0,view_->width()-lineLockCue_->width())),
        std::clamp(qRound(screen["y"].toDouble()+15),0,std::max(0,view_->height()-lineLockCue_->height())));
    lineLockCue_->show();lineLockCue_->raise();
}

QJsonObject AlloyWindow::lockedLinePoint(const QJsonObject& pointer) const {
    const auto first=session_.value("firstPoint").toObject(),pending=session_.value("pendingLineLength").toObject();
    if(!pending.value("valid").toBool())return {};
    const double du=pointer["uMm"].toDouble()-first["uMm"].toDouble(),dv=pointer["vMm"].toDouble()-first["vMm"].toDouble();
    if(std::max(std::abs(du),std::abs(dv))<0.001)return {};
    const double length=pending["lengthMm"].toDouble();const bool horizontal=std::abs(du)>std::abs(dv);
    if(pending.contains("angleText")) {
        if(!pending.value("angleValid").toBool())return {};
        const double radians=pending["angleDeg"].toDouble()*std::numbers::pi/180.0;
        const double sx=(du<0 ? -1 : 1)*(std::cos(radians)<0 ? -1 : 1),sy=dv<0 ? -1 : 1;
        return {{"uMm",first["uMm"].toDouble()+sx*length*std::cos(radians)},
            {"vMm",first["vMm"].toDouble()+sy*length*std::sin(radians)},
            {"direction","angled"},{"referenceDirection",sx<0 ? "negative" : "positive"}};
    }
    return {{"uMm",first["uMm"].toDouble()+(horizontal ? std::copysign(length,du) : 0)},
        {"vMm",first["vMm"].toDouble()+(horizontal ? 0 : std::copysign(length,dv))},
        {"direction",horizontal ? "horizontal" : "vertical"}};
}

QJsonObject AlloyWindow::previewCenterRectangle(const QJsonObject& args) {
    if(session_.value("command")!="sketch.edit" || session_.value("tool")!="centerRectangle" || !session_.contains("firstPoint"))
        return failure("no_pending_center_rectangle","Click the rectangle center first");
    if(args.contains("session") && args["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))
        return failure("stale_session","The document changed; cancel and restart this sketch");
    const auto prior=session_.value("pendingCenterRectangle").toObject();
    const QString widthText=args.value("widthText").toString(prior.value("widthText").toString());
    const QString heightText=args.value("heightText").toString(prior.value("heightText").toString());
    auto parse=[&](const QString& text)->double {
        const QRegularExpression expression(QStringLiteral(R"(^\s*([+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*(mm|in)?\s*$)"),QRegularExpression::CaseInsensitiveOption);
        const auto match=expression.match(text);if(!match.hasMatch())return 0;
        bool valid=false;const auto number=match.captured(1).toDouble(&valid);
        const auto units=match.captured(2).isEmpty() ? session_.value("inputs").toObject()["units"].toString() : match.captured(2).toLower();
        const double mm=valid ? CadDocument::millimeters(number,units) : 0;
        return std::isfinite(mm) && mm>=0.001 && mm<=100000 ? mm : 0;
    };
    const double width=parse(widthText),height=parse(heightText);
    QJsonObject pending{{"widthText",widthText},{"heightText",heightText},{"valid",width>0 && height>0}};
    if(width>0)pending["widthMm"]=width;if(height>0)pending["heightMm"]=height;
    const bool opening=prior.isEmpty();session_["pendingCenterRectangle"]=pending;
    const auto center=session_.value("firstPoint").toObject();
    if(width>0 && height>0)view_->showSketchCursor(session_.value("inputs").toObject()["plane"].toString(),
        {center["uMm"].toDouble(),center["vMm"].toDouble()},
        {center["uMm"].toDouble()+width/2,center["vMm"].toDouble()+height/2},true,true);
    else view_->clearSketchCursor();
    ensureSketchInlineEditor();lineLengthLabel_->hide();lineAngleLabel_->hide();lineAngleValue_->hide();twoPointWidthLabel_->hide();twoPointHeightLabel_->hide();centerRectangleHeight_->show();
    if(dimensionEditorValue_->text()!=widthText){const QSignalBlocker block(dimensionEditorValue_);dimensionEditorValue_->setText(widthText);}
    if(centerRectangleHeight_->text()!=heightText){const QSignalBlocker block(centerRectangleHeight_);centerRectangleHeight_->setText(heightText);}
    dimensionEditorValue_->setPlaceholderText("Width");centerRectangleHeight_->setPlaceholderText("Height");
    dimensionEditorError_->setText(pending["valid"].toBool() ? "Tab switches · Enter accepts · Esc cancels" : "Enter width and height");
    dimensionEditor_->adjustSize();positionDimensionEditor();dimensionEditor_->show();dimensionEditor_->raise();
    if(opening){dimensionEditorValue_->setFocus();dimensionEditorValue_->setCursorPosition(widthText.size());}
    return {{"pendingCenterRectangle",pending},{"authoredChange",false}};
}

QJsonObject AlloyWindow::acceptCenterRectangle(const QJsonObject& args) {
    if(args.contains("widthText") || args.contains("heightText")) {
        const auto preview=previewCenterRectangle(args);
        if(preview.value("ok").isBool() && !preview.value("ok").toBool())return preview;
    }
    if(session_.value("command")!="sketch.edit" || session_.value("tool")!="centerRectangle" || !session_.contains("firstPoint"))
        return failure("no_pending_center_rectangle","Click the rectangle center first");
    const auto pending=session_.value("pendingCenterRectangle").toObject();
    if(!pending["valid"].toBool())return failure("invalid_dimensions","Enter positive width and height");
    const auto center=session_.value("firstPoint").toObject();
    QJsonObject input{{"centerX",center["uMm"]},{"centerY",center["vMm"]},
        {"width",pending["widthMm"]},{"height",pending["heightMm"]},{"units","mm"}};
    if(center["status"]=="acquired")input["centerSnapTarget"]=center["target"];
    const auto result=appendCenterRectangle(input);
    if(!result.value("ok").isBool() || result.value("ok").toBool()){cancelCenterRectangle();view_->setFocus();}
    return result;
}

void AlloyWindow::cancelCenterRectangle() {
    if(!session_.contains("pendingCenterRectangle"))return;
    session_.remove("pendingCenterRectangle");if(dimensionEditor_)dimensionEditor_->hide();view_->clearSketchCursor();
}

QJsonObject AlloyWindow::previewTwoPointRectangle(const QJsonObject& args) {
    if(session_.value("command")!="sketch.edit" || session_.value("tool")!="rectangle" || !session_.contains("firstPoint"))
        return failure("no_pending_rectangle","Click the first rectangle corner first");
    if(args.contains("session") && args["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))
        return failure("stale_session","The document changed; cancel and restart this sketch");
    const auto prior=session_.value("pendingTwoPointRectangle").toObject();
    const QString widthText=args.value("widthText").toString(prior.value("widthText").toString());
    const QString heightText=args.value("heightText").toString(prior.value("heightText").toString());
    auto parse=[&](const QString& value)->double {
        const QRegularExpression expression(QStringLiteral(R"(^\s*([+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*(mm|in)?\s*$)"),QRegularExpression::CaseInsensitiveOption);
        const auto match=expression.match(value);if(!match.hasMatch())return 0;
        bool valid=false;const double number=match.captured(1).toDouble(&valid);
        const auto units=match.captured(2).isEmpty() ? session_.value("inputs").toObject()["units"].toString() : match.captured(2).toLower();
        const double mm=valid ? CadDocument::millimeters(number,units) : 0;
        return std::isfinite(mm) && mm>=0.001 && mm<=100000 ? mm : 0;
    };
    const double width=parse(widthText),height=parse(heightText);
    QJsonObject pending{{"widthText",widthText},{"heightText",heightText},{"phase","editing"},{"valid",width>0 && height>0}};
    if(width>0)pending["widthMm"]=width;if(height>0)pending["heightMm"]=height;
    const auto first=session_.value("firstPoint").toObject(),pointer=session_.value("pointerPoint").toObject();
    const double du=pointer.value("uMm").toDouble(first["uMm"].toDouble())-first["uMm"].toDouble();
    const double dv=pointer.value("vMm").toDouble(first["vMm"].toDouble())-first["vMm"].toDouble();
    if(std::abs(du)>=0.001 && std::abs(dv)>=0.001){pending["uSign"]=du>0 ? 1 : -1;pending["vSign"]=dv>0 ? 1 : -1;}
    session_["pendingTwoPointRectangle"]=pending;
    if(pending["valid"].toBool() && pending.contains("uSign"))view_->showSketchCursor(session_.value("inputs").toObject()["plane"].toString(),
        {first["uMm"].toDouble(),first["vMm"].toDouble()},
        {first["uMm"].toDouble()+pending["uSign"].toInt()*width,first["vMm"].toDouble()+pending["vSign"].toInt()*height},true,false);
    else view_->clearSketchCursor();
    ensureSketchInlineEditor();lineLengthLabel_->hide();lineAngleLabel_->hide();lineAngleValue_->hide();twoPointWidthLabel_->show();twoPointHeightLabel_->show();centerRectangleHeight_->show();
    if(dimensionEditorValue_->text()!=widthText){const QSignalBlocker block(dimensionEditorValue_);dimensionEditorValue_->setText(widthText);}
    if(centerRectangleHeight_->text()!=heightText){const QSignalBlocker block(centerRectangleHeight_);centerRectangleHeight_->setText(heightText);}
    dimensionEditorValue_->setReadOnly(false);dimensionEditorValue_->setPlaceholderText("Width");centerRectangleHeight_->setPlaceholderText("Height");
    dimensionEditorError_->setText(!pending.contains("uSign") ? "Move pointer into a quadrant · Tab switches fields" :
        pending["valid"].toBool() ? "Width × height · Tab switches · Enter places · Esc cancels" : "Enter positive width and height");
    dimensionEditor_->adjustSize();positionDimensionEditor();dimensionEditor_->show();dimensionEditor_->raise();
    if(prior.isEmpty()){dimensionEditorValue_->setFocus();dimensionEditorValue_->setCursorPosition(widthText.size());}
    return {{"pendingTwoPointRectangle",pending},{"authoredChange",false}};
}

QJsonObject AlloyWindow::acceptTwoPointRectangle(const QJsonObject& args) {
    if(args.contains("widthText") || args.contains("heightText")) {
        const auto preview=previewTwoPointRectangle(args);
        if(preview.value("ok").isBool() && !preview.value("ok").toBool())return preview;
    }
    if(session_.value("command")!="sketch.edit" || session_.value("tool")!="rectangle" || !session_.contains("firstPoint"))
        return failure("no_pending_rectangle","Click the first rectangle corner first");
    const auto pending=session_.value("pendingTwoPointRectangle").toObject();
    if(!pending.value("valid").toBool())return failure("invalid_dimensions","Enter positive width and height");
    if(!pending.contains("uSign") || !pending.contains("vSign"))return failure("rectangle_quadrant_required","Move the pointer into the intended rectangle quadrant");
    const auto first=session_.value("firstPoint").toObject();
    QJsonObject input{{"x1",first["uMm"]},{"y1",first["vMm"]},
        {"x2",first["uMm"].toDouble()+pending["uSign"].toInt()*pending["widthMm"].toDouble()},
        {"y2",first["vMm"].toDouble()+pending["vSign"].toInt()*pending["heightMm"].toDouble()},
        {"typedWidthMm",pending["widthMm"]},{"typedHeightMm",pending["heightMm"]},{"units","mm"}};
    if(first["status"]=="acquired")input["startSnapTarget"]=first["target"];
    const auto response=appendSketchEntity("rectangle",input);
    if(!response.value("ok").isBool() || response.value("ok").toBool()) {
        cancelTwoPointRectangle();session_.remove("firstPoint");session_.remove("pointerPoint");view_->setFocus();
    }
    return response;
}

void AlloyWindow::cancelTwoPointRectangle() {
    if(!session_.contains("pendingTwoPointRectangle"))return;
    session_.remove("pendingTwoPointRectangle");if(dimensionEditor_)dimensionEditor_->hide();
    if(twoPointWidthLabel_)twoPointWidthLabel_->hide();if(twoPointHeightLabel_)twoPointHeightLabel_->hide();view_->clearSketchCursor();
}

void AlloyWindow::cancelDimension() {
    if(session_.value("pendingDimension").toObject().value("chamferPending").toBool())cancelChamfer();
    session_.remove("pendingDimension");
    if(dimensionEditor_)dimensionEditor_->hide();
}
QJsonObject AlloyWindow::previewDimension(const QJsonObject& args) {
    if(session_.value("command")!="sketch.edit")return failure("no_active_sketch","Enter a sketch first");
    if(args.contains("session") && args["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))return failure("stale_session","The document changed; cancel and restart this sketch");
    if(session_.value("pendingDimension").toObject().value("phase")=="editing")return failure("dimension_input_active","Accept or cancel the current value first");
    auto pending=session_.value("pendingDimension").toObject();auto targets=sketchDimensionTargets({});
    const auto draft=session_.value("draftSketch").toObject();const auto plane=session_.value("inputs").toObject().value("plane").toString();
    const auto geometry=SketchGeometry::expandedProjectionFeature(draft,session_.value("projectionContext").toObject())["parameters"].toObject();
    const auto placement=view_->sketchPoint(args.value("x").toDouble(),args.value("y").toDouble(),plane);
    QMap<QString,QPointF> points;
    for(const auto& entry:geometry.value("points").toArray()){const auto p=entry.toObject();points[p.value("id").toString()]={p.value("uMm").toDouble(),p.value("vMm").toDouble()};}
    const auto ids=targets.value("pointIds").toArray();
    const auto orientation=args.value("kind").toString(pending.value("orientation").toString("auto"));QString kind=orientation;
    if(targets.contains("entityId") && targets["pointIds"].toArray().size()==1)kind="pointLineDistance";
    else if(targets.contains("entityIds"))kind=targets.value("kind").toString("angle");
    else if(targets.contains("entityId")) {
        QJsonObject entity;for(const auto& entry:geometry["entities"].toArray())if(entry.toObject()["id"]==targets["entityId"]){entity=entry.toObject();break;}
        if(entity["type"]=="ellipse")return failure("ellipse_axis_required","Select either full construction axis to dimension the ellipse");
        if(kind=="auto")kind=entity["type"]=="circle" ? "diameter" : "radius";
    } else if(kind=="auto") {
        if(ids.size()!=2 || !points.contains(ids[0].toString()) || !points.contains(ids[1].toString()))return failure("stale_entity","Dimension targets do not exist");
        const auto a=points.value(ids[0].toString()),b=points.value(ids[1].toString());
        const double du=std::abs(b.x()-a.x()),dv=std::abs(b.y()-a.y());
        const double u=placement.value("uMm").toDouble(),v=placement.value("vMm").toDouble();
        const auto selection=session_.value("selection").toObject();
        const bool singleLine=selection.value("entityIds").toArray().size()==1 && selection.value("pointIds").toArray().isEmpty();
        // Alloy policy: nearby placement on an oblique selected line means its
        // aligned length. Farther placement still exposes axis projections.
        constexpr double alignedBandPx=96;
        bool nearObliqueLine=false;
        if(singleLine && du>=1e-7 && dv>=1e-7){
            const auto pa=view_->projectSketchPoint(a.x(),a.y(),plane),pb=view_->projectSketchPoint(b.x(),b.y(),plane);
            const QPointF start(pa["x"].toDouble(),pa["y"].toDouble()),end(pb["x"].toDouble(),pb["y"].toDouble());
            const QPointF cursor(args.value("x").toDouble(),args.value("y").toDouble()),span=end-start;
            const double length2=span.x()*span.x()+span.y()*span.y();
            if(length2>1e-8){
                const double t=std::clamp(((cursor.x()-start.x())*span.x()+(cursor.y()-start.y())*span.y())/length2,0.0,1.0);
                const auto closest=start+span*t;
                nearObliqueLine=std::hypot(cursor.x()-closest.x(),cursor.y()-closest.y())<=alignedBandPx;
            }
        }
        if(dv<1e-7)kind="horizontal";else if(du<1e-7)kind="vertical";
        else if(nearObliqueLine)kind="linear";
        else if(v<std::min(a.y(),b.y()) || v>std::max(a.y(),b.y()))kind="horizontal";
        else if(u<std::min(a.x(),b.x()) || u>std::max(a.x(),b.x()))kind="vertical";else kind="linear";
    }
    if(kind=="angle")targets["raySigns"]=angleRaySigns(targets["entityIds"].toArray(),{{"uMm",placement.value("uMm")},{"vMm",placement.value("vMm")}});
    const double value=sketchDimensionMeasure(targets,kind);
    if(value<1e-6)return failure("invalid_dimension","This orientation has no measurable span");
    const bool driving=args.value("driving").toBool(pending.value("driving").toBool(sketchDimensionDriving_ ? sketchDimensionDriving_->isChecked() : true));
    pending=targets;pending["phase"]="placing";pending["kind"]=kind;pending["orientation"]=orientation;
    pending["driving"]=driving;
    pending["annotation"]=QJsonObject{{"uMm",placement.value("uMm")},{"vMm",placement.value("vMm")}};
    pending[kind=="arcSweep" || kind=="angle" || kind=="overallSlotAngle" ? "measuredValueDeg" : "measuredValueMm"]=value;
    if(kind=="parallelLineDistance") {
        const auto chosen=targets["entityIds"].toArray();
        for(const auto& row:draft["parameters"].toObject()["dimensions"].toArray()) {
            const auto existing=row.toObject();const auto ids=existing["entityIds"].toArray();
            if(existing["kind"]==kind && ids.size()==2 && (ids==chosen || (ids[0]==chosen[1] && ids[1]==chosen[0]))) {
                pending["dimensionId"]=existing["id"];
                pending["driving"]=existing["driving"];
                pending["annotation"]=existing["annotation"];
                for(const auto* key:{"name","expression","expressionUnits","referenceIds","parameterId"})
                    if(existing.contains(key))pending[key]=existing.value(key);
                break;
            }
        }
    }
    session_["tool"]="dimension";session_["pendingDimension"]=pending;return pending;
}
QJsonObject AlloyWindow::acceptDimension(const QJsonObject& args) {
    if(session_.value("command")!="sketch.edit")return failure("no_active_sketch","Enter a sketch first");
    if(args.contains("session") && args["session"]!=session_.value("id"))return failure("invalid_session","Session is no longer active");
    const auto pending=session_.value("pendingDimension").toObject();if(pending.value("phase")!="editing")return failure("no_pending_dimension","Place or edit a dimension first");
    if(pending.contains("chamferId")){
        if(!pending.value("driving").toBool()){cancelDimension();view_->setFocus();return {{"authoredChange",false}};}
        const bool angular=pending.value("chamferAngle").toBool();
        if((args.contains("text") && (args.contains("value") || args.contains("valueDeg"))) || args.contains(angular?"value":"valueDeg"))return failure("invalid_arguments","Enter one Chamfer quantity with the appropriate units");
        auto units=args.value("units").toString(session_.value("inputs").toObject().value("units").toString());double value=0;
        if(args.contains(angular?"valueDeg":"value"))value=args.value(angular?"valueDeg":"value").toDouble();
        else {
            const QRegularExpression expression(angular?QStringLiteral(R"(^\s*([+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*(deg|°)?\s*$)")
                :QStringLiteral(R"(^\s*([+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*(mm|in)?\s*$)"),QRegularExpression::CaseInsensitiveOption);
            const auto match=expression.match(args.value("text").toString(dimensionEditorValue_?dimensionEditorValue_->text():QString{}));
            if(!match.hasMatch())return failure("invalid_dimension_value",angular?"Enter a positive Chamfer angle with optional deg or degree sign":"Enter a positive Chamfer distance with optional mm or in");
            bool valid=false;value=match.captured(1).toDouble(&valid);if(!valid)return failure("invalid_dimension_value","Chamfer quantity is outside the supported range");
            if(!angular && !match.captured(2).isEmpty())units=match.captured(2).toLower();
        }
        QJsonObject mutation{{angular?"angleDeg":pending.value("chamferSide").toInt()==1?"value2":"value",value},{"units",units}};
        if(!pending.value("chamferPending").toBool())mutation["chamferId"]=pending.value("chamferId");
        const auto response=execute(pending.value("chamferPending").toBool()?"sketch.chamferAccept":"sketch.chamferUpdate",mutation);
        if(!response.value("ok").toBool())return response;
        cancelDimension();view_->setFocus();return response.value("result").toObject();
    }
    if(pending.contains("polygonId")){
        if(args.contains("valueDeg") || (args.contains("text") && args.contains("value")))return failure("invalid_arguments","Enter one Polygon length quantity");
        auto units=args.value("units").toString(session_.value("inputs").toObject()["units"].toString());double value=0;
        if(args.contains("value"))value=args["value"].toDouble();
        else {
            const QRegularExpression expression(QStringLiteral(R"(^\s*([+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*(mm|in)?\s*$)"),QRegularExpression::CaseInsensitiveOption);
            const auto match=expression.match(args.value("text").toString(dimensionEditorValue_ ? dimensionEditorValue_->text() : QString{}));
            if(!match.hasMatch())return failure("invalid_dimension_value","Enter a positive Polygon size with optional mm or in");
            bool valid=false;value=match.captured(1).toDouble(&valid);if(!valid)return failure("invalid_dimension_value","Polygon size is outside the supported range");
            if(!match.captured(2).isEmpty())units=match.captured(2).toLower();
        }
        const auto response=execute("sketch.polygonUpdate",{{"polygonId",pending["polygonId"]},{"size",value},{"units",units}});
        if(!response["ok"].toBool())return response;
        cancelDimension();session_["selection"]=QJsonObject{{"pointIds",QJsonArray{}},{"entityIds",QJsonArray{}}};view_->setFocus();return response["result"].toObject();
    }
    const bool angular=pending["kind"]=="arcSweep" || pending["kind"]=="angle" || pending["kind"]=="overallSlotAngle";
    if((args.contains("text") && (args.contains("value") || args.contains("valueDeg"))) || args.contains(angular ? "value" : "valueDeg"))
        return failure("invalid_arguments","Choose text or a numeric quantity with appropriate units");
    const bool driving=pending.value("driving").toBool();double valueMm=pending.value(angular ? "measuredValueDeg" : "measuredValueMm").toDouble();
    QJsonObject bound,formula;
    if(driving) {
        QString units=args.value("units").toString(session_.value("inputs").toObject().value("units").toString());double value=0;
        if(args.contains(angular ? "valueDeg" : "value"))value=args.value(angular ? "valueDeg" : "value").toDouble();
        else {
            const QString text=args.value("text").toString(dimensionEditorValue_ ? dimensionEditorValue_->text() : QString{});
            if(angular && pending["kind"]=="angle")bound=lengthParameter(text.trimmed(),true);
            if(!angular) {
                const auto token=text.trimmed();bool local=false;
                for(const auto& entry:session_.value("draftSketch").toObject().value("parameters").toObject().value("dimensions").toArray())
                    if(entry.toObject().value("name")==token)local=true;
                const auto user=lengthParameter(token);
                const bool unchangedFormula=pending.contains("expression") && pending.value("expression").toString()==token;
                const bool unchangedBinding=!user.isEmpty() && pending.value("parameterId")==user.value("id");
                if(local && !user.isEmpty() && !unchangedFormula && !unchangedBinding)
                    return failure("ambiguous_parameter","This name identifies both a sketch dimension and a user parameter");
                if(!unchangedFormula && (!local || unchangedBinding))bound=user;
            }
            if(!bound.isEmpty()) {valueMm=bound[angular ? "valueDeg" : "valueMm"].toDouble();value=!angular && units=="in" ? valueMm/25.4 : valueMm;}
            else {
            const QRegularExpression expression(angular ? QStringLiteral(R"(^\s*([+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*(deg|°)?\s*$)")
                : QStringLiteral(R"(^\s*([+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*(mm|in)?\s*$)"),QRegularExpression::CaseInsensitiveOption);
            const auto match=expression.match(text);
            if(!match.hasMatch() || (pending.contains("expression") && pending.value("expression").toString()==text.trimmed())) {
                if(angular)return failure("invalid_dimension_value","Enter a positive angle with optional deg or °");
                formula={{"expression",text.trimmed()},{"expressionUnits",!args.contains("units") && pending.value("expression").toString()==text.trimmed()
                    ? pending.value("expressionUnits") : QJsonValue(units)}};
            } else {
                bool ok=false;value=match.captured(1).toDouble(&ok);if(!ok)return failure("invalid_dimension_value","Dimension is outside the supported numeric range");
                if(!angular && !match.captured(2).isEmpty())units=match.captured(2).toLower();
            }
            }
        }
        if(formula.isEmpty() && bound.isEmpty())valueMm=angular ? value : CadDocument::millimeters(value,units);
        if(formula.isEmpty() && (!std::isfinite(valueMm) || valueMm<0.000001 || (angular ? valueMm>=(pending["kind"]=="angle" ? 180 : 360) : valueMm>100000)))return failure("invalid_dimension_value",angular ? "Angle must be greater than zero and below its supported limit" : "Dimension must be 0.000001..100000 mm");
    }
    const auto draft=session_.value("draftSketch").toObject();QJsonObject result;
    if(pending.contains("dimensionId")) {
        if(!driving){cancelDimension();view_->setFocus();return {{"authoredChange",false}};}
        QJsonObject mutation{{"dimensionId",pending.value("dimensionId")},{angular ? "valueDeg" : "valueMm",valueMm}};
        if(!bound.isEmpty())mutation["parameterId"]=bound["id"];
        if(!formula.isEmpty()){mutation.remove("valueMm");for(auto it=formula.begin();it!=formula.end();++it)mutation[it.key()]=it.value();}
        result=publishSketchSolve(SketchGeometry::updateDimension(draft,mutation,session_.value("projectionContext").toObject(),userLengthNames()));
    } else {
        QJsonObject mutation{{"pointIds",pending.value("pointIds")},{"kind",pending.value("kind")},{"driving",driving},{"annotation",pending.value("annotation")}};
        if(pending.contains("entityId")){if(pending["kind"]!="pointLineDistance")mutation.remove("pointIds");mutation["entityId"]=pending["entityId"];}
        if(pending.contains("entityIds")){mutation.remove("pointIds");mutation["entityIds"]=pending["entityIds"];if(pending["kind"]=="angle")mutation["raySigns"]=pending["raySigns"];}
        if(driving)mutation[angular ? "valueDeg" : "valueMm"]=valueMm;
        if(!bound.isEmpty())mutation["parameterId"]=bound["id"];
        if(!formula.isEmpty()){mutation.remove("valueMm");for(auto it=formula.begin();it!=formula.end();++it)mutation[it.key()]=it.value();}
        result=publishNewDimension(draft,mutation);
    }
    if(result.value("pending").toBool())return result;
    if(result.value("ok").isBool() && !result.value("ok").toBool())return result;
    cancelDimension();session_["selection"]=QJsonObject{{"pointIds",QJsonArray{}},{"entityIds",QJsonArray{}}};view_->setFocus();return result;
}
QJsonObject AlloyWindow::editDimension(const QString& id) {
    if(session_.value("command")!="sketch.edit")return failure("no_active_sketch","Enter a sketch first");
    if(session_.value("baseDocumentRevision").toInteger()!=static_cast<qint64>(document_->revision()))return failure("stale_session","The document changed; cancel and restart this sketch");
    for(const auto& row:view_->annotations()){
        const auto layout=row.toObject();if(layout.value("dimensionId")!=id || layout.value("chamferId").toString().isEmpty())continue;
        cancelDimension();
        const bool angular=layout.value("kind")=="chamferAngle";
        QJsonObject dimension{{"dimensionId",id},{"chamferId",layout.value("chamferId")},{"kind",angular?"angle":"chamferDistance"},{"chamferAngle",angular},
            {"phase","editing"},{"driving",layout.value("driving")},{"chamferSide",layout.value("independentSecond").toBool()?1:0},{angular?"measuredValueDeg":"measuredValueMm",layout.value(angular?"valueDeg":"valueMm")},
            {"annotation",layout.value("annotation")},{"name",angular?"Chamfer angle":layout.value("driving").toBool()?"Chamfer distance":"Equal setback (driven)"},
            {"chamferPending",session_.contains("pendingChamfer")}};
        session_["pendingDimension"]=dimension;showDimensionEditor();return dimension;
    }
    QJsonObject dimension;for(const auto& entry:session_.value("draftSketch").toObject()["parameters"].toObject()["dimensions"].toArray())if(entry.toObject()["id"]==id){dimension=entry.toObject();break;}
    if(dimension.isEmpty())for(const auto& row:session_.value("draftSketch").toObject()["parameters"].toObject()["polygonGroups"].toArray()){
        const auto group=row.toObject();if(group["id"]!=id)continue;
        dimension={{"id",id},{"polygonId",id},{"kind","polygonSize"},{"driving",true},{"valueMm",group["sizeMm"]},
            {"name",group["mode"]=="edge" ? "Polygon base edge" : group["mode"]=="circumscribed" ? "Polygon inradius" : "Polygon circumradius"}};break;
    }
    if(dimension.isEmpty())return failure("stale_entity","Dimension does not exist");
    const auto valueKey=dimension["kind"]=="arcSweep" || dimension["kind"]=="angle" || dimension["kind"]=="overallSlotAngle" ? "valueDeg" : "valueMm";
    double value=dimension.value(valueKey).toDouble();for(const auto& entry:session_.value("solverDiagnostics").toObject().value("dimensionValues").toArray())if(entry.toObject().value("id")==id)value=entry.toObject().value(valueKey).toDouble();
    const auto layoutFeature=SketchGeometry::expandedProjectionFeature(session_.value("draftSketch").toObject(),session_.value("projectionContext").toObject());
    const auto layout=view_->dimensionLayout(layoutFeature,dimension,value,session_.value("inputs").toObject().value("units").toString());
    if(layout.isEmpty())return failure("annotation_unavailable","Look At the sketch plane before editing this label");
    cancelDimension();dimension["dimensionId"]=id;dimension["phase"]="editing";dimension["annotation"]=layout.value("annotation");dimension[dimension["kind"]=="arcSweep" || dimension["kind"]=="angle" || dimension["kind"]=="overallSlotAngle" ? "measuredValueDeg" : "measuredValueMm"]=value;
    session_["pendingDimension"]=dimension;auto selection=session_.value("selection").toObject();selection.remove("constraintIds");session_.remove("hoveredConstraintId");selection["dimensionId"]=id;session_["selection"]=selection;showDimensionEditor();return dimension;
}
void AlloyWindow::ensureSketchInlineEditor() {
    if(!dimensionEditor_) {
        dimensionEditor_=new QFrame(view_);dimensionEditor_->setObjectName("sketchInlineEditor");dimensionEditor_->setAttribute(Qt::WA_NativeWindow);dimensionEditor_->setAutoFillBackground(true);
        dimensionEditor_->setFixedWidth(245);dimensionEditor_->setStyleSheet("#sketchInlineEditor { background: #f7f8f9; border: 1px solid #9aabb8; } QLineEdit { background: white; color: #20252a; padding: 5px; }");
        auto* layout=new QVBoxLayout(dimensionEditor_);layout->setContentsMargins(7,7,7,7);layout->setSpacing(4);
        twoPointWidthLabel_=new QLabel("Width");twoPointWidthLabel_->setObjectName("sketch.twoPointRectangle.widthLabel");layout->addWidget(twoPointWidthLabel_);twoPointWidthLabel_->hide();
        lineLengthLabel_=new QLabel("Length");lineLengthLabel_->setObjectName("sketch.lineLengthLabel");layout->addWidget(lineLengthLabel_);lineLengthLabel_->hide();
        dimensionEditorValue_=new QLineEdit;dimensionEditorValue_->setObjectName("sketch.inlineValue");layout->addWidget(dimensionEditorValue_);
        lineAngleLabel_=new QLabel("Angle");lineAngleLabel_->setObjectName("sketch.lineAngleLabel");layout->addWidget(lineAngleLabel_);lineAngleLabel_->hide();
        lineAngleValue_=new QLineEdit;lineAngleValue_->setObjectName("sketch.lineAngleValue");lineAngleValue_->setPlaceholderText("Angle (deg)");layout->addWidget(lineAngleValue_);lineAngleValue_->installEventFilter(this);lineAngleValue_->hide();
        twoPointHeightLabel_=new QLabel("Height");twoPointHeightLabel_->setObjectName("sketch.twoPointRectangle.heightLabel");layout->addWidget(twoPointHeightLabel_);twoPointHeightLabel_->hide();
        centerRectangleHeight_=new QLineEdit;centerRectangleHeight_->setObjectName("sketch.centerRectangle.height");layout->addWidget(centerRectangleHeight_);centerRectangleHeight_->hide();
        dimensionEditorError_=new QLabel;dimensionEditorError_->setWordWrap(true);dimensionEditorError_->setStyleSheet("color: #53616b; font-size: 11px; background: #f7f8f9;");layout->addWidget(dimensionEditorError_);
        connect(dimensionEditorValue_,&QLineEdit::returnPressed,this,[this]{
            if(session_.contains("pendingTwoPointRectangle"))
                sketchResponse(execute("sketch.twoPointRectangleAccept",{{"widthText",dimensionEditorValue_->text()},{"heightText",centerRectangleHeight_->text()}}));
            else if(session_.contains("pendingCenterRectangle"))
                sketchResponse(execute("sketch.centerRectangleAccept",{{"widthText",dimensionEditorValue_->text()},{"heightText",centerRectangleHeight_->text()}}));
            else if(session_.contains("pendingLineLength"))sketchResponse(execute("sketch.lineLengthLock",{{"text",dimensionEditorValue_->text()}}));
            else sketchResponse(execute(session_.contains("pendingCircleDiameter") ? "sketch.circleDiameterAccept" : "sketch.dimensionAccept",
                {{"text",dimensionEditorValue_->text()}}));
        });
        connect(dimensionEditorValue_,&QLineEdit::textChanged,this,[this](const QString& text){
            if(session_.contains("pendingCircleDiameter"))sketchResponse(execute("sketch.circleDiameterPreview",{{"text",text}}));
            if(session_.value("pendingLineLength").toObject().value("phase")=="editing")sketchResponse(execute("sketch.lineLengthPreview",{{"text",text}}));
            if(session_.contains("pendingCenterRectangle"))sketchResponse(execute("sketch.centerRectanglePreview",{{"widthText",text},{"heightText",centerRectangleHeight_->text()}}));
            if(session_.contains("pendingTwoPointRectangle"))sketchResponse(execute("sketch.twoPointRectanglePreview",{{"widthText",text},{"heightText",centerRectangleHeight_->text()}}));
        });
        connect(lineAngleValue_,&QLineEdit::textChanged,this,[this](const QString& text){
            if(session_.value("pendingLineLength").toObject().value("phase")=="locked")
                sketchResponse(execute("sketch.lineAnglePreview",{{"text",text}}));
        });
        connect(lineAngleValue_,&QLineEdit::returnPressed,this,[this]{
            if(session_.value("pendingLineLength").toObject().value("phase")=="locked")
                sketchResponse(execute("sketch.lineAngleLock",{{"text",lineAngleValue_->text()}}));
        });
        connect(centerRectangleHeight_,&QLineEdit::textChanged,this,[this](const QString& text){
            if(session_.contains("pendingCenterRectangle"))sketchResponse(execute("sketch.centerRectanglePreview",{{"widthText",dimensionEditorValue_->text()},{"heightText",text}}));
            if(session_.contains("pendingTwoPointRectangle"))sketchResponse(execute("sketch.twoPointRectanglePreview",{{"widthText",dimensionEditorValue_->text()},{"heightText",text}}));
        });
        connect(centerRectangleHeight_,&QLineEdit::returnPressed,this,[this]{
            if(session_.contains("pendingCenterRectangle"))
                sketchResponse(execute("sketch.centerRectangleAccept",{{"widthText",dimensionEditorValue_->text()},{"heightText",centerRectangleHeight_->text()}}));
            else if(session_.contains("pendingTwoPointRectangle"))
                sketchResponse(execute("sketch.twoPointRectangleAccept",{{"widthText",dimensionEditorValue_->text()},{"heightText",centerRectangleHeight_->text()}}));
        });
        auto* escape=new QShortcut(QKeySequence(Qt::Key_Escape),dimensionEditor_);escape->setContext(Qt::WidgetWithChildrenShortcut);
        connect(escape,&QShortcut::activated,this,[this]{execute(session_.contains("pendingTwoPointRectangle") ? "sketch.twoPointRectangleCancel" :
            session_.contains("pendingCenterRectangle") ? "sketch.centerRectangleCancel" :
            session_.contains("pendingCircleDiameter") ? "sketch.circleDiameterCancel" :
            session_.contains("pendingLineLength") ? "sketch.lineLengthCancel" : "sketch.dimensionCancel");});
    }
}
void AlloyWindow::showCircleDiameterEditor(const QString& text) {
    ensureSketchInlineEditor();
    dimensionEditorValue_->installEventFilter(this);
    twoPointWidthLabel_->hide();twoPointHeightLabel_->hide();centerRectangleHeight_->hide();
    lineLengthLabel_->hide();lineAngleLabel_->hide();lineAngleValue_->hide();
    dimensionEditorValue_->setReadOnly(false);
    {const QSignalBlocker block(dimensionEditorValue_);dimensionEditorValue_->setText(text);}
    dimensionEditorError_->setText(session_.value("pendingCircleDiameter").toObject().value("valid").toBool()
        ? "Enter accepts · Esc cancels" : "Enter a diameter from 0.002 to 100000 mm");
    dimensionEditor_->adjustSize();positionDimensionEditor();dimensionEditor_->show();dimensionEditor_->raise();dimensionEditorValue_->setFocus();
    dimensionEditorValue_->setCursorPosition(dimensionEditorValue_->text().size());
}
void AlloyWindow::showDimensionEditor() {
    ensureSketchInlineEditor();
    twoPointWidthLabel_->hide();twoPointHeightLabel_->hide();centerRectangleHeight_->hide();
    lineLengthLabel_->hide();lineAngleLabel_->hide();lineAngleValue_->hide();
    const auto pending=session_.value("pendingDimension").toObject();const auto units=session_.value("inputs").toObject().value("units").toString();const double scale=units=="in" ? 25.4 : 1;
    const bool driving=pending.value("driving").toBool();dimensionEditorValue_->setReadOnly(!driving);
    const bool angular=pending["kind"]=="arcSweep" || pending["kind"]=="angle" || pending["kind"]=="overallSlotAngle";
    QString shown=QString::number(pending.value(angular ? "measuredValueDeg" : "measuredValueMm").toDouble()/(angular ? 1 : scale),'g',9)+(angular ? " deg" : " "+units);
    if(!pending["parameterId"].toString().isEmpty())for(const auto& entry:document_->authored()["userParameters"].toArray())
        if(entry.toObject()["id"]==pending["parameterId"]){shown=entry.toObject()["name"].toString();break;}
    if(pending.contains("expression"))shown=pending.value("expression").toString();
    dimensionEditorValue_->setText(shown);
    const auto dimensionName=pending.value("name").toString();
    dimensionEditorError_->setText((dimensionName.isEmpty() ? QString{} : dimensionName+" · ")
        +(driving ? "Enter accepts · Esc cancels" : "Driven measurement · Enter / Esc closes"));
    dimensionEditor_->adjustSize();positionDimensionEditor();dimensionEditor_->show();dimensionEditor_->raise();dimensionEditorValue_->setFocus();dimensionEditorValue_->selectAll();
}
void AlloyWindow::positionDimensionEditor() {
    if(!dimensionEditor_)return;
    const auto circle=session_.value("pendingCircleDiameter").toObject();
    if(circle.isEmpty() && !session_.contains("pendingCenterRectangle") && !session_.contains("pendingTwoPointRectangle") && !session_.contains("pendingLineLength") && session_.value("pendingDimension").toObject().value("phase")!="editing")return;
    auto point=session_.value("pendingDimension").toObject().value("annotation").toObject();
    if(!circle.isEmpty()) {
        const auto first=session_.value("firstPoint").toObject();
        const bool twoPoint=session_.value("tool")=="twoPointCircle";
        point={{"uMm",first["uMm"].toDouble()+circle.value("diameterMm").toDouble(10)*(twoPoint ? circle["directionU"].toDouble() : 0.5)},
            {"vMm",first["vMm"].toDouble()+circle.value("diameterMm").toDouble(10)*(twoPoint ? circle["directionV"].toDouble() : 0.0)}};
    }
    if(session_.contains("pendingCenterRectangle")) {
        const auto center=session_.value("firstPoint").toObject();
        const auto pending=session_.value("pendingCenterRectangle").toObject();
        point={{"uMm",center["uMm"].toDouble()+pending.value("widthMm").toDouble(10)/2},{"vMm",center["vMm"]}};
    }
    if(session_.contains("pendingTwoPointRectangle")) {
        const auto first=session_.value("firstPoint").toObject();const auto pending=session_.value("pendingTwoPointRectangle").toObject();
        point={{"uMm",first["uMm"].toDouble()+pending.value("uSign").toInt()*pending.value("widthMm").toDouble(10)/2},
            {"vMm",first["vMm"].toDouble()+pending.value("vSign").toInt()*pending.value("heightMm").toDouble(10)/2}};
    }
    if(session_.contains("pendingLineLength")) {
        const auto first=session_.value("firstPoint").toObject();
        point={{"uMm",first["uMm"]},{"vMm",first["vMm"]}};
    }
    const auto plane=session_.value("inputs").toObject().value("plane").toString();
    const auto p=view_->projectSketchPoint(point.value("uMm").toDouble(),point.value("vMm").toDouble(),plane);
    int editorX=qRound(p.value("x").toDouble()+12);
    if(session_.contains("pendingLineLength")){
        const auto pointer=session_.value("pointerPoint").toObject();
        const auto hovered=pointer.isEmpty() ? QJsonObject{} : view_->projectSketchPoint(pointer.value("uMm").toDouble(),pointer.value("vMm").toDouble(),plane);
        const bool lineHeadsRight=hovered.isEmpty() || hovered.value("x").toDouble()>=p.value("x").toDouble();
        const int opposite=qRound(p.value("x").toDouble())-(lineHeadsRight ? dimensionEditor_->width()+16 : -16);
        if(opposite>=0 && opposite+dimensionEditor_->width()<=view_->width())editorX=opposite;
    }
    dimensionEditor_->move(std::clamp(editorX,0,std::max(0,view_->width()-dimensionEditor_->width())),
        std::clamp(qRound(p.value("y").toDouble()+12),0,std::max(0,view_->height()-dimensionEditor_->height())));
}
QJsonObject AlloyWindow::inlineEditorState() const {
    if(!dimensionEditor_)return {{"visible",false}};
    return {{"visible",dimensionEditor_->isVisible()},{"kind",session_.contains("pendingTwoPointRectangle") ? "twoPointRectangle" : session_.contains("pendingCenterRectangle") ? "centerRectangle" :
        session_.contains("pendingCircleDiameter") ? (session_.value("tool")=="twoPointCircle" ? "twoPointCircleDiameter" : "circleDiameter") : session_.contains("pendingLineLength") ? "lineLength" : "dimension"},{"heightText",centerRectangleHeight_ ? centerRectangleHeight_->text() : QString{}},
        {"text",dimensionEditorValue_->text()},{"angleText",lineAngleValue_ ? lineAngleValue_->text() : QString{}},
        {"angleVisible",lineAngleValue_ && lineAngleValue_->isVisible()},{"focusedField",lineAngleValue_ && lineAngleValue_->hasFocus() ? "angle" : dimensionEditorValue_->hasFocus() ? "length" : "none"},
        {"readOnly",dimensionEditorValue_->isReadOnly()},
        {"bounds",QJsonObject{{"x",dimensionEditor_->x()},{"y",dimensionEditor_->y()},{"width",dimensionEditor_->width()},{"height",dimensionEditor_->height()}}}};
}

void AlloyWindow::dimensionSelectionChanged() {
    if(!sketchDimensionList_ || !sketchDimensionEdit_)return;
    const auto id=sketchDimensionList_->currentData().toString();const auto units=session_.value("inputs").toObject()["units"].toString();
    const double scale=units=="in" ? 25.4 : 1;
    const QSignalBlocker block(sketchDimensionEdit_);sketchDimensionEdit_->setSuffix(" "+units);
    auto* apply=sketchPanel_->findChild<QPushButton*>("sketch.dimension.apply");
    if(apply){apply->setEnabled(false);apply->setText("Apply Dimension Value");}
    QJsonObject authored;
    for(const auto& entry:session_.value("draftSketch").toObject().value("parameters").toObject().value("dimensions").toArray())
        if(entry.toObject().value("id")==id){authored=entry.toObject();break;}
    const bool formula=authored.contains("expression");
    for(const auto& entry:session_.value("solverDiagnostics").toObject()["dimensionValues"].toArray()) {
        const auto value=entry.toObject();if(value["id"]!=id)continue;
        const bool angular=value["kind"]=="arcSweep" || value["kind"]=="angle" || value["kind"]=="overallSlotAngle";sketchDimensionEdit_->setSuffix(angular ? " deg" : " "+units);
        sketchDimensionEdit_->setValue(value[angular ? "valueDeg" : "valueMm"].toDouble()/(angular ? 1 : scale));sketchDimensionEdit_->setEnabled(value["driving"].toBool() && !formula);
        if(apply){apply->setEnabled(value["driving"].toBool());apply->setText(formula ? "Edit Expression" : "Apply Dimension Value");}
        sketchDimensionMeasure_->setText(QString("%1: %2 %3").arg(value["driving"].toBool() ? "Driving" : "Driven measurement")
            .arg(QString::number(value[angular ? "valueDeg" : "valueMm"].toDouble()/(angular ? 1 : scale),'g',8)).arg(angular ? "deg" : units)
            +(formula ? "\nExpression: "+authored.value("expression").toString() : value["driving"].toBool() ? "\nEnter a value, then Apply." : "\nRead-only: measures geometry."));return;
    }
    sketchDimensionEdit_->setEnabled(false);sketchDimensionMeasure_->setText("Select a dimension to inspect or edit it");
}

void AlloyWindow::refreshSketchControls() {
    if(session_.value("tool")!="twoTangentCircle" && tangentCircleRadius_)tangentCircleRadius_->hide();
    if(!sketchSelectionTree_ || session_.value("command")!="sketch.edit")return;
    if(auto* cue=sketchPanel_->findChild<QLabel*>("sketch.selectionIdentity")) {
        const auto selected=session_.value("selection").toObject().value("entityIds").toArray();
        QStringList labels;
        for(const auto& id:selected) {
            bool projected=false;
            for(const auto& key:{"projections","circleProjections"})for(const auto& value:session_.value("draftSketch").toObject().value("parameters").toObject().value(key).toArray())
                projected |= value.toObject().value("id")==id;
            labels.append(QString("%1 · %2").arg(projected ? "Projected" : "Authored",id.toString()));
        }
        cue->setText(labels.join('\n'));cue->setVisible(!labels.isEmpty());
    }

    if(auto* options=sketchPanel_->findChild<QWidget*>("sketch.circle.featureOptions")) {
        auto* mode=options->findChild<QComboBox*>("sketch.circle.mode");
        const int index=mode->findData(session_.value("tool").toString());
        options->setVisible(index>=0);
        if(index>=0){const QSignalBlocker block(mode);mode->setCurrentIndex(index);}
    }
    const auto conflict=session_.value("lastSolveFailure").toObject();
    if(auto* repair=sketchPanel_->findChild<QPushButton*>("sketch.conflict.select"))
        repair->setVisible(conflict.value("code")=="constraint_conflict");
    if(sketchError_ && conflict.value("code")=="constraint_conflict") {
        sketchError_->setProperty("constraintConflict",true);
        sketchError_->setText("Constraint conflict: "+conflict.value("message").toString());
        sketchError_->setMinimumHeight(sketchError_->heightForWidth(std::max(80,sketchError_->contentsRect().width())));
    } else if(sketchError_ && sketchError_->property("constraintConflict").toBool()) {
        sketchError_->setProperty("constraintConflict",false);sketchError_->clear();sketchError_->setMinimumHeight(0);
    }
    if(auto* offer=sketchPanel_->findChild<QWidget*>("sketch.dimension.offer"))
        offer->setVisible(session_.contains("pendingDrivenOffer"));
    if(auto* project=sketchPanel_->findChild<QWidget*>("sketch.projectControls")) {
        const bool active=session_.contains("pendingProject");project->setVisible(active);
        if(active)if(auto* count=project->findChild<QLabel*>("sketch.projectCount"))
            count->setText(QString("Geometry · %1 selected").arg(session_["pendingProject"].toObject()["sources"].toArray().size()));
    }
    for(auto* button:sketchPanel_->findChildren<QPushButton*>())if(button->objectName().startsWith("sketch.constraint.")) {
        const QSignalBlocker block(button);
        button->setChecked(session_.value("tool")=="constraint" && button->objectName()=="sketch.constraint."+session_.value("constraintType").toString());
    }
    if(auto* contact=sketchPanel_->findChild<QComboBox*>("sketch.tangent.contact")){
        const bool active=session_.value("tool")=="constraint" && session_.value("constraintType")=="tangent";
        contact->parentWidget()->setVisible(active);const QSignalBlocker block(contact);
        contact->setCurrentIndex(contact->findData(session_.value("tangentEndpoint").toString()));
    }
    const auto draft=session_.value("draftSketch").toObject(),selection=session_.value("selection").toObject();
    const auto units=session_.value("inputs").toObject()["units"].toString();
    refreshSplinePalette();
    const auto displayOptions=session_.value("displayOptions").toObject();
    view_->setSketchDisplayOptions(displayOptions);
    for(const auto& field:QStringList{"showProfile","showPoints","showConstructionGeometries","showProjectedGeometries","hideFullyConstrained"})if(auto* option=sketchPanel_->findChild<QCheckBox*>("sketch."+field)){
        const QSignalBlocker block(option);option->setChecked(displayOptions.value(field).toBool(field!="hideFullyConstrained"));
    }
    if(sketchShowConstraints_){const QSignalBlocker block(sketchShowConstraints_);sketchShowConstraints_->setChecked(displayOptions.value("showConstraints").toBool(true));}
    if(sketchShowDimensions_){const QSignalBlocker block(sketchShowDimensions_);sketchShowDimensions_->setChecked(displayOptions.value("showDimensions").toBool(true));}
    auto presentationSelection=selection;presentationSelection["tool"]=session_.value("tool");presentationSelection["hoveredConstraintId"]=session_.value("hoveredConstraintId");
    if(session_.value("tool")=="line"){
        const auto first=session_.value("firstPoint").toObject();
        const auto entities=draft.value("parameters").toObject().value("entities").toArray();
        if(!entities.isEmpty() && entities.last().toObject().value("type")=="line"
            && first.value("target").toObject().value("kind")=="point"
            && first.value("target").toObject().value("pointId")==entities.last().toObject().value("endPointId")){
            presentationSelection["chainLineId"]=entities.last().toObject().value("id");
            presentationSelection["chainPointId"]=entities.last().toObject().value("endPointId");
        }
    }
    const auto loopPreview=session_.value("pendingLoopOffset").toObject();
    const auto projectPreview=session_.value("pendingProject").toObject();
    const auto patternPreview=session_.value("pendingSketchPattern").toObject();
    const auto movePreview=session_.value("pendingSketchMove").toObject();
    presentationSelection["moveInteraction"]=session_.value("moveInteraction");
    if(session_["moveInteraction"].toObject()["active"].toBool())presentationSelection["entityIds"]=session_["moveInteraction"].toObject()["entityIds"];
    presentationSelection["patternInteraction"]=session_.value("patternInteraction");
    if(!patternPreview.isEmpty())presentationSelection["entityIds"]=QJsonArray{patternPreview["draft"].toObject()["parameters"].toObject()["patternGroups"].toArray().first().toObject()["sourceEntityId"]};
    for(const auto& id:session_["patternInteraction"].toObject()["pickedPointIds"].toArray()){auto ids=presentationSelection["pointIds"].toArray();if(!ids.contains(id))ids.append(id);presentationSelection["pointIds"]=ids;}
    for(const auto& id:session_["patternInteraction"].toObject()["pickedEntityIds"].toArray()){auto ids=presentationSelection["entityIds"].toArray();if(!ids.contains(id))ids.append(id);presentationSelection["entityIds"]=ids;}
    view_->decorateSketch(!movePreview.isEmpty() ? movePreview["draft"].toObject() : !patternPreview.isEmpty() ? patternPreview["draft"].toObject() : !projectPreview.isEmpty() ? projectPreview["previewDraft"].toObject()
            : loopPreview["valid"].toBool() ? loopPreview["previewDraft"].toObject() : draft,
        presentationSelection,patternPreview.isEmpty() ? session_.value("solverDiagnostics").toObject() : patternPreview["diagnostics"].toObject(),units,session_.value("pendingDimension").toObject());
    if(sketchCurveEntry_){const auto tool=session_["tool"].toString();sketchCurveEntry_->setVisible(tool=="circle" || tool=="centerArc" || tool=="threePointArc");}
    if(sketchMirrorControls_){
        const bool active=session_.value("tool")=="mirror";sketchMirrorControls_->setVisible(active);
        if(active){
            const auto chosen=session_.value("mirrorSelection").toObject();const auto curves=chosen["sourceEntityIds"].toArray(),points=chosen["pointIds"].toArray();
            const auto axisId=chosen["axisEntityId"].toString();
            if(sketchMirrorSummary_){
                sketchMirrorSummary_->setText(QString("%1 objects · %2 curves · %3 distinct points\nMirror Line · %4")
                    .arg(curves.size()+points.size()).arg(curves.size()).arg(points.size()).arg(axisId.isEmpty() ? "choose a line" : axisId.left(8)));
                sketchMirrorSummary_->setMinimumHeight(std::max(sketchMirrorSummary_->sizeHint().height(),
                    sketchMirrorSummary_->heightForWidth(sketchMirrorSummary_->width())));
            }
            if(sketchMirrorRows_){
                sketchMirrorRows_->clear();QMap<QString,QString> types;
                for(const auto& value:draft["parameters"].toObject()["entities"].toArray()){
                    const auto entity=value.toObject();types[entity["id"].toString()]=entity["type"].toString();
                }
                for(int i=0;i<curves.size();++i){const auto id=curves[i].toString();sketchMirrorRows_->addItem(QString("Curve %1 · %2 · %3").arg(i+1).arg(types.value(id)).arg(id.left(8)));}
                for(int i=0;i<points.size();++i)sketchMirrorRows_->addItem(QString("Point %1 · %2").arg(i+1).arg(points[i].toString().left(8)));
                sketchMirrorRows_->addItem(axisId.isEmpty() ? "Mirror Line · not selected" : "Mirror Line · "+axisId.left(8));
            }
            if(auto* button=sketchMirrorControls_->findChild<QPushButton*>("sketch.mirror.role.objects")){const QSignalBlocker block(button);button->setChecked(chosen["role"]!="axis");}
            if(auto* button=sketchMirrorControls_->findChild<QPushButton*>("sketch.mirror.role.axis")){const QSignalBlocker block(button);button->setChecked(chosen["role"]=="axis");}
            if(auto* button=sketchMirrorControls_->findChild<QPushButton*>("sketch.mirror.accept"))button->setEnabled(session_.contains("pendingSketchMirror"));
        }
    }
    if(sketchUnderconstrained_){
        const auto rows=session_.value("solverDiagnostics").toObject().value("underconstrainedEntities").toArray();
        const QSignalBlocker block(sketchUnderconstrained_);
        const bool visible=session_.value("findUnderconstrained").toBool();sketchUnderconstrained_->setVisible(visible);
        sketchUnderconstrained_->setHeaderLabel(QString("Under-Constrained · %1 entities").arg(rows.size()));
        QSet<QString> live;
        for(const auto& value:rows){
            const auto row=value.toObject();const auto id=row.value("entityId").toString();live.insert(id);QTreeWidgetItem* item=nullptr;
            for(int i=0;i<sketchUnderconstrained_->topLevelItemCount();++i)if(sketchUnderconstrained_->topLevelItem(i)->data(0,Qt::UserRole)==id)item=sketchUnderconstrained_->topLevelItem(i);
            if(!item){item=new QTreeWidgetItem(sketchUnderconstrained_);item->setData(0,Qt::UserRole,id);}
            const auto type=row.value("type").toString();
            item->setText(0,type.first(1).toUpper()+type.sliced(1)+" · "+id.left(8)+(row.value("analysisKnown").toBool() ? "" : " · analysis limited"));
            item->setToolTip(0,"Select to highlight and zoom · "+id);item->setHidden(false);
            item->setSelected(selection.value("entityIds").toArray().contains(id));
        }
        for(int i=0;i<sketchUnderconstrained_->topLevelItemCount();++i){auto* item=sketchUnderconstrained_->topLevelItem(i);if(!live.contains(item->data(0,Qt::UserRole).toString())){item->setSelected(false);item->setHidden(true);}}
    }
    const bool changed=draft!=sketchWidgetDraft_,selected=selection!=sketchWidgetSelection_,unitChanged=units!=sketchWidgetUnits_;
    if(!changed && !selected && !unitChanged)return;
    const auto parameters=draft["parameters"].toObject();const double scale=units=="in" ? 25.4 : 1;
    QMap<QString,QJsonObject> points;QMap<QString,int> pointNumbers;
    QMap<QString,QStringList> relations;
    for(const auto& entry:parameters["constraints"].toArray()) {
        const auto constraint=entry.toObject();const auto type=constraint["type"]=="pointOnCurve" ? QString("coincident") :
            (constraint["type"]=="arcTangent" || constraint["type"]=="circleTangent" || constraint["type"]=="arcEndpointArcTangent" || constraint["type"]=="arcEndpointCircleTangent" || constraint["type"]=="arcCircleTangent" || constraint["type"]=="arcArcTangent") ? QString("tangent") :
            constraint["type"]=="supportLine" ? QString("support line (internal)") : constraint["type"].toString();
        for(const auto& id:constraint["entityIds"].toArray())relations[id.toString()].append((type=="fixedLine" || type=="fixedCircle" || type=="fixedArc") ? QString("Fixed") : type.first(1).toUpper()+type.sliced(1));
        for(const auto& id:constraint["pointIds"].toArray())relations[id.toString()].append((type=="fixedLine" || type=="fixedCircle" || type=="fixedArc") ? QString("Fixed") : type.first(1).toUpper()+type.sliced(1));
    }
    QMap<QString,QString> entityRoles;
    for(const auto& row:session_.value("solverDiagnostics").toObject().value("entityRoles").toArray()){
        const auto value=row.toObject();entityRoles.insert(value.value("entityId").toString(),value.value("role").toString());
    }
    if(changed || unitChanged) {
        const QSignalBlocker block(sketchSelectionTree_);
        auto rowDraft=draft;
        if(parameters.contains("projections") || parameters.contains("circleProjections") || parameters.contains("pointProjections")) {
            // An unavailable source must not turn a controls refresh into an
            // exception. The command/solve path reports the missing reference.
            try {rowDraft=SketchGeometry::expandedProjectionFeature(draft,session_.value("projectionContext").toObject());}
            catch(const std::invalid_argument&) {}
        }
        const auto presented=SketchGeometry::chamferPresentation(rowDraft).value("parameters").toObject();
        const auto pointEntries=presented.value("points").toArray(),entityEntries=presented.value("entities").toArray();
        auto* pointGroup=sketchSelectionTree_->topLevelItemCount()==2 ? sketchSelectionTree_->topLevelItem(0) : nullptr;
        auto* lineGroup=sketchSelectionTree_->topLevelItemCount()==2 ? sketchSelectionTree_->topLevelItem(1) : nullptr;
        bool accessibleRowsChanged=false,accessibleLabelsChanged=false;
        if(!pointGroup || !lineGroup) {
            pointGroup=new QTreeWidgetItem(sketchSelectionTree_,{"Points"});pointGroup->setFlags(pointGroup->flags() & ~Qt::ItemIsSelectable);
            lineGroup=new QTreeWidgetItem(sketchSelectionTree_,{"Curves"});lineGroup->setFlags(lineGroup->flags() & ~Qt::ItemIsSelectable);
            accessibleRowsChanged=true;
        }
        // Native accessibility clients can hold a row while an edit inserts or
        // removes geometry. Keep each item's identity tied to its authored ID;
        // retiring a row only hides it until Undo restores that same ID.
        auto rowForId=[&](QTreeWidgetItem* group,const QString& id) {
            for(int i=0;i<group->childCount();++i) {
                auto* item=group->child(i);
                if(item->data(0,Qt::UserRole+1).toString()==id)return item;
            }
            accessibleRowsChanged=true;
            return new QTreeWidgetItem(group);
        };
        QSet<QString> livePoints,liveEntities;
        const auto pointCoordinate=[scale](double mm){return QString::number((std::abs(mm)<1e-9 ? 0.0 : mm)/scale,'g',5);};
        int index=0;
        for(const auto& entry:pointEntries) {
            const auto point=entry.toObject();const auto id=point["id"].toString();points[id]=point;pointNumbers[id]=++index;livePoints.insert(id);
            auto* item=rowForId(pointGroup,id);
            QString label=QString("P%1  (%2, %3) %4").arg(index).arg(pointCoordinate(point["uMm"].toDouble())).arg(pointCoordinate(point["vMm"].toDouble())).arg(units);
            if(relations.contains(id))label+=" · "+relations[id].join(", ");
            if(item->text(0)!=label){item->setText(0,label);accessibleLabelsChanged=true;}
            item->setData(0,Qt::UserRole,"point");item->setData(0,Qt::UserRole+1,id);item->setSelected(selection["pointIds"].toArray().contains(id));
            item->setFlags(item->flags()|Qt::ItemIsEnabled|Qt::ItemIsSelectable);
            if(item->isHidden()){item->setHidden(false);accessibleRowsChanged=true;}
        }
        index=0;
        for(const auto& entry:entityEntries) {
            const auto entity=entry.toObject();if(entity["type"]=="point")continue;
            const auto id=entity["id"].toString();liveEntities.insert(id);
            auto* item=rowForId(lineGroup,id);
            QString label=entity["type"]=="ellipse" ? QString("Ellipse %1 · full axes in Construction").arg(++index) :
                entity["type"]=="circle" ? QString("Circle %1  ·  P%2 · R%3").arg(++index).arg(pointNumbers.value(entity["centerPointId"].toString())).arg(entity["radiusMm"].toDouble()/scale) : QString("%1 %2  ·  P%3 → P%4").arg(entity["type"]=="arc" ? "Arc" : "Line").arg(++index).arg(pointNumbers.value(entity["startPointId"].toString())).arg(pointNumbers.value(entity["endPointId"].toString()));
            if(entity["type"]=="conic")label=QString("Conic %1 · Rho %2").arg(index).arg(entity["rho"].toDouble(),0,'g',6);
            if(entity["type"]=="fitSpline")label=QString("Fit Point Spline %1 · Degree 5").arg(index);
            if(entity["type"]=="controlSpline")label=QString("Control Point Spline %1 · Degree %2 (maximum %3)").arg(index).arg(std::min(entity["maximumDegree"].toInt(),int(entity["pointIds"].toArray().size())-1)).arg(entity["maximumDegree"].toInt());
            const auto role=entityRoles.value(id);
            label+=role=="fixed" ? " · Fixed" : role=="fullyConstrained" ? " · Fully constrained" : " · Under-constrained";
            if(entity["construction"].toBool())label+=" · Construction";
            if(entity["centerline"].toBool())label+=" · Centerline";
            auto relationLabels=relations.value(id);
            if(role=="fixed")relationLabels.removeAll("Fixed");
            if(!relationLabels.isEmpty())label+=" · "+relationLabels.join(", ");
            if(item->text(0)!=label){item->setText(0,label);accessibleLabelsChanged=true;}
            item->setData(0,Qt::UserRole,"entity");item->setData(0,Qt::UserRole+1,id);item->setSelected(selection["entityIds"].toArray().contains(id));
            item->setFlags(item->flags()|Qt::ItemIsEnabled|Qt::ItemIsSelectable);
            if(item->isHidden()){item->setHidden(false);accessibleRowsChanged=true;}
        }
        auto retireRows=[&](QTreeWidgetItem* group,const QSet<QString>& live) {
            for(int i=0;i<group->childCount();++i) {
                auto* item=group->child(i);
                if(live.contains(item->data(0,Qt::UserRole+1).toString()))continue;
                item->setSelected(false);
                item->setFlags(item->flags() & ~(Qt::ItemIsEnabled|Qt::ItemIsSelectable));
                if(!item->isHidden()){item->setHidden(true);accessibleRowsChanged=true;}
            }
        };
        retireRows(pointGroup,livePoints);retireRows(lineGroup,liveEntities);
        pointGroup->setExpanded(true);lineGroup->setExpanded(true);
        if(accessibleRowsChanged || accessibleLabelsChanged)if(auto* accessible=QAccessible::queryAccessibleInterface(sketchSelectionTree_))
            if(auto* table=accessible->tableInterface()) {
                // QTreeWidget hides rows without a model insertion/removal event.
                // Qt's accessible tree caches child interfaces by visible index;
                // hide/reveal or changed labels can otherwise report stale rows.
                QAccessibleTableModelChangeEvent reset(sketchSelectionTree_,QAccessibleTableModelChangeEvent::ModelReset);
                table->modelChange(&reset);
            }
    } else if(selected) {
        const QSignalBlocker block(sketchSelectionTree_);
        for(int group=0;group<sketchSelectionTree_->topLevelItemCount();++group) {
            auto* parent=sketchSelectionTree_->topLevelItem(group);
            for(int i=0;i<parent->childCount();++i) {
                auto* item=parent->child(i);const auto field=item->data(0,Qt::UserRole).toString()=="point" ? "pointIds" : "entityIds";
                item->setSelected(selection[field].toArray().contains(item->data(0,Qt::UserRole+1).toString()));
            }
        }
    }
    QMap<QString,QJsonObject> values;const auto diagnostics=session_.value("solverDiagnostics").toObject();
    for(const auto& entry:diagnostics["dimensionValues"].toArray()){const auto value=entry.toObject();values[value["id"].toString()]=value;}
    if(changed || unitChanged) {
        const auto previous=sketchDimensionList_->currentData();const QSignalBlocker block(sketchDimensionList_);
        QVector<QPair<QString,QVariant>> rows;
        for(const auto& entry:parameters["dimensions"].toArray()) {
            const auto dimension=entry.toObject();const auto measured=values.value(dimension["id"].toString());const auto kind=dimension["kind"].toString();
            const bool angular=kind=="arcSweep" || kind=="angle" || kind=="overallSlotAngle";
            rows.append({(dimension.value("name").toString().isEmpty() ? QString{} : dimension.value("name").toString()+": ")+QString("%1 %2 %3 · %4").arg(kind.first(1).toUpper()+kind.sliced(1))
                .arg(QString::number(measured[angular ? "valueDeg" : "valueMm"].toDouble()/(angular ? 1 : scale),'g',6)).arg(angular ? "deg" : units).arg(dimension["driving"].toBool() ? "Driving" : "Driven"),dimension["id"].toString()});
        }
        if(rows.isEmpty())rows.append({"No dimensions",QVariant{}});
        const int common=std::min(sketchDimensionList_->count(),static_cast<int>(rows.size()));
        for(int i=0;i<common;++i) {
            if(sketchDimensionList_->itemText(i)!=rows[i].first)sketchDimensionList_->setItemText(i,rows[i].first);
            if(sketchDimensionList_->itemData(i)!=rows[i].second)sketchDimensionList_->setItemData(i,rows[i].second);
        }
        while(sketchDimensionList_->count()>rows.size())sketchDimensionList_->removeItem(sketchDimensionList_->count()-1);
        for(int i=common;i<rows.size();++i)sketchDimensionList_->addItem(rows[i].first,rows[i].second);
        const int previousIndex=sketchDimensionList_->findData(previous);if(previousIndex>=0)sketchDimensionList_->setCurrentIndex(previousIndex);
        dimensionSelectionChanged();
    }
    if(selected) {
        const auto explicitId=selection["dimensionId"].toString();
        const auto entityIds=selection["entityIds"].toArray();
        const auto pointIds=selection["pointIds"].toArray();
        QString selectedId;
        if(!explicitId.isEmpty())selectedId=explicitId;
        else if(entityIds.size()==1 && pointIds.isEmpty()) {
            const auto previous=sketchDimensionList_->currentData().toString();
            QJsonArray linePoints;
            for(const auto& entry:parameters["entities"].toArray()) {
                const auto entity=entry.toObject();
                if(entity["id"]==entityIds[0] && entity["type"]=="line") {
                    linePoints={entity["startPointId"],entity["endPointId"]};break;
                }
            }
            bool driving=false;
            for(const auto& entry:parameters["dimensions"].toArray()) {
                const auto dimension=entry.toObject();const auto dimensionPoints=dimension["pointIds"].toArray();
                const bool matchesLine=linePoints.size()==2 && dimensionPoints.size()==2
                    && ((dimensionPoints[0]==linePoints[0] && dimensionPoints[1]==linePoints[1])
                        || (dimensionPoints[0]==linePoints[1] && dimensionPoints[1]==linePoints[0]));
                if(dimension["entityId"]!=entityIds[0] && !matchesLine)continue;
                const auto id=dimension["id"].toString();
                if(id==previous){selectedId=id;break;}
                if(selectedId.isEmpty() || (!driving && dimension["driving"].toBool())) {
                    selectedId=id;driving=dimension["driving"].toBool();
                }
            }
        }
        if(!explicitId.isEmpty() || (entityIds.size()==1 && pointIds.isEmpty())) {
            const QSignalBlocker block(sketchDimensionList_);
            sketchDimensionList_->setCurrentIndex(sketchDimensionList_->findData(selectedId));
            dimensionSelectionChanged();
        }
    }
    const QSignalBlocker block(sketchDimensionValue_);
    const bool targetsChanged=selection["pointIds"]!=sketchWidgetSelection_["pointIds"] || selection["entityIds"]!=sketchWidgetSelection_["entityIds"];
    if(targetsChanged) {
        try {const auto targets=sketchDimensionTargets({});if(targets.contains("entityIds")) {
            const QSignalBlocker kindBlock(sketchDimensionKind_);sketchDimensionKind_->setCurrentIndex(sketchDimensionKind_->findData(targets.value("kind").toString("angle")));
        }else if(targets.contains("entityId") && targets["pointIds"].toArray().size()==1) {
            const QSignalBlocker kindBlock(sketchDimensionKind_);sketchDimensionKind_->setCurrentIndex(sketchDimensionKind_->findData("pointLineDistance"));
        }else if(targets.contains("entityId")) {
            QString type;for(const auto& value:parameters["entities"].toArray())if(value.toObject()["id"]==targets["entityId"])type=value.toObject()["type"].toString();
            const QSignalBlocker kindBlock(sketchDimensionKind_);sketchDimensionKind_->setCurrentIndex(sketchDimensionKind_->findData(type=="circle" ? "diameter" : "radius"));
        }}catch(const std::invalid_argument&){}
    }
    const auto measureKind=sketchDimensionKind_->currentData().toString();const bool angular=measureKind=="arcSweep" || measureKind=="angle";sketchDimensionValue_->setSuffix(angular ? " deg" : " "+units);
    try {auto targets=sketchDimensionTargets({});if(measureKind=="angle")targets["raySigns"]=angleRaySigns(targets["entityIds"].toArray(),{});sketchDimensionValue_->setValue(sketchDimensionMeasure(targets,measureKind)/(angular ? 1 : scale));}catch(const std::invalid_argument&){}
    sketchWidgetDraft_=draft;sketchWidgetSelection_=selection;sketchWidgetUnits_=units;
}

void AlloyWindow::showCurveEntry() {
    if(session_.value("command")!="sketch.edit")return;
    const auto tool=session_.value("tool").toString();if(tool!="circle" && tool!="centerArc" && tool!="threePointArc")return;
    auto* dialog=new QDialog(this);dialog->setAttribute(Qt::WA_DeleteOnClose);dialog->setObjectName("curveEntry");
    dialog->setWindowTitle(tool=="circle" ? "Center Diameter Circle" : tool=="centerArc" ? "Center Point Arc" : "3-Point Arc");
    const auto sessionId=session_["id"].toString(),units=session_["inputs"].toObject()["units"].toString();const double scale=units=="in" ? 25.4 : 1;
    auto* layout=new QVBoxLayout(dialog);auto* form=new QFormLayout;QMap<QString,QDoubleSpinBox*> fields;
    const QStringList keys=tool=="circle" ? QStringList{"centerX","centerY","diameter"} : tool=="centerArc" ? QStringList{"centerX","centerY","radius","startAngleDeg","sweepAngleDeg"} : QStringList{"startX","startY","endX","endY","throughX","throughY"};
    const QMap<QString,QString> names{{"centerX","Center X"},{"centerY","Center Y"},{"diameter","Diameter"},{"radius","Radius"},{"startAngleDeg","Start angle"},{"sweepAngleDeg","Signed sweep"},
        {"startX","Start X"},{"startY","Start Y"},{"endX","End X"},{"endY","End Y"},{"throughX","On-arc X"},{"throughY","On-arc Y"}};
    const auto first=session_.value("firstPoint").toObject(),second=session_.value("secondPoint").toObject();
    for(const auto& key:keys) {
        auto* value=new QDoubleSpinBox;value->setDecimals(6);value->setRange(-100000,100000);value->setObjectName("sketch.curve."+key);
        const bool angle=key.endsWith("Deg");value->setSuffix(angle ? " deg" : " "+units);
        double seed=0;
        if(key=="centerX" || key=="startX")seed=first.value("uMm").toDouble(tool=="threePointArc" ? 5 : 0);
        else if(key=="centerY" || key=="startY")seed=first["vMm"].toDouble();
        else if(key=="endX")seed=second.value("uMm").toDouble(0);
        else if(key=="endY")seed=second.value("vMm").toDouble(5);
        else if(key=="diameter")seed=10;else if(key=="radius")seed=5;else if(key=="sweepAngleDeg")seed=90;
        else if(key=="throughX" || key=="throughY")seed=5/std::sqrt(2.0);
        value->setValue(seed/(angle ? 1 : scale));form->addRow(names[key],value);fields[key]=value;
    }
    layout->addLayout(form);auto* error=new QLabel;error->setWordWrap(true);layout->addWidget(error);
    auto* buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);layout->addWidget(buttons);
    connect(buttons,&QDialogButtonBox::rejected,dialog,&QDialog::reject);
    connect(buttons,&QDialogButtonBox::accepted,dialog,[this,dialog,fields,units,tool,sessionId,error]{
        QJsonObject args{{"units",units},{"session",sessionId}};for(auto it=fields.begin();it!=fields.end();++it)args[it.key()]=it.value()->value();
        if(tool!="circle")args["mode"]=tool=="centerArc" ? "center" : "threePoint";
        const auto response=execute(tool=="circle" ? "sketch.addCircle" : "sketch.addArc",args);sketchResponse(response);
        if(response["ok"].toBool())dialog->accept();else error->setText(response["error"].toObject()["message"].toString());
    });
    dialog->open();
}

